// The existing Form 1099-Q box relationships and source choices, in native order.
fn q1099_issue(v: &Q1099) -> Option<ValidationIssue> {
    let boxes = v.account.boxes();
    if boxes.is_some_and(|(earnings, basis)| {
        i128::from(earnings) + i128::from(basis) != i128::from(v.gross)
    }) {
        return Some(ValidationIssue::new("Q1099_BOXES_DO_NOT_ADD_UP").at_field("gross"));
    }
    let parts = match &v.transfer {
        Q1099Transfer::Withdrawal { redeposited, .. } => *redeposited,
        Q1099Transfer::TrusteeTransfer { taxable_part } => *taxable_part,
        _ => 0,
    };
    if parts > v.gross {
        let issue = ValidationIssue::new("Q1099_PART_ABOVE_GROSS");
        return Some(match v.transfer {
            Q1099Transfer::Withdrawal { .. } => issue.at_field("redeposited").in_field("transfer"),
            Q1099Transfer::TrusteeTransfer { .. } => {
                issue.at_field("taxable_part").in_field("transfer")
            }
            _ => issue.at_field("gross"),
        });
    }
    let qtp = matches!(v.account, EducationAccount::Qtp { .. });
    match &v.transfer {
        Q1099Transfer::RothIra { .. } if !qtp => {
            Some(ValidationIssue::new("Q1099_ROTH_ROLLOVER_NOT_529").at_field("account"))
        }
        Q1099Transfer::RothIra { .. } if !matches!(v.beneficiary, Q1099Beneficiary::Recipient) => {
            Some(ValidationIssue::new("Q1099_ROTH_ROLLOVER_NOT_STUDENT").at_field("beneficiary"))
        }
        Q1099Transfer::RothIra { .. } if boxes.is_some_and(|(earnings, _)| earnings < 0) => Some(
            ValidationIssue::new("Q1099_ROTH_ROLLOVER_LOSS")
                .at_field("earnings")
                .in_field("account"),
        ),
        Q1099Transfer::ExcessThisYear
        | Q1099Transfer::ExcessLastYear
        | Q1099Transfer::ProhibitedTransaction
            if qtp =>
        {
            Some(ValidationIssue::new("Q1099_CODE_NOT_COVERDELL").at_field("transfer"))
        }
        Q1099Transfer::ExcessThisYear | Q1099Transfer::ExcessLastYear if boxes.is_none() => Some(
            ValidationIssue::new("Q1099_EXCESS_NEEDS_BOXES")
                .at_field("amounts")
                .in_field("account"),
        ),
        _ => None,
    }
}
// The existing SavingsBonds source, amount and issue-date checks, in native order.
fn savings_bonds_issue(v: &SavingsBonds) -> Option<ValidationIssue> {
    if v.interest_statement <= 0 {
        Some(ValidationIssue::new("SAVINGS_BONDS_SOURCE_INVALID").at_field("interest_statement"))
    } else if v.redemption_interest > v.proceeds {
        Some(
            ValidationIssue::new("SAVINGS_BONDS_INTEREST_ABOVE_PROCEEDS")
                .at_field("redemption_interest"),
        )
    } else if v.earliest_issue_date < crate::year_constants::SAVINGS_BOND_FIRST_ISSUE_DATE {
        Some(
            ValidationIssue::new("SAVINGS_BONDS_ISSUED_BEFORE_1990")
                .at_field("earliest_issue_date"),
        )
    } else if v.earliest_issue_date > crate::year_constants::TAX_YEAR_END_DATE {
        Some(
            ValidationIssue::new("SAVINGS_BONDS_ISSUED_AFTER_2026").at_field("earliest_issue_date"),
        )
    } else {
        None
    }
}

pub(crate) fn dividend_record(v: &Div1099) -> FederalDividend {
    let mut data = FederalDividend {
        ordinary: v.ordinary,
        qualified: v.qualified,
        section199a: ReitDividends::None,
        capital_distributions: 0,
        collectible_distributions: 0,
        unrecaptured_distributions: 0,
        section_1202_gain: 0,
        section_1202_exclusion: None,
        withholding: 0,
        special: DividendSpecial::NoneOfThese,
        exempt_dividends: 0,
        private_activity_dividends: 0,
        foreign_tax: 0,
        after_death: v.answers.after_death.clone(),

        section_897_ordinary: 0,
        section_897_capital: 0,
        foreign_country: alloc::string::String::new(),

        nominee: v.nominee.clone(),
        capital_returns: v.capital_returns.clone(),
        nondividend_distributions: v.more.nondividend_distributions,
        cash_liquidation: v.more.cash_liquidation,
        noncash_liquidation: v.more.noncash_liquidation,
    };
    let DivMore {
        capital_distributions,
        unrecaptured_distributions,
        collectible_distributions,
        section_1202_gain,
        section_1202_exclusion,
        withholding,
        section199a,
        foreign_tax,
        exempt_dividends,
        private_activity_dividends,
        special,
        ..
    } = &v.more;
    data.section_1202_gain = *section_1202_gain;
    data.section_1202_exclusion = *section_1202_exclusion;
    data.capital_distributions = *capital_distributions;
    data.unrecaptured_distributions = *unrecaptured_distributions;
    data.collectible_distributions = *collectible_distributions;
    data.withholding = *withholding;
    // The save holds the answer present with box 5 (DIV_REIT_ELIGIBILITY_NEEDED).
    data.section199a = match (*section199a, v.answers.reit_eligible) {
        (0, _) => ReitDividends::None,
        (amount, eligible) => ReitDividends::Reported {
            amount,
            eligible: eligible
                .expect("positive Section 199A dividends require native eligibility admission"),
        },
    };
    data.exempt_dividends = *exempt_dividends;
    data.private_activity_dividends = *private_activity_dividends;
    data.foreign_tax = *foreign_tax;
    data.special = *special;
    data.section_897_ordinary = v.more.section_897_ordinary;
    data.section_897_capital = v.more.section_897_capital;
    data.foreign_country = v.more.foreign_country.clone();
    data
}

