// FederalUnemployment field for field; ordinary is No exactly when the
// page's special checkbox is checked (convention: a confirmation is a
// branch, not a question).
fn unemployment_record(v: &Form1099G) -> FederalUnemployment {
    let mut data = FederalUnemployment {
        amount: v.amount,
        withholding: v.withholding,
        repayments: Vec::new(),
        ordinary: true,
        taxable_grants: 0,
        agriculture_payment: 0,
        agriculture_farm: None,
        grant_use: None,
        rtaa: 0,
        market_gain: 0,
        family_leave: 0,
        family_leave_includes_medical: false,
    };
    let Form1099GMore {
        rtaa,
        taxable_grants,
        agriculture_payment,
        agriculture_farm,
        grant_use,
        market_gain,
        family_leave,
        family_leave_medical,
        repayments,
        special,
    } = &v.more;
    data.rtaa = *rtaa;
    data.taxable_grants = *taxable_grants;
    data.agriculture_payment = *agriculture_payment;
    data.agriculture_farm = *agriculture_farm;
    data.grant_use = grant_use.as_ref().map(crate::GrantUse::record);
    data.market_gain = *market_gain;
    data.family_leave = *family_leave;
    data.family_leave_includes_medical = *family_leave_medical;
    data.repayments = repayments.clone();
    data.ordinary = !*special;
    data
}
// Pure mappings preserve printed facts and supplemental records separately.
fn prepare_cooperative_source_ids(
    draft: &mut FederalDraft,
    accepted_draft: &FederalDraft,
) -> Result<(), (i64, ValidationIssue)> {
    for index in 0..draft.income.len() {
        let eligible = crate::cooperative::eligible_activities(draft, draft.income[index].owner);
        let entry = &mut draft.income[index];
        let FederalIncome::Cooperative { data } = &mut entry.income else {
            continue;
        };
        if data.allocations.is_empty() {
            data.allocations.push(crate::cooperative::automatic(
                data,
                (eligible.len() == 1).then(|| eligible[0]),
            ));
        }
        if eligible.len() == 1 {
            for a in &mut data.allocations {
                if a.activity.is_none() {
                    a.activity = Some(eligible[0]);
                }
            }
            if data.credit_facts.activity.is_none() {
                data.credit_facts.activity = Some(eligible[0]);
            }
            for item in &mut data.credit_facts.other {
                if item.activity.is_none() {
                    item.activity = Some(eligible[0]);
                }
            }
        }
        let accepted =
            accepted_draft.income.iter().find(|e| e.id == entry.id).into_iter().flat_map(|e| {
                match &e.income {
                    FederalIncome::Cooperative { data } => {
                        data.allocations.iter().map(|a| a.id).collect::<Vec<_>>()
                    }
                    _ => Vec::new(),
                }
            });
        assign_record_ids(
            data.allocations.iter_mut().map(|a| &mut a.id),
            accepted,
            &mut draft.next_id,
        )
        .map_err(|(key, _, index)| {
            (entry.id, ValidationIssue::new(key).at_list_item("allocations", index))
        })?;
    }
    Ok(())
}

fn project_cooperative_issue(mut issue: ValidationIssue, automatic: bool) -> ValidationIssue {
    if automatic && issue.has_field_prefix(&["allocations"]) {
        issue = issue.at_field("allocations");
    }
    for field in [
        "section_199a_g",
        "qualified_payments",
        "qualified_items",
        "sstb_items",
        "allocations",
        "credit_facts",
        "box12_text",
    ] {
        issue = issue.map_field_prefix(&[field], &["more", field]);
    }
    issue
}
fn project_estate_issue(issue: ValidationIssue) -> ValidationIssue {
    issue.map_field_prefix(&["activities"], &["business"])
}
fn submitted_source_issue(
    id: i64,
    issue: ValidationIssue,
    origins: &[(i64, usize, bool)],
) -> ValidationIssue {
    let Some((_, index, _)) = origins.iter().find(|(source, _, _)| *source == id) else {
        return ValidationIssue::new(issue.key);
    };
    submitted_data_answer_issue(issue, *index)
}
fn submitted_graph_issue(
    failure: (i64, ValidationIssue),
    origins: &[(i64, usize, bool)],
    cooperative: bool,
) -> ValidationIssue {
    let (id, issue) = failure;
    let Some((_, index, automatic)) = origins.iter().find(|(source, _, _)| *source == id) else {
        // A retained source outside this request has no editable submitted row.
        return ValidationIssue::new(issue.key);
    };
    let issue = if cooperative {
        project_cooperative_issue(issue, *automatic)
    } else {
        project_estate_issue(issue)
    };
    issue.in_field("document").in_list("documents", *index).in_field("documents")
}
fn preview_graph_issue(
    failure: (i64, ValidationIssue),
    bound_id: i64,
    cooperative: bool,
    automatic: bool,
) -> ValidationIssue {
    let (id, issue) = failure;
    if id != bound_id {
        return ValidationIssue::new(issue.key);
    }
    let issue = if cooperative {
        project_cooperative_issue(issue, automatic)
    } else {
        project_estate_issue(issue)
    };
    issue.in_field("document")
}
fn is_adjustment_document(document: &IncomeDocument) -> bool {
    matches!(
        document,
        IncomeDocument::Form8606(_)
            | IncomeDocument::Qcd(_)
            | IncomeDocument::SocialLumpSums(_)
            | IncomeDocument::MissedRmd(_)
            | IncomeDocument::RothHistory(_)
    )
}

