// The refund's federal deduction history. `SeveralYears` (a placeholder the
// page cannot yet detail) is stored as a structurally valid but deliberately
// incomplete IncomeTaxMultiplePriorYears record (allocation_complete false),
// so the estimate leaves the refund out with a notice (unknowns::supported)
// instead of the page rejecting the save.
fn refund_history(v: &Refund1099G) -> TaxRefundHistory {
    match &v.deducted {
        RefundDeduction::StandardDeduction => TaxRefundHistory::NotDeducted,
        RefundDeduction::SalesTax => TaxRefundHistory::SalesTax,
        RefundDeduction::IncomeTax {
            income_paid,
            salt_paid,
            salt_deducted,
            itemized,
            standard,
            sales_available,
            property_refunded,
        } => TaxRefundHistory::IncomeTax {
            deduction_year: v.year,
            income_paid: *income_paid,
            sales_available: *sales_available,
            salt_paid: *salt_paid,
            salt_deducted: *salt_deducted,
            itemized: *itemized,
            standard: *standard,
            overall_limit: None,
            property_refunded: *property_refunded,
            ordinary: true,
        },
        RefundDeduction::BusinessExpense { business } => {
            TaxRefundHistory::BusinessExpense { business: *business }
        }
        RefundDeduction::SeveralYears => TaxRefundHistory::IncomeTaxMultiplePriorYears {
            years: alloc::vec![
                TaxRefundYearPayment {
                    payment_year: 2018,
                    payment_for_refunded_return: 1,
                    income_paid: 1,
                    sales_available: 0,
                    salt_paid: 1,
                    salt_deducted: 1,
                    itemized: 1,
                    standard: 0,
                    overall_limit: None,
                    ordinary: false,
                },
                TaxRefundYearPayment {
                    payment_year: 2019,
                    payment_for_refunded_return: 1,
                    income_paid: 1,
                    sales_available: 0,
                    salt_paid: 1,
                    salt_deducted: 1,
                    itemized: 1,
                    standard: 0,
                    overall_limit: None,
                    ordinary: false,
                },
            ],
            allocation_complete: false,
        },
    }
}
// The reverse of refund_history: only the ordinary single-year deduction
// round-trips onto the page; NotDeducted/SalesTax/SeveralYears each collapse
// onto their own branch. A record from IncomeTaxPriorYearsAndCurrent cannot
// reach this page (M3-P3 never creates one) and reopens as SeveralYears.
fn refund_deduction(history: &TaxRefundHistory) -> (i32, RefundDeduction) {
    match history {
        TaxRefundHistory::NotDeducted => (2025, RefundDeduction::StandardDeduction),
        TaxRefundHistory::SalesTax => (2025, RefundDeduction::SalesTax),
        TaxRefundHistory::BusinessExpense { business } => {
            (2025, RefundDeduction::BusinessExpense { business: *business })
        }
        TaxRefundHistory::IncomeTax {
            deduction_year,
            income_paid,
            sales_available,
            salt_paid,
            salt_deducted,
            itemized,
            standard,
            property_refunded,
            ..
        } => (
            *deduction_year,
            RefundDeduction::IncomeTax {
                income_paid: *income_paid,
                sales_available: *sales_available,
                salt_paid: *salt_paid,
                salt_deducted: *salt_deducted,
                itemized: *itemized,
                standard: *standard,
                property_refunded: *property_refunded,
            },
        ),
        TaxRefundHistory::IncomeTaxMultiplePriorYears { .. }
        | TaxRefundHistory::IncomeTaxPriorYearsAndCurrent { .. } => {
            (2025, RefundDeduction::SeveralYears)
        }
    }
}

// The Schedule C page (unit M3-P5) is a projection of FederalBusiness. The
// page's vehicles, property, office and "more" answers each become the
// stored record's own facts; the reverse mapping rebuilds the page and is
// accepted only when saving it again reproduces the stored record exactly.
// The first day on or after which a continuing asset is no longer continuing.
const YEAR_FIRST_DAY: u32 = 20260101;

fn equipment_class(class: AssetClass) -> EquipmentClass {
    match class {
        AssetClass::Three => EquipmentClass::Three,
        AssetClass::Five => EquipmentClass::Five,
        AssetClass::Seven => EquipmentClass::Seven,
        AssetClass::Ten => EquipmentClass::Ten,
        AssetClass::Fifteen => EquipmentClass::Fifteen,
        AssetClass::Twenty => EquipmentClass::Twenty,
        AssetClass::ThirtyNine => EquipmentClass::ThirtyNine,
    }
}
fn asset_class(class: EquipmentClass) -> AssetClass {
    match class {
        EquipmentClass::Three => AssetClass::Three,
        EquipmentClass::Five => AssetClass::Five,
        EquipmentClass::Seven => AssetClass::Seven,
        EquipmentClass::Ten => AssetClass::Ten,
        EquipmentClass::Fifteen => AssetClass::Fifteen,
        EquipmentClass::Twenty => AssetClass::Twenty,
        EquipmentClass::ThirtyNine => AssetClass::ThirtyNine,
    }
}
// The first-year choice onto the section 179 and bonus elections: Section179
// elects its amount; otherwise property that can be section 179 property
// (over 50% business use, not a building) is Eligible with nothing elected, so
// it still counts toward the annual phase-out, and the rest is Ineligible. Only
// Regular elects out of bonus depreciation, for the whole class.
fn equipment_history(history: &AssetHistory, section179_property: bool) -> EquipmentHistory {
    match history {
        AssetHistory::New { first_year } => EquipmentHistory::New {
            section179: match first_year {
                FirstYearDeduction::Section179 { elected, .. } => {
                    Section179::Eligible { elected: *elected }
                }
                _ if section179_property => Section179::Eligible { elected: 0 },
                _ => Section179::Ineligible,
            },
            bonus: if *first_year == FirstYearDeduction::Regular {
                BonusElection::ElectOut
            } else {
                BonusElection::Apply
            },
            tables: true,
        },
        AssetHistory::Continuing {
            prior_depreciation,
            first_year_179,
            first_year_bonus,
            carryforward,
            mid_quarter,
        } => EquipmentHistory::Continuing {
            initial_section179: *first_year_179,
            carryforward: *carryforward,
            prior_depreciation: *prior_depreciation,
            amt: EquipmentAmtHistory::Same,
            mid_quarter: *mid_quarter,
            schedule: EquipmentSchedule::Tables { initial_bonus: *first_year_bonus },
        },
    }
}
// The reverse of equipment_history. A Section179 choice is told from a
// Bonus one by its typed description, which every other asset leaves empty.
fn asset_history(record: &BusinessAsset) -> AssetHistory {
    match record.history {
        EquipmentHistory::New { section179, bonus, .. } => AssetHistory::New {
            first_year: match (section179, bonus) {
                (_, BonusElection::ElectOut) => FirstYearDeduction::Regular,
                (Section179::Eligible { elected }, _)
                    if elected != 0 || !record.description.is_empty() =>
                {
                    FirstYearDeduction::Section179 {
                        description: record.description.clone(),
                        elected,
                    }
                }
                _ => FirstYearDeduction::Bonus,
            },
        },
        EquipmentHistory::Continuing {
            initial_section179,
            carryforward,
            prior_depreciation,
            mid_quarter,
            schedule,
            ..
        } => AssetHistory::Continuing {
            prior_depreciation,
            first_year_179: initial_section179,
            first_year_bonus: match schedule {
                EquipmentSchedule::Tables { initial_bonus } => initial_bonus,
                EquipmentSchedule::Manual => 0,
            },
            carryforward,
            mid_quarter,
        },
    }
}
// The description typed with a section 179 election; no other asset has one.
fn asset_description(asset_history: &AssetHistory) -> alloc::string::String {
    match asset_history {
        AssetHistory::New { first_year: FirstYearDeduction::Section179 { description, .. } } => {
            description.clone()
        }
        _ => alloc::string::String::new(),
    }
}
// One page asset onto BusinessAsset: acquired defaults to the service date,
// the ordinary GDS method from the IRS tables, confirmed by the page.
// `business` is false for equipment rented out outside a business, which is
// never section 179 property.
fn asset_record(asset: &Asset, business: bool) -> BusinessAsset {
    let class = equipment_class(asset.class);
    BusinessAsset {
        id: asset.id,
        history_details: asset.history_details.clone(),
        amt_section179_income_carry: crate::AssetAmt179CarryAnswer::amount(
            &asset.amt_section179_income_carry,
        ),
        description: asset_description(&asset.history),
        cost: asset.cost,
        credit_reduction: asset.credit_reduction,
        acquired: asset.acquired.unwrap_or(asset.placed),
        placed: asset.placed,
        class,
        history: equipment_history(
            &asset.history,
            business && asset.business_percent > 50 && class != EquipmentClass::ThirtyNine,
        ),
        method: EquipmentMethod::Regular,
        listed: ListedProperty::No { business_percent: asset.business_percent },
        disposal: asset.disposal.clone(),
        investment_credit: asset.investment_credit.clone(),
        earlier_business_percent: asset.earlier_business_percent,
        partial: asset.partial.clone(),
    }
}
fn asset_item(record: &BusinessAsset) -> Asset {
    let history = asset_history(record);
    Asset {
        id: record.id,
        history_details: record.history_details.clone(),
        amt_section179_income_carry: crate::AssetAmt179CarryAnswer::from_amount(
            record.amt_section179_income_carry,
        ),
        allowed_amt_carry: crate::AssetAmt179CarryAnswer::page_choices(&history),
        cost: record.cost,
        credit_reduction: record.credit_reduction,
        placed: record.placed,
        class: asset_class(record.class),
        business_percent: match record.listed {
            ListedProperty::No { business_percent } => business_percent,
            ListedProperty::Vehicle { .. } => {
                unreachable!("vehicle assets use their mileage editor")
            }
        },
        acquired: (record.acquired != record.placed).then_some(record.acquired),
        history,
        disposal: record.disposal.clone(),
        investment_credit: record.investment_credit.clone(),
        earlier_business_percent: record.earlier_business_percent,
        partial: record.partial.clone(),
    }
}
// A person's name, the first and last name the person typed.
pub(crate) fn person_name(first: &str, last: &str) -> Vec<u8> {
    crate::Message::new(
        "PERSON_NAME",
        alloc::vec![crate::MessageArg::Text(first.into()), crate::MessageArg::Text(last.into())],
    )
    .encode()
}
// The W-2s a Form 2106 can choose: every wage record of the return, labelled
// by its employer and owner.
fn employee_wage_choices(d: &FederalDraft) -> Vec<crate::WageChoice> {
    d.income
        .iter()
        .filter(|entry| matches!(entry.income, FederalIncome::Wage { .. }))
        .map(|entry| crate::WageChoice {
            id: entry.id,
            label: crate::Message::new(
                "EMPLOYEE_EXPENSES_EMPLOYER_CHOICE",
                alloc::vec![
                    crate::MessageArg::Nested(alloc::boxed::Box::new(
                        income_issue_context(entry).label()
                    )),
                    crate::MessageArg::Resource(
                        if entry.owner == Owner::Taxpayer { "PERSON_YOU" } else { "PERSON_SPOUSE" }
                            .into()
                    ),
                ],
            )
            .encode(),
            owner: entry.owner,
        })
        .collect()
}
// The reverse of employee_expenses_candidate's mapping for one stored form:
// the chosen W-2s that are still the owner's, the standard-mileage vehicles
// and then the actual-expense ones as the Vehicle page lists them.
fn employee_expense_form(
    claim: &crate::EmployeeExpenseClaim,
    wages: &[crate::WageChoice],
) -> crate::EmployeeExpenseForm {
    let mut vehicles: Vec<Vehicle> = claim.mileage.iter().map(mileage_item).collect();
    for asset in &claim.vehicle_assets {
        vehicles.extend(vehicle_item(asset));
    }
    vehicles.extend(
        claim
            .leased_vehicles
            .iter()
            .cloned()
            .map(|vehicle| Vehicle { method: VehicleMethod::Leased { vehicle } }),
    );
    crate::EmployeeExpenseForm {
        owner: claim.owner,
        occupation: claim.occupation.clone(),
        capacity: claim.capacity,
        dot_hours_of_service: claim.dot_hours_of_service,
        employers: claim
            .employers
            .iter()
            .filter(|id| wages.iter().any(|w| w.id == **id && w.owner == claim.owner))
            .copied()
            .collect(),
        local_transportation: claim.local_transportation,
        travel: claim.travel,
        other: claim.other,
        meals: claim.meals,
        reimbursements: claim.reimbursements,
        vehicles,
    }
}
// The page's vehicles in stored order: the standard-mileage vehicles first,
// then the actual-expense ones, each numbered "Vehicle n" in that order.
fn vehicles_in_stored_order(vehicles: &[Vehicle]) -> impl Iterator<Item = &VehicleMethod> {
    let mileage =
        vehicles.iter().filter(|v| matches!(v.method, VehicleMethod::StandardMileage { .. }));
    let actual = vehicles.iter().filter(|v| matches!(v.method, VehicleMethod::Actual { .. }));
    mileage.chain(actual).map(|v| &v.method)
}
// A standard-mileage vehicle onto BusinessMileage.
fn mileage_record(
    id: i64,
    first_half: u32,
    second_half: u32,
    total: u32,
    more: &MileageMore,
) -> BusinessMileage {
    BusinessMileage {
        id,
        first_half,
        second_half,
        total,
        commuting: more.commuting,
        parking_tolls: more.parking_tolls,
        interest: more.interest,
        property_tax: more.property_tax,
        owned: !more.leased,
        placed: more.placed,
        personal_use_available: more.personal_use_available,
        other_vehicle: more.other_vehicle,
        evidence: more.evidence,
    }
}
fn mileage_item(record: &BusinessMileage) -> Vehicle {
    Vehicle {
        method: VehicleMethod::StandardMileage {
            id: record.id,
            first_half: record.first_half,
            second_half: record.second_half,
            total: record.total,
            more: MileageMore {
                commuting: record.commuting,
                parking_tolls: record.parking_tolls,
                interest: record.interest,
                property_tax: record.property_tax,
                leased: !record.owned,
                placed: record.placed,
                personal_use_available: record.personal_use_available,
                other_vehicle: record.other_vehicle,
                evidence: record.evidence,
            },
        },
    }
}
// An actual-expense vehicle onto a 5-year BusinessAsset with its listed
// property facts; its business use remains the exact business miles over all miles.
#[allow(clippy::too_many_arguments)]
fn vehicle_asset(
    id: i64,
    history_details: &Option<alloc::boxed::Box<crate::HistoricalAssetRecords>>,
    amt_section179_income_carry: &Option<alloc::boxed::Box<crate::AssetAmt179CarryAnswer>>,
    cost: i64,
    credit_reduction: i64,
    acquired: Option<u32>,
    placed: u32,
    total_miles: u32,
    business_miles: u32,
    operating_costs: i64,
    loan_interest: i64,
    passenger_automobile: bool,
    earlier_business_percent: Option<u32>,
    history: &AssetHistory,
    disposal: &crate::AssetDisposal,
) -> BusinessAsset {
    BusinessAsset {
        id,
        history_details: history_details.as_deref().cloned(),
        amt_section179_income_carry: amt_section179_income_carry
            .as_deref()
            .map(crate::AssetAmt179CarryAnswer::value),
        description: asset_description(history),
        cost,
        credit_reduction,
        acquired: acquired.unwrap_or(placed),
        placed,
        class: EquipmentClass::Five,
        history: equipment_history(history, u64::from(business_miles) * 2 > u64::from(total_miles)),
        method: match history_details.as_ref().map(|records| &records.original_method) {
            Some(crate::OriginalAssetMethod::Declining150) => EquipmentMethod::Declining150,
            Some(crate::OriginalAssetMethod::StraightLine) => EquipmentMethod::StraightLine,
            _ => EquipmentMethod::Regular,
        },
        listed: ListedProperty::Vehicle {
            total_miles,
            business_miles,
            operating_costs,
            loan_interest,
            passenger_automobile,
        },
        disposal: disposal.clone(),
        investment_credit: crate::InvestmentCredit::No,
        earlier_business_percent,
        partial: None,
    }
}
fn vehicle_item(record: &BusinessAsset) -> Option<Vehicle> {
    let ListedProperty::Vehicle {
        total_miles,
        business_miles,
        operating_costs,
        loan_interest,
        passenger_automobile,
    } = record.listed
    else {
        return None;
    };
    let earlier_business_percent = record.earlier_business_percent;
    Some(Vehicle {
        method: VehicleMethod::Actual {
            id: record.id,
            history_details: record.history_details.clone().map(alloc::boxed::Box::new),
            amt_section179_income_carry: crate::AssetAmt179CarryAnswer::from_amount(
                record.amt_section179_income_carry,
            )
            .map(alloc::boxed::Box::new),
            allowed_amt_carry: crate::AssetAmt179CarryAnswer::page_choices(&asset_history(record)),
            cost: record.cost,
            credit_reduction: record.credit_reduction,
            acquired: (record.acquired != record.placed).then_some(record.acquired),
            placed: record.placed,
            total_miles,
            business_miles,
            operating_costs,
            loan_interest,
            passenger_automobile,
            earlier_business_percent,
            history: asset_history(record),
            disposal: record.disposal.clone(),
        },
    })
}
// Part II lines in printed order, each with its stored category.
fn expense_lines(e: &BusinessExpenses) -> [(BusinessExpenseCategory, i64); 18] {
    use BusinessExpenseCategory as C;
    [
        (C::Advertising, e.advertising),
        (C::Commissions, e.commissions),
        (C::ContractLabor, e.contract_labor),
        (C::EmployeeBenefits, e.employee_benefits),
        (C::Insurance, e.insurance),
        (C::MortgageInterest, e.mortgage_interest),
        (C::OtherInterest, e.other_interest),
        (C::LegalAndProfessional, e.legal_and_professional),
        (C::Office, e.office),
        (C::EmployeePension, e.pension_plans),
        (C::VehicleAndEquipmentRent, e.vehicle_and_equipment_rent),
        (C::OtherRent, e.other_rent),
        (C::Repairs, e.repairs),
        (C::Supplies, e.supplies),
        (C::TaxesAndLicenses, e.taxes_and_licenses),
        (C::Travel, e.travel),
        (C::Utilities, e.utilities),
        (C::Wages, e.wages),
    ]
}
// Each nonzero line is one FederalBusinessExpense; meals take the 50% or the
// DOT 80% treatment, every other line is ordinary.
fn expense_records(e: &BusinessExpenses) -> Vec<FederalBusinessExpense> {
    let mut records: Vec<_> = expense_lines(e)
        .into_iter()
        .filter(|(_, amount)| *amount != 0)
        .map(|(category, amount)| FederalBusinessExpense {
            treatment: BusinessExpenseKind::Ordinary,
            category,
            amount,
        })
        .chain(e.meals.iter().map(|meal| FederalBusinessExpense {
            category: BusinessExpenseCategory::Meals,
            amount: meal.amount,
            treatment: match meal.kind {
                crate::MealKind::Business => BusinessExpenseKind::Meals,
                crate::MealKind::Transportation => BusinessExpenseKind::TransportationMeals,
                crate::MealKind::FullyDeductible => BusinessExpenseKind::Ordinary,
            },
        }))
        .chain(e.other.iter().map(|other| FederalBusinessExpense {
            category: BusinessExpenseCategory::Other { label: other.description.clone() },
            amount: other.amount,
            treatment: BusinessExpenseKind::Ordinary,
        }))
        .collect();
    records.sort_by_key(|record| record.category.index());
    records
}
fn expense_items(records: &[FederalBusinessExpense]) -> BusinessExpenses {
    let mut e = BusinessExpenses {
        advertising: 0,
        commissions: 0,
        contract_labor: 0,
        employee_benefits: 0,
        insurance: 0,
        mortgage_interest: 0,
        other_interest: 0,
        legal_and_professional: 0,
        office: 0,
        vehicle_and_equipment_rent: 0,
        other_rent: 0,
        repairs: 0,
        supplies: 0,
        taxes_and_licenses: 0,
        travel: 0,
        meals: Vec::new(),
        pension_plans: 0,
        utilities: 0,
        wages: 0,
        other: Vec::new(),
    };
    for record in records {
        use BusinessExpenseCategory as C;
        let line = match &record.category {
            C::Advertising => &mut e.advertising,
            C::Commissions => &mut e.commissions,
            C::ContractLabor => &mut e.contract_labor,
            C::EmployeeBenefits => &mut e.employee_benefits,
            C::Insurance => &mut e.insurance,
            C::MortgageInterest => &mut e.mortgage_interest,
            C::OtherInterest => &mut e.other_interest,
            C::LegalAndProfessional => &mut e.legal_and_professional,
            C::Office => &mut e.office,
            C::VehicleAndEquipmentRent => &mut e.vehicle_and_equipment_rent,
            C::OtherRent => &mut e.other_rent,
            C::Repairs => &mut e.repairs,
            C::Supplies => &mut e.supplies,
            C::TaxesAndLicenses => &mut e.taxes_and_licenses,
            C::Travel => &mut e.travel,
            C::EmployeePension => &mut e.pension_plans,
            C::Meals => {
                let kind = match record.treatment {
                    BusinessExpenseKind::Meals => crate::MealKind::Business,
                    BusinessExpenseKind::TransportationMeals => crate::MealKind::Transportation,
                    _ => crate::MealKind::FullyDeductible,
                };
                if let Some(meal) = e.meals.iter_mut().find(|m| m.kind == kind) {
                    meal.amount += record.amount;
                } else {
                    e.meals.push(crate::MealExpense { kind, amount: record.amount });
                }
                continue;
            }
            C::Utilities => &mut e.utilities,
            C::Wages => &mut e.wages,
            C::Other { label } => {
                e.other.push(OtherExpense { description: label.clone(), amount: record.amount });
                continue;
            }
            // A farm-only line has no Schedule C field; the reopen check then
            // keeps the page closed (and the return refuses it by name).
            _ => continue,
        };
        *line = record.amount;
    }
    e
}
// The page's vehicles and property onto the stored mileage and asset
// records: mileage vehicles, then the property, then the actual-expense
// vehicles (shared by the Business and Farm kinds).
pub(crate) fn vehicle_and_asset_records(
    vehicles_page: &[Vehicle],
    assets_page: &[Asset],
) -> (Vec<BusinessMileage>, Vec<BusinessAsset>) {
    let mut vehicles = Vec::new();
    let mut vehicle_assets = Vec::new();
    for method in vehicles_in_stored_order(vehicles_page) {
        match method {
            VehicleMethod::StandardMileage { id, first_half, second_half, total, more } => {
                vehicles.push(mileage_record(*id, *first_half, *second_half, *total, more))
            }
            VehicleMethod::Leased { .. } => {}
            VehicleMethod::Actual {
                id,
                history_details,
                amt_section179_income_carry,
                allowed_amt_carry: _,
                cost,
                credit_reduction,
                acquired,
                placed,
                total_miles,
                business_miles,
                operating_costs,
                loan_interest,
                passenger_automobile,
                earlier_business_percent,
                history,
                disposal,
            } => vehicle_assets.push(vehicle_asset(
                *id,
                history_details,
                amt_section179_income_carry,
                *cost,
                *credit_reduction,
                *acquired,
                *placed,
                *total_miles,
                *business_miles,
                *operating_costs,
                *loan_interest,
                *passenger_automobile,
                *earlier_business_percent,
                history,
                disposal,
            )),
        }
    }
    let mut assets: Vec<BusinessAsset> =
        assets_page.iter().map(|asset| asset_record(asset, true)).collect();
    assets.extend(vehicle_assets);
    (vehicles, assets)
}
// Property assets precede actual-expense vehicle assets in the conversion above.
// Each descriptor is an actual editable Page row, never a stored ordinal used as a Page index.
fn document_asset_rows(document: &IncomeDocument) -> Vec<ValidationIssue> {
    let key = "ASSET_BONUS_ELECTION_BY_CLASS";
    let rows = |count: usize| {
        (0..count)
            .map(|index| ValidationIssue::new(key).at_list_item("assets", index))
            .collect::<Vec<_>>()
    };
    let (mut result, vehicles) = match document {
        IncomeDocument::Business(v) => (rows(v.assets.len()), Some(v.vehicles.as_slice())),
        IncomeDocument::Farm(v) => (rows(v.assets.len()), Some(v.vehicles.as_slice())),
        IncomeDocument::FarmRental(v) => (rows(v.assets.len()), Some(v.vehicles.as_slice())),
        IncomeDocument::Rental(v) => (rows(v.assets.len()), None),
        IncomeDocument::EquipmentRental(v) => (rows(v.assets.len()), None),
        _ => (Vec::new(), None),
    };
    if let Some(vehicles) = vehicles {
        result.extend(
            vehicles
                .iter()
                .enumerate()
                .filter(|(_, vehicle)| matches!(vehicle.method, VehicleMethod::Actual { .. }))
                .map(|(index, _)| ValidationIssue::new(key).at_list_item("vehicles", index)),
        );
    }
    result
}
// The reverse of vehicle_and_asset_records; None for a stored vehicle
// asset the page cannot show.
pub(crate) fn vehicle_and_asset_items(
    mileage: &[BusinessMileage],
    stored: &[BusinessAsset],
) -> Option<(Vec<Vehicle>, Vec<Asset>)> {
    let mut vehicles: Vec<Vehicle> = mileage.iter().map(mileage_item).collect();
    let mut assets = Vec::new();
    for record in stored {
        if record.is_vehicle() {
            vehicles.push(vehicle_item(record)?);
        } else {
            assets.push(asset_item(record));
        }
    }
    Some((vehicles, assets))
}
// The page's business onto FederalBusiness. Owner health insurance and the
// retirement plan belong to the adjustments page and are kept from the
// accepted record with the same identity. Every other answer, including the
// always-present "More about this business" record, is the person's own.
fn business_record(b: &Business, kept: Option<&FederalBusiness>) -> FederalBusiness {
    let (vehicles, assets) = vehicle_and_asset_records(&b.vehicles, &b.assets);
    let more = &b.more;
    FederalBusiness {
        principal_business: b.principal_business.clone(),
        business_code: b.business_code,
        ein: b.ein.clone(),
        address: b.address.clone(),
        started_current_year: b.started_current_year,
        information_returns: b.information_returns,
        other_income: b.other_income.clone(),
        de_minimis: more.de_minimis.clone(),
        depletion: more.depletion.clone(),
        leased_vehicles: b
            .vehicles
            .iter()
            .filter_map(|v| {
                if let VehicleMethod::Leased { vehicle } = &v.method {
                    Some(vehicle.clone())
                } else {
                    None
                }
            })
            .collect(),
        ministerial: more.ministerial,
        notary_profit: more.notary_profit,
        notary_gross: more.notary_gross,
        source: more.source.clone(),
        income_source: more.income_source.record(),
        activity: match &more.gambling {
            None => BusinessActivity::Ordinary {
                returns: b.returns,
                receipts: b.receipts,
                accounting: b.accounting,
            },
            Some(g) => BusinessActivity::Gambling {
                returns: 0,
                receipts: b.receipts,
                accounting: b.accounting,
                losses: g.losses,
                withholding: g.withholding,
                eligible: g.eligible,
            },
        },
        inventory: more.inventory.clone(),
        startup: more.startup.clone(),
        method_changes: more.method_changes.clone(),
        intangibles: more.intangibles.clone(),
        timber: more.timber.clone(),
        other_amortization: more.other_amortization.iter().cloned().map(Into::into).collect(),
        health_insurance: kept
            .map_or(BusinessHealthInsurance::None, |k| k.health_insurance.clone()),
        retirement: kept.map_or(BusinessRetirement::None, |k| k.retirement.clone()),
        vehicles,
        assets,
        expenses: expense_records(&b.expenses),
        tips: more.tips.clone(),
        overtime: more.overtime.clone(),
        fuel_tax_credit: more.fuel_tax_credit.clone(),
        cash_fuel_tax_recovery: more.cash_fuel_tax_recovery.clone(),
        employer_tip_fica_credit: more.tip_fica.clone(),
        work_opportunity_credit: more.work_opportunity.clone(),
        retirement_plan_credit: more.retirement_plan.clone(),
        small_employer_health_credit: more.small_employer_health.clone(),
        paid_leave_credit: more.paid_leave.clone(),
        material_participation: more.material_participation,
        specified_service: b.specified_service,
        at_risk: more.at_risk.clone(),
        payroll: more.payroll.clone(),
        special_treatment: more.special,
        qbi_aggregation_group: crate::common::optional_text(&more.qbi_group),
        withholding: 0,
        commercial_fishing: more.commercial_fishing,
        sale: more.sale.clone(),
    }
}
// The reverse of business_record; None for a stored business the page's
// answers would not reproduce.
fn business_item(entry_label: &str, data: &FederalBusiness) -> Option<Business> {
    let (receipts, accounting, gambling) = match data.activity {
        BusinessActivity::Ordinary { receipts, accounting, .. } => (receipts, accounting, None),
        BusinessActivity::Gambling {
            receipts, accounting, losses, withholding, eligible, ..
        } => (
            receipts,
            accounting,
            Some(crate::ProfessionalGambling { losses, withholding, eligible }),
        ),
        BusinessActivity::Farming { .. } => return None,
    };
    let (mut vehicles, assets) = vehicle_and_asset_items(&data.vehicles, &data.assets)?;
    vehicles.extend(
        data.leased_vehicles
            .iter()
            .cloned()
            .map(|vehicle| Vehicle { method: VehicleMethod::Leased { vehicle } }),
    );
    let item = Business {
        principal_business: data.principal_business.clone(),
        business_code: data.business_code,
        ein: data.ein.clone(),
        address: data.address.clone(),
        started_current_year: data.started_current_year,
        information_returns: data.information_returns,
        returns: match data.activity {
            BusinessActivity::Ordinary { returns, .. }
            | BusinessActivity::Gambling { returns, .. } => returns,
            _ => 0,
        },
        other_income: data.other_income.clone(),
        name: entry_label.into(),
        receipts,
        accounting,
        expenses: expense_items(&data.expenses),
        vehicles,
        assets,
        specified_service: data.specified_service,
        more: BusinessDetails {
            research_property_choices: crate::cohorts::property_choices(data),
            de_minimis: data.de_minimis.clone(),
            overtime: data.overtime.clone(),
            depletion: data.depletion.clone(),
            ministerial: data.ministerial,
            notary_profit: data.notary_profit,
            notary_gross: data.notary_gross,
            inventory: data.inventory.clone(),
            startup: data.startup.clone(),
            method_changes: data.method_changes.clone(),
            intangibles: data.intangibles.clone(),
            timber: data.timber.clone(),
            other_amortization: data.other_amortization.iter().cloned().map(Into::into).collect(),
            payroll: data.payroll.clone(),
            work_opportunity: data.work_opportunity_credit.clone(),
            retirement_plan: data.retirement_plan_credit.clone(),
            tip_fica: data.employer_tip_fica_credit.clone(),
            small_employer_health: data.small_employer_health_credit.clone(),
            paid_leave: data.paid_leave_credit.clone(),
            fuel_tax_credit: data.fuel_tax_credit.clone(),
            cash_fuel_tax_recovery: data.cash_fuel_tax_recovery.clone(),
            tips: data.tips.clone(),
            material_participation: data.material_participation,
            at_risk: data.at_risk.clone(),
            qbi_group: data.qbi_aggregation_group.clone().unwrap_or_default(),
            income_source: crate::BusinessIncomeChoice::from_record(&data.income_source),
            gambling,
            source: data.source.clone(),
            special: data.special_treatment,
            commercial_fishing: data.commercial_fishing,
            sale: data.sale.clone(),
        },
    };
    (business_record(&item, Some(data)) == *data).then_some(item)
}
fn asset_partial_issue(
    class: AssetClass,
    cost: i64,
    placed: u32,
    part: &Option<crate::PartialDisposition>,
) -> Option<ValidationIssue> {
    let issue = |key, field| ValidationIssue::new(key).at_field(field);
    if let Some(part) = part {
        if class != AssetClass::ThirtyNine {
            return Some(issue("PARTIAL_DISPOSITION_NEEDS_A_BUILDING_ROW", "partial"));
        }
        if part.cost_of_part >= cost {
            return Some(
                issue("PARTIAL_DISPOSITION_PART_ABOVE_COST", "cost_of_part").in_field("partial"),
            );
        }
        if part.date <= placed {
            return Some(issue("PARTIAL_DISPOSITION_BEFORE_SERVICE", "date").in_field("partial"));
        }
    }
    None
}
// Each source predicate chooses its local field before outer walkers add indices.
fn asset_issue(asset: &Asset) -> Option<ValidationIssue> {
    let issue = |key, field| ValidationIssue::new(key).at_field(field);
    if asset.acquired.is_some_and(|acquired| acquired > asset.placed) {
        return Some(issue("ASSET_ACQUIRED_AFTER_PLACED", "acquired"));
    }
    if asset.credit_reduction > asset.cost {
        return Some(issue("ASSET_CREDIT_ABOVE_COST", "credit_reduction"));
    }
    if let Some(issue) = disposal_issue(&asset.disposal, asset.placed) {
        return Some(issue.in_field("disposal"));
    }
    if asset.earlier_business_percent.is_some()
        && (!matches!(asset.history, AssetHistory::Continuing { .. })
            || asset.business_percent > 50)
    {
        return Some(issue("ASSET_EARLIER_USE_ONLY_AFTER_USE_FELL", "earlier_business_percent"));
    }
    if let Some(issue) = asset_partial_issue(asset.class, asset.cost, asset.placed, &asset.partial)
    {
        return Some(issue);
    }
    if let Some(issue) = history_issue(&asset.history, asset.placed) {
        return Some(issue);
    }
    if let AssetHistory::New { first_year: FirstYearDeduction::Section179 { elected, .. } } =
        &asset.history
        && i128::from(*elected) * 100
            > i128::from(asset.cost - asset.credit_reduction) * i128::from(asset.business_percent)
    {
        return Some(
            issue("ASSET_179_ABOVE_BUSINESS_COST", "elected")
                .in_field("first_year")
                .in_field("history"),
        );
    }
    investment_issue(asset)
}
fn investment_issue(asset: &Asset) -> Option<ValidationIssue> {
    use crate::InvestmentCredit;
    let issue = |key, field| ValidationIssue::new(key).at_field(field);
    let new = matches!(asset.history, AssetHistory::New { .. });
    match &asset.investment_credit {
        InvestmentCredit::No => None,
        InvestmentCredit::Rehabilitation(claim) => {
            if asset.class != AssetClass::ThirtyNine
                || asset.placed
                    < crate::year_constants::REHABILITATION_FIRST_PLACED_YEAR * 10000 + 101
            {
                return Some(issue(
                    "REHABILITATION_NEEDS_A_BUILDING_ROW",
                    if asset.class != AssetClass::ThirtyNine { "class" } else { "placed" },
                ));
            }
            if claim.period_start >= asset.placed {
                return Some(
                    issue("REHABILITATION_PERIOD_AFTER_PLACED", "period_start")
                        .in_field("investment_credit"),
                );
            }
            let qre =
                crate::kernel::ratio::fraction(asset.cost, i64::from(asset.business_percent), 100);
            claim.issue(asset.placed, qre).map(|issue| issue.in_field("investment_credit"))
        }
        InvestmentCredit::NewEnergy { construction_began, .. } => {
            if asset.class != AssetClass::Five || !new {
                Some(issue(
                    "ENERGY_CREDIT_NEEDS_NEW_5_YEAR_PROPERTY",
                    if asset.class != AssetClass::Five { "class" } else { "history" },
                ))
            } else if *construction_began > asset.placed {
                Some(
                    issue("ENERGY_CONSTRUCTION_AFTER_PLACED", "construction_began")
                        .in_field("investment_credit"),
                )
            } else {
                None
            }
        }
        InvestmentCredit::EarlierEnergy { credit, used, carried, .. } => {
            if asset.class != AssetClass::Five || new {
                Some(issue(
                    "EARLIER_ENERGY_NEEDS_CONTINUING_5_YEAR_PROPERTY",
                    if asset.class != AssetClass::Five { "class" } else { "history" },
                ))
            } else if i128::from(*used) + i128::from(*carried) > i128::from(*credit) {
                Some(
                    issue("INVESTMENT_CREDIT_HISTORY_ABOVE_CREDIT", "carried")
                        .in_field("investment_credit"),
                )
            } else {
                None
            }
        }
    }
}
fn disposal_issue(disposal: &crate::AssetDisposal, placed: u32) -> Option<ValidationIssue> {
    if let crate::AssetDisposal::Disposed {
        how: crate::DisposalKind::Sold { proceeds, payment, buyer, .. },
        ..
    } = disposal
    {
        if let Some(issue) = payment.issue(*proceeds) {
            return Some(issue.in_field("payment").in_field("how"));
        }
        if *buyer != crate::Buyer::Unrelated && payment.installment() {
            return Some(
                ValidationIssue::new("INSTALLMENT_RELATED_BUYER").at_field("buyer").in_field("how"),
            );
        }
    }
    disposal
        .date()
        .filter(|date| *date <= placed)
        .map(|_| ValidationIssue::new("ASSET_DISPOSED_BEFORE_PLACED").at_field("date"))
}
// The date belongs to the containing asset or actual-expense vehicle, not history.
fn history_issue(history: &AssetHistory, placed: u32) -> Option<ValidationIssue> {
    let key = match history {
        AssetHistory::New { .. } if placed / 10000 != 2026 => "ASSET_NEW_PLACED_IN_2026",
        AssetHistory::Continuing { .. } if placed >= YEAR_FIRST_DAY => {
            "ASSET_OLD_PLACED_BEFORE_2026"
        }
        _ => return None,
    };
    Some(ValidationIssue::new(key).at_field("placed"))
}
fn business_issue(b: &Business) -> Option<ValidationIssue> {
    let more = &b.more;
    if let Some(issue) =
        more.at_risk.issue_for_method(&crate::RiskEffectiveCategory::OtherTradeBusiness, true)
    {
        return Some(issue.in_field("at_risk").in_field("more"));
    }
    if let Some(issue) = more
        .fuel_tax_credit
        .as_ref()
        .and_then(|claim| claim.fuels.vendor_blocked_pump_kerosene.as_ref())
        .and_then(|claim| claim.buyer_issue())
    {
        return Some(
            issue
                .in_field("vendor_blocked_pump_kerosene")
                .in_field("fuels")
                .in_field("fuel_tax_credit")
                .in_field("more"),
        );
    }

    if let Some(issue) = more.payroll.issue() {
        return Some(issue.in_field("payroll").in_field("more"));
    }
    for (index, meal) in b.expenses.meals.iter().enumerate() {
        if b.expenses.meals[..index].iter().any(|prior| prior.kind == meal.kind) {
            return Some(
                ValidationIssue::new("BUSINESS_MEAL_KIND_ONCE")
                    .at_field("kind")
                    .in_list("meals", index)
                    .in_field("expenses"),
            );
        }
    }
    if let Some(issue) = more.de_minimis.as_ref().and_then(|value| value.issue()) {
        return Some(issue.in_field("de_minimis").in_field("more"));
    }
    if let Some(issue) = more.depletion.as_ref().and_then(|value| value.issue()) {
        return Some(issue.in_field("depletion").in_field("more"));
    }
    if let Some(issue) = crate::method_change::list_issue(&more.method_changes) {
        return Some(issue.in_field("more"));
    }
    if (more.work_opportunity.is_some()
        || more.retirement_plan.is_some()
        || more.tip_fica.is_some()
        || more.small_employer_health.is_some()
        || more.paid_leave.is_some())
        && more.payroll == BusinessPayroll::No
    {
        return Some(
            ValidationIssue::new("EMPLOYER_CREDITS_NEED_PAYROLL")
                .at_field("payroll")
                .in_field("more"),
        );
    }
    if more.gambling.as_ref().is_some_and(|gambling| gambling.withholding > b.receipts) {
        return Some(
            ValidationIssue::new("GAMBLING_BUSINESS_WITHHOLDING_ABOVE_WINNINGS")
                .at_field("withholding")
                .in_field("gambling")
                .in_field("more"),
        );
    }
    if let Some(issue) = more.work_opportunity.as_ref().and_then(|claim| claim.issue()) {
        return Some(issue.in_field("work_opportunity").in_field("more"));
    }
    if let Some(issue) = more.small_employer_health.as_ref().and_then(|claim| claim.issue()) {
        return Some(issue.in_field("small_employer_health").in_field("more"));
    }
    if let Some(issue) = more.paid_leave.as_ref().and_then(|claim| claim.issue()) {
        return Some(issue.in_field("paid_leave").in_field("more"));
    }
    if let BusinessPayroll::Yes { statements, .. } = &more.payroll {
        let listed = |label: &str| statements.iter().any(|w| w.label == label);
        for (field, labels) in [
            (
                "work_opportunity",
                more.work_opportunity
                    .iter()
                    .flat_map(|claim| claim.employees.iter().map(|e| e.label.as_str()))
                    .collect::<Vec<_>>(),
            ),
            (
                "tip_fica",
                more.tip_fica
                    .iter()
                    .flat_map(|claim| claim.employees.iter().map(|e| e.label.as_str()))
                    .collect::<Vec<_>>(),
            ),
            (
                "small_employer_health",
                more.small_employer_health
                    .iter()
                    .flat_map(|claim| claim.employees.iter().map(|e| e.label.as_str()))
                    .collect::<Vec<_>>(),
            ),
            (
                "paid_leave",
                more.paid_leave
                    .iter()
                    .flat_map(|claim| claim.employees.iter().map(|e| e.label.as_str()))
                    .collect::<Vec<_>>(),
            ),
        ] {
            for (index, label) in labels.iter().enumerate() {
                if !listed(label) {
                    return Some(
                        ValidationIssue::new("EMPLOYER_CREDIT_EMPLOYEE_NOT_ON_PAYROLL")
                            .at_field("label")
                            .in_list("employees", index)
                            .in_field(field)
                            .in_field("more"),
                    );
                }
            }
        }
    }
    shared_business_issue(&b.vehicles, &b.assets)
}
// Preserve the existing group-wide order: office, ordinary vehicles, leases, assets.
pub(crate) fn shared_business_issue(
    vehicles: &[Vehicle],
    assets: &[Asset],
) -> Option<ValidationIssue> {
    for (index, vehicle) in vehicles.iter().enumerate() {
        let issue = |key, field| ValidationIssue::new(key).at_field(field);
        let local = match &vehicle.method {
            VehicleMethod::StandardMileage { first_half, second_half, total, more, .. }
                if u64::from(*first_half) + u64::from(*second_half) + u64::from(more.commuting)
                    > u64::from(*total) =>
            {
                Some(if first_half > total {
                    issue("MILEAGE_ABOVE_TOTAL_MILES", "first_half")
                } else if u64::from(*first_half) + u64::from(*second_half) > u64::from(*total) {
                    issue("MILEAGE_ABOVE_TOTAL_MILES", "second_half")
                } else {
                    issue("MILEAGE_ABOVE_TOTAL_MILES", "commuting").in_field("more")
                })
            }
            VehicleMethod::Actual { total_miles, business_miles, .. }
                if business_miles > total_miles =>
            {
                Some(issue("VEHICLE_BUSINESS_MILES_ABOVE_TOTAL", "business_miles"))
            }
            VehicleMethod::Actual { cost, credit_reduction, .. } if credit_reduction > cost => {
                Some(issue("ASSET_CREDIT_ABOVE_COST", "credit_reduction"))
            }
            VehicleMethod::Actual {
                earlier_business_percent: Some(_),
                total_miles,
                business_miles,
                history,
                ..
            } if !matches!(history, AssetHistory::Continuing { .. })
                || u64::from(*business_miles) * 2 > u64::from(*total_miles) =>
            {
                Some(issue("VEHICLE_EARLIER_USE_ONLY_AFTER_USE_FELL", "earlier_business_percent"))
            }
            VehicleMethod::Actual { acquired: Some(acquired), placed, .. } if acquired > placed => {
                Some(issue("ASSET_ACQUIRED_AFTER_PLACED", "acquired"))
            }
            VehicleMethod::Actual { placed, history, disposal, .. } => {
                history_issue(history, *placed).or_else(|| {
                    disposal_issue(disposal, *placed).map(|issue| issue.in_field("disposal"))
                })
            }
            _ => None,
        };
        if let Some(issue) = local {
            return Some(issue.in_field("method").in_list("vehicles", index));
        }
        let (_, records) = vehicle_and_asset_records(core::slice::from_ref(vehicle), &[]);
        if let Some(issue) = records.first().and_then(crate::auto_recovery::history_issue) {
            return Some(issue.in_field("method").in_list("vehicles", index));
        }
    }
    for (index, vehicle) in vehicles.iter().enumerate() {
        if let VehicleMethod::Leased { vehicle } = &vehicle.method
            && let Some(issue) = vehicle.issue()
        {
            return Some(issue.in_field("vehicle").in_field("method").in_list("vehicles", index));
        }
    }
    assets
        .iter()
        .enumerate()
        .find_map(|(index, asset)| asset_issue(asset).map(|issue| issue.in_list("assets", index)))
}
// Equipment rented out outside a business is 100% income-producing
// nonbusiness property: section 179 is not available to it.
fn equipment_rent_issue(v: &EquipmentRent) -> Option<ValidationIssue> {
    v.assets.iter().enumerate().find_map(|(index, asset)| {
        asset_issue(asset)
            .or_else(|| {
                asset.investment_credit.is_some().then_some(
                    ValidationIssue::new("EQUIPMENT_RENT_NO_INVESTMENT_CREDIT")
                        .at_field("investment_credit"),
                )
            })
            .or_else(|| {
                matches!(
                    asset.history,
                    AssetHistory::New { first_year: FirstYearDeduction::Section179 { .. } }
                )
                .then_some(
                    ValidationIssue::new("EQUIPMENT_RENT_NO_SECTION_179")
                        .at_field("first_year")
                        .in_field("history"),
                )
            })
            .map(|issue| issue.in_list("assets", index))
    })
}

// The Schedule E page (unit M3-P6) is a projection of FederalRental: each
// nonzero line one ordinary RentalExpense, the building then the improvements
// as RentalBuilding records, and the "more" answers' Nothing branch an
// active, fully at-risk, investment-only rental with no suspended losses,
// payroll, group, home-use carryovers or special treatment. The reverse
// mapping rebuilds the page and is accepted only when saving it again
// reproduces the stored record exactly.
// Schedule E lines 5-17 in printed order, each with its stored category.
fn rental_expense_lines(e: &RentalExpenses) -> [(RentalExpenseCategory, i64); 14] {
    use RentalExpenseCategory as C;
    [
        (C::Advertising, e.advertising),
        (C::AutoAndTravel, e.auto_and_travel),
        (C::CleaningAndMaintenance, e.cleaning),
        (C::Commissions, e.commissions),
        (C::Insurance, e.insurance),
        (C::LegalAndProfessional, e.legal),
        (C::ManagementFees, e.management),
        (C::MortgageInterest, e.mortgage_interest),
        (C::VehicleLoanInterest, e.vehicle_loan_interest),
        (C::OtherInterest, e.other_interest),
        (C::Repairs, e.repairs),
        (C::Supplies, e.supplies),
        (C::TaxesAndLicenses, e.taxes),
        (C::Utilities, e.utilities),
    ]
}
fn rental_expense_records(e: &RentalExpenses) -> Vec<RentalExpense> {
    rental_expense_lines(e)
        .into_iter()
        .filter(|(_, amount)| *amount != 0)
        .map(|(category, amount)| RentalExpense {
            category,
            amount,
            treatment: BusinessExpenseKind::Ordinary,
        })
        .chain(e.other.iter().map(|other| RentalExpense {
            category: RentalExpenseCategory::Other { label: other.description.clone() },
            amount: other.amount,
            treatment: BusinessExpenseKind::Ordinary,
        }))
        .collect()
}
fn rental_expense_items(records: &[RentalExpense]) -> RentalExpenses {
    let mut e = RentalExpenses {
        advertising: 0,
        auto_and_travel: 0,
        cleaning: 0,
        commissions: 0,
        insurance: 0,
        legal: 0,
        management: 0,
        mortgage_interest: 0,
        vehicle_loan_interest: 0,
        other_interest: 0,
        repairs: 0,
        supplies: 0,
        taxes: 0,
        utilities: 0,
        other: Vec::new(),
    };
    for record in records {
        use RentalExpenseCategory as C;
        let line = match &record.category {
            C::Advertising => &mut e.advertising,
            C::AutoAndTravel => &mut e.auto_and_travel,
            C::CleaningAndMaintenance => &mut e.cleaning,
            C::Commissions => &mut e.commissions,
            C::Insurance => &mut e.insurance,
            C::LegalAndProfessional => &mut e.legal,
            C::ManagementFees => &mut e.management,
            C::MortgageInterest => &mut e.mortgage_interest,
            C::VehicleLoanInterest => &mut e.vehicle_loan_interest,
            C::OtherInterest => &mut e.other_interest,
            C::Repairs => &mut e.repairs,
            C::Supplies => &mut e.supplies,
            C::TaxesAndLicenses => &mut e.taxes,
            C::Utilities => &mut e.utilities,
            C::Other { label } => {
                e.other.push(OtherExpense { description: label.clone(), amount: record.amount });
                continue;
            }
        };
        *line = record.amount;
    }
    e
}
fn building_record(b: &Building) -> RentalBuilding {
    RentalBuilding {
        casualty: b.casualty.clone(),
        id: b.id,
        energy: b.energy.as_ref().map(Into::into),
        sale_history: b.sale_history.clone(),
        credit_reduction: b.credit_reduction,
        cost: b.cost,
        land: b.land,
        in_service: b.in_service,
        commercial_1993_transition: b.commercial_1993_transition.clone(),
        acquired: b.acquired.clone(),
        rehabilitation: None,
        partial: b.partial.clone(),
    }
}
// An improvement is a stored building row with no land.
fn improvement_record(b: &Improvement) -> RentalBuilding {
    RentalBuilding {
        casualty: b.casualty.clone(),
        id: b.id,
        energy: b.energy.as_ref().map(Into::into),
        sale_history: b.sale_history.clone(),
        credit_reduction: b.credit_reduction,
        cost: b.cost,
        land: 0,
        in_service: b.in_service,
        commercial_1993_transition: b.commercial_1993_transition.clone(),
        acquired: crate::RentalAcquisition::Purchased,
        rehabilitation: b.rehabilitation.clone(),
        partial: b.partial.clone(),
    }
}
fn building_item(record: &RentalBuilding, kind: &RentalPropertyType) -> Building {
    Building {
        casualty: record.casualty.clone(),
        id: record.id,
        energy: record.energy.as_ref().map(Into::into),
        sale_history: record.sale_history.clone(),
        credit_reduction: record.credit_reduction,
        cost: record.cost,
        land: record.land,
        in_service: record.in_service,
        commercial_1993_transition: record.commercial_1993_transition.clone(),
        allowed_commercial_1993_transition: crate::rental_recovery::allowed(
            kind,
            record.in_service,
        ),
        acquired: record.acquired.clone(),
        partial: record.partial.clone(),
    }
}
// None for a stored improvement row the page cannot show (it holds land).
fn improvement_item(record: &RentalBuilding, kind: &RentalPropertyType) -> Option<Improvement> {
    (record.land == 0).then(|| Improvement {
        casualty: record.casualty.clone(),
        id: record.id,
        energy: record.energy.as_ref().map(Into::into),
        sale_history: record.sale_history.clone(),
        credit_reduction: record.credit_reduction,
        cost: record.cost,
        in_service: record.in_service,
        commercial_1993_transition: record.commercial_1993_transition.clone(),
        allowed_commercial_1993_transition: crate::rental_recovery::allowed(
            kind,
            record.in_service,
        ),
        rehabilitation: record.rehabilitation.clone(),
        partial: record.partial.clone(),
    })
}
// Personal use onto RentalPersonalUse; last year's home-use carryovers are
// stored beside it, so a rental with none this year is a plain No (they are
// still limited to the rent left, section 280A(c)(5)).
fn personal_use_record(personal_use: &PersonalUse) -> RentalPersonalUse {
    match personal_use {
        PersonalUse::No => RentalPersonalUse::No,
        PersonalUse::Yes { fair_rental_days, personal_days, overlap_days, direct_expenses } => {
            RentalPersonalUse::Yes {
                fair_rental_days: *fair_rental_days,
                personal_days: *personal_days,
                overlap_days: *overlap_days,
                direct_expenses: *direct_expenses,
            }
        }
    }
}
// The suspended losses onto a rental's history. The loss-year participation
// answer belongs to a loss; with none it is the default.
pub(crate) fn rental_history(suspended: &SuspendedLoss) -> RentalHistory {
    RentalHistory {
        regular: suspended.regular,
        amt: suspended.amt,
        active_in_loss_year: suspended.active_in_loss_year
            || (suspended.regular == 0 && suspended.amt == 0),
    }
}
// The page's rental onto FederalRental.
fn rental_record(r: &Rental) -> FederalRental {
    let more = &r.more;
    let mut buildings = alloc::vec![building_record(&r.building)];
    buildings.extend(more.improvements.iter().map(improvement_record));
    FederalRental {
        energy_buildings: more.energy_buildings.clone(),
        property_qbi_history: more.property_qbi_history.clone(),
        mortgage_loans: r.mortgage_loans.clone(),
        rent: r.rent,
        expenses: rental_expense_records(&r.expenses),
        buildings,
        participation: more.participation,
        ordinary_rental: !more.special,
        at_risk: more.at_risk.clone(),
        assets: r.assets.iter().cloned().map(Into::into).collect(),
        qbi_business: match &more.qbi {
            RentalBusiness::No => RentalBusiness::No,
            RentalBusiness::Yes { material_participation, .. } => {
                RentalBusiness::Yes { material_participation: *material_participation }
            }
        },
        history: rental_history(&more.suspended),
        method_changes: more.method_changes.clone(),
        payroll: more.payroll.clone(),
        qbi_aggregation_group: crate::common::optional_text(&more.qbi_group),
        personal_use: personal_use_record(&r.personal_use),
        home_operating_carryover: more.home_operating_carryover,
        home_depreciation_carryover: more.home_depreciation_carryover.clone(),
        amt_home_depreciation_carryover: more.amt_home_depreciation_carryover.clone(),
        home_casualty_carryover: more.home_casualty_carryover.clone(),
        amt_home_casualty_carryover: more.amt_home_casualty_carryover.clone(),
        property_type: r.kind.clone(),
        sale: r.sale.clone(),
        statement: r.statement.clone(),
    }
}
// The reverse of rental_record; None for a stored rental the page's answers
// would not reproduce. Zero days with carryovers reopen as no personal use.
fn rental_item(entry_label: &str, data: &FederalRental) -> Option<Rental> {
    let (building, improvements) = data.buildings.split_first()?;
    let personal_use = match data.personal_use {
        RentalPersonalUse::No => PersonalUse::No,
        RentalPersonalUse::Yes {
            fair_rental_days,
            personal_days,
            overlap_days,
            direct_expenses,
        } => PersonalUse::Yes { fair_rental_days, personal_days, overlap_days, direct_expenses },
    };
    let item = Rental {
        mortgage_loans: data.mortgage_loans.clone(),
        address: entry_label.into(),
        kind: data.property_type.clone(),
        assets: data.assets.iter().cloned().map(Into::into).collect(),
        rent: data.rent,
        expenses: rental_expense_items(&data.expenses),
        building: building_item(building, &data.property_type),
        sale: data.sale.clone(),
        statement: data.statement.clone(),
        personal_use,
        more: RentalDetails {
            energy_buildings: data.energy_buildings.clone(),
            property_qbi_history: data.property_qbi_history.clone(),
            improvements: improvements
                .iter()
                .map(|row| improvement_item(row, &data.property_type))
                .collect::<Option<_>>()?,
            participation: data.participation,
            suspended: SuspendedLoss {
                regular: data.history.regular,
                amt: data.history.amt,
                active_in_loss_year: data.history.active_in_loss_year,
            },
            method_changes: data.method_changes.clone(),
            home_operating_carryover: data.home_operating_carryover,
            home_depreciation_carryover: data.home_depreciation_carryover.clone(),
            amt_home_depreciation_carryover: data.amt_home_depreciation_carryover.clone(),
            home_casualty_carryover: data.home_casualty_carryover.clone(),
            amt_home_casualty_carryover: data.amt_home_casualty_carryover.clone(),
            qbi: data.qbi_business.clone(),
            qbi_group: data.qbi_aggregation_group.clone().unwrap_or_default(),
            payroll: data.payroll.clone(),
            at_risk: data.at_risk.clone(),
            special: !data.ordinary_rental,
        },
    };
    (rental_record(&item) == *data).then_some(item)
}
// The page rules repeated on save: the land part of the building (and, on
// the server only, of each improvement) cannot exceed its cost, and the
// personal-use days cannot exceed the year.
// Intrinsic document checks have no return context. Save and preview supply
// the actual accepted year here for the casualty election window.
fn rental_casualty_year_issue(document: &IncomeDocument, year: i32) -> Option<ValidationIssue> {
    let IncomeDocument::Rental(rental) = document else {
        return None;
    };
    if let Some(source) = &rental.building.casualty
        && let Some(issue) = source.casualty.year_issue(year)
    {
        return Some(issue.in_field("casualty").in_field("casualty").in_field("building"));
    }
    rental.more.improvements.iter().enumerate().find_map(|(index, improvement)| {
        improvement.casualty.as_ref()?.casualty.year_issue(year).map(|issue| {
            issue
                .in_field("casualty")
                .in_field("casualty")
                .in_list("improvements", index)
                .in_field("more")
        })
    })
}

fn rental_issue(r: &Rental) -> Option<crate::validation::ValidationIssue> {
    use crate::validation::ValidationIssue;
    if let Some(casualty) = &r.building.casualty
        && let Some(issue) =
            casualty.issue(r.building.cost.checked_sub(r.building.land).unwrap_or(-1))
    {
        return Some(issue.in_field("casualty").in_field("building"));
    }
    for (index, improvement) in r.more.improvements.iter().enumerate() {
        if let Some(casualty) = &improvement.casualty
            && let Some(issue) = casualty.issue(improvement.cost)
        {
            return Some(
                issue.in_field("casualty").in_list("improvements", index).in_field("more"),
            );
        }
    }
    if let Some(issue) = crate::rental_home_carry::issue(&rental_record(r)) {
        return Some(issue.in_field("more"));
    }
    if let Some(key) = crate::rental_energy::source_issue(&rental_record(r)) {
        let issue = ValidationIssue::new(key);
        return Some(
            if key == "RENTAL_ENERGY_BUILDING_RECORDS" || key == "RENTAL_ENERGY_HISTORY_RECORDS" {
                issue.at_field("energy_buildings").in_field("more")
            } else if r.building.energy.is_some() {
                issue.at_field("energy").in_field("building")
            } else {
                issue.at_field("improvements").in_field("more")
            },
        );
    }
    if let Some(issue) = r.more.payroll.issue() {
        return Some(issue.in_field("payroll").in_field("more"));
    }
    if (!matches!(r.personal_use, PersonalUse::No) && r.expenses.mortgage_interest != 0)
        || (matches!(r.personal_use, PersonalUse::No) && !r.mortgage_loans.is_empty())
    {
        let issue = ValidationIssue::new("RENTAL_MORTGAGE_SINGLE_SOURCE");
        return Some(
            if !matches!(r.personal_use, PersonalUse::No) && r.expenses.mortgage_interest != 0 {
                issue.at_field("mortgage_interest").in_field("expenses")
            } else {
                issue.at_field("mortgage_loans")
            },
        );
    }
    if let Some(issue) =
        crate::activity_risk::source_issue(&r.more.at_risk, &rental_history(&r.more.suspended))
    {
        return Some(issue.in_field("more"));
    }
    if let Some(index) = r.assets.iter().position(|asset| asset.elected179() > 0) {
        return Some(
            ValidationIssue::new("RENTAL_ASSET_NO_SECTION_179")
                .at_field("elected")
                .in_field("section179")
                .in_field("history")
                .in_list("assets", index),
        );
    }
    if let Some(material) = r.kind.business_participation()
        && let RentalBusiness::Yes { material_participation } = r.more.qbi
        && material_participation != material
    {
        return Some(
            ValidationIssue::new("SHORT_TERM_PARTICIPATION_AGREES")
                .at_field("material_participation")
                .in_field("qbi")
                .in_field("more"),
        );
    }
    if let Some(issue) = crate::method_change::list_issue(&r.more.method_changes) {
        return Some(issue.in_field("more"));
    }
    if let Some(issue) = crate::rental_property_history::history_issue(
        &r.more.property_qbi_history,
        r.more.at_risk.as_ref().map_or(0, |risk| risk.prior_sale(false)),
    ) {
        return Some(issue.in_field("more"));
    }
    // Check both signs and ordering before subtracting untrusted source amounts.
    if r.building.land < 0 || r.building.cost < r.building.land {
        return Some(
            ValidationIssue::new("RENTAL_LAND_ABOVE_COST").at_field("land").in_field("building"),
        );
    }
    if r.building
        .sale_history
        .as_ref()
        .is_some_and(|history| !history.valid(r.building.cost - r.building.land))
    {
        return Some(
            ValidationIssue::new("ISSUE_RENTAL_BUILDING_DEPRECIATION_RECORDS")
                .at_field("sale_history")
                .in_field("building"),
        );
    }
    for (index, building) in r.more.improvements.iter().enumerate() {
        if building.sale_history.as_ref().is_some_and(|history| !history.valid(building.cost)) {
            return Some(
                ValidationIssue::new("ISSUE_RENTAL_BUILDING_DEPRECIATION_RECORDS")
                    .at_field("sale_history")
                    .in_list("improvements", index)
                    .in_field("more"),
            );
        }
    }
    let improvements: &[Improvement] = &r.more.improvements;
    if !(0..=r.building.cost - r.building.land).contains(&r.building.credit_reduction) {
        return Some(
            ValidationIssue::new("RENTAL_CREDIT_REDUCTION_ABOVE_BASIS")
                .at_field("credit_reduction")
                .in_field("building"),
        );
    }
    if let Some(index) = improvements
        .iter()
        .position(|building| !(0..=building.cost).contains(&building.credit_reduction))
    {
        return Some(
            ValidationIssue::new("RENTAL_CREDIT_REDUCTION_ABOVE_BASIS")
                .at_field("credit_reduction")
                .in_list("improvements", index)
                .in_field("more"),
        );
    }
    for (index, improvement) in improvements.iter().enumerate() {
        let Some(claim) = &improvement.rehabilitation else {
            continue;
        };
        if improvement.in_service
            < crate::year_constants::REHABILITATION_FIRST_PLACED_YEAR * 10000 + 101
        {
            return Some(
                ValidationIssue::new("REHABILITATION_NEEDS_AN_IMPROVEMENT_ROW")
                    .at_field("in_service")
                    .in_list("improvements", index)
                    .in_field("more"),
            );
        }
        if claim.period_start >= improvement.in_service {
            return Some(
                ValidationIssue::new("REHABILITATION_PERIOD_AFTER_PLACED")
                    .at_field("period_start")
                    .in_field("rehabilitation")
                    .in_list("improvements", index)
                    .in_field("more"),
            );
        }
        if let Some(issue) = claim.issue(improvement.in_service, improvement.cost) {
            return Some(
                issue.in_field("rehabilitation").in_list("improvements", index).in_field("more"),
            );
        }
    }
    if let Some(statement) = &r.statement {
        match r.sale {
            crate::RentalSale::Sold { date, price, .. } => {
                if date != statement.closed {
                    return Some(
                        ValidationIssue::new("RENTAL_STATEMENT_DATE_DIFFERS")
                            .at_field("date")
                            .in_field("sale"),
                    );
                }
                if price != statement.proceeds {
                    return Some(
                        ValidationIssue::new("RENTAL_STATEMENT_PROCEEDS_DIFFER")
                            .at_field("price")
                            .in_field("sale"),
                    );
                }
            }
            crate::RentalSale::Exchanged(ref exchange) => {
                if exchange.transferred != statement.closed {
                    return Some(
                        ValidationIssue::new("RENTAL_STATEMENT_DATE_DIFFERS")
                            .at_field("transferred")
                            .in_field("sale"),
                    );
                }
            }
            crate::RentalSale::Condemned { date, award, .. } => {
                if date != statement.closed {
                    return Some(
                        ValidationIssue::new("RENTAL_STATEMENT_DATE_DIFFERS")
                            .at_field("date")
                            .in_field("sale"),
                    );
                }
                if award != statement.proceeds {
                    return Some(
                        ValidationIssue::new("RENTAL_STATEMENT_PROCEEDS_DIFFER")
                            .at_field("award")
                            .in_field("sale"),
                    );
                }
            }
            crate::RentalSale::No => {}
        }
    }
    if let crate::RentalSale::Sold {
        date,
        price,
        land_price,
        ref payment,
        buyer,
        personal_share_percent,
        ..
    } = r.sale
    {
        if buyer != crate::Buyer::Unrelated && payment.installment() {
            return Some(
                ValidationIssue::new("INSTALLMENT_RELATED_BUYER")
                    .at_field("buyer")
                    .in_field("sale"),
            );
        }
        if personal_share_percent == 0 && !matches!(r.personal_use, PersonalUse::No) {
            return Some(
                ValidationIssue::new("RENTAL_SALE_PERSONAL_SHARE_NEEDED")
                    .at_field("personal_share_percent")
                    .in_field("sale"),
            );
        }
        if let Some(issue) = payment.issue(price) {
            return Some(issue.in_field("payment").in_field("sale"));
        }
        if core::iter::once(r.building.in_service)
            .chain(improvements.iter().map(|b| b.in_service))
            .any(|in_service| in_service >= date)
        {
            return Some(
                ValidationIssue::new("RENTAL_SOLD_BEFORE_IN_SERVICE")
                    .at_field("date")
                    .in_field("sale"),
            );
        }
        if land_price > price {
            return Some(
                ValidationIssue::new("RENTAL_LAND_PRICE_ABOVE_PRICE")
                    .at_field("land_price")
                    .in_field("sale"),
            );
        }
    }
    if let crate::RentalSale::Condemned { date, award, land_award, .. } = r.sale {
        if land_award > award {
            return Some(
                ValidationIssue::new("CONDEMNATION_LAND_ABOVE_AWARD")
                    .at_field("land_award")
                    .in_field("sale"),
            );
        }
        if core::iter::once(r.building.in_service)
            .chain(improvements.iter().map(|b| b.in_service))
            .any(|in_service| in_service >= date)
        {
            return Some(
                ValidationIssue::new("RENTAL_SOLD_BEFORE_IN_SERVICE")
                    .at_field("date")
                    .in_field("sale"),
            );
        }
    }
    for (index, (part, cost, in_service)) in core::iter::once((
        &r.building.partial,
        r.building.cost - r.building.land,
        r.building.in_service,
    ))
    .chain(
        improvements.iter().map(|building| (&building.partial, building.cost, building.in_service)),
    )
    .enumerate()
    {
        if let Some(part) = part {
            let key = if part.cost_of_part >= cost {
                Some(("PARTIAL_DISPOSITION_PART_ABOVE_COST", "cost_of_part"))
            } else if part.date <= in_service {
                Some(("PARTIAL_DISPOSITION_BEFORE_SERVICE", "date"))
            } else {
                None
            };
            if let Some((key, field)) = key {
                let issue = ValidationIssue::new(key).at_field(field).in_field("partial");
                return Some(if index == 0 {
                    issue.in_field("building")
                } else {
                    issue.in_list("improvements", index - 1).in_field("more")
                });
            }
        }
    }
    if let crate::RentalSale::Exchanged(ref exchange) = r.sale {
        if core::iter::once(r.building.in_service)
            .chain(improvements.iter().map(|b| b.in_service))
            .any(|in_service| in_service >= exchange.transferred)
        {
            return Some(
                ValidationIssue::new("RENTAL_EXCHANGED_BEFORE_IN_SERVICE")
                    .at_field("transferred")
                    .in_field("sale"),
            );
        }
        if let Some(issue) = exchange.issue() {
            return Some(issue.in_field("sale"));
        }
    }
    match r.personal_use {
        PersonalUse::Yes { fair_rental_days, personal_days, .. }
            if fair_rental_days + personal_days > 365 =>
        {
            Some(
                ValidationIssue::new("RENTAL_DAYS_ABOVE_365")
                    .at_field("personal_days")
                    .in_field("personal_use"),
            )
        }
        PersonalUse::Yes { fair_rental_days, overlap_days, .. }
            if overlap_days > fair_rental_days =>
        {
            Some(
                ValidationIssue::new("RENTAL_OVERLAP_DAYS_ABOVE_RENTAL_DAYS")
                    .at_field("overlap_days")
                    .in_field("personal_use"),
            )
        }
        _ => None,
    }
    .or_else(|| {
        r.assets.iter().enumerate().find_map(|(index, asset)| {
            asset_partial_issue(asset_class(asset.class), asset.cost, asset.placed, &asset.partial)
                .map(|issue| issue.in_list("assets", index))
        })
    })
}

// Whether the return holds a self-employment business, which the
// self-employed benefits topic needs (M3-P8: offered only when one exists).
fn has_ordinary_business(d: &FederalDraft) -> bool {
    d.income.iter().any(|e| topic_of(d, e) == Some(TaxSection::SelfEmployment))
}
fn has_farm(d: &FederalDraft) -> bool {
    d.income.iter().any(|e| {
        matches!(e.income, FederalIncome::Business { .. })
            && topic_of(d, e) == Some(TaxSection::Farming)
    })
}
// The self-employed benefits page is offered while a business or a
// partnership K-1 exists (T2-43p: a row per Schedule K-1 (Form 1065)).
fn has_benefit_rows(d: &FederalDraft) -> bool {
    d.income.iter().any(|e| {
        matches!(
            e.income,
            FederalIncome::Business { .. }
                | FederalIncome::Partnership { .. }
                | FederalIncome::Scorp { .. }
                | FederalIncome::PartnershipActivities { .. }
                | FederalIncome::ScorpActivities { .. }
        )
    })
}
// The box 7 code onto `RetirementTreatment`. `gross` supplies code G's
// rollover amount (a direct rollover transfers the whole distribution).
// The HSA page (M3-P7) is a projection of FederalAdjustments.hsa and
// hsa_family_share. The shared employer-source owner allocates W-2 R/W by
// actual contribution year; the account's editable amount is outside sources.
pub(crate) fn box12_total(d: &FederalDraft, owner: Owner, code: W2Code) -> i64 {
    d.income
        .iter()
        .filter(|e| e.owner == owner)
        .map(|e| match &e.income {
            FederalIncome::Wage { data } => {
                data.other_box12.iter().filter(|c| c.code == code).map(|c| c.amount).sum()
            }
            _ => 0,
        })
        .sum()
}
fn hsa_accounts(d: &FederalDraft) -> &[FederalHsa] {
    d.adjustments.as_ref().map_or(&[], |a| &a.hsa)
}
fn health_correction_reference_rule(d: &FederalDraft) -> Option<&'static str> {
    health_correction_income_issue(d, d, &[]).map(|issue| issue.key)
}
// A health relationship can be broken by editing its actual income source.
// The retained account field is outside an income request; identify only a
// changed source that is actually submitted. Deletions and unchanged retained
// payments (including one whose inherited group was removed) remain unlocated.
fn health_income_source_issue(
    issue: ValidationIssue,
    source: Option<i64>,
    original: &FederalDraft,
    candidate: &FederalDraft,
    origins: &[(i64, usize, bool)],
) -> ValidationIssue {
    let unlocated = || ValidationIssue::new(issue.key);
    let Some(id) = source else {
        return unlocated();
    };
    let Some((_, index, _)) = origins.iter().find(|(source, _, _)| *source == id) else {
        return unlocated();
    };
    let Some(before) = original.income.iter().find(|entry| entry.id == id) else {
        return unlocated();
    };
    let Some(after) = candidate.income.iter().find(|entry| entry.id == id) else {
        return unlocated();
    };
    let field = if before.owner != after.owner && before.income == after.income {
        "owner"
    } else if before.income != after.income {
        // Source availability and aggregate deposit capacity govern the
        // submitted source record, not a guessed child of its active Union.
        "document"
    } else {
        return unlocated();
    };
    unlocated().at_field(field).in_list("documents", *index).in_field("documents")
}
fn health_correction_income_issue(
    original: &FederalDraft,
    candidate: &FederalDraft,
    origins: &[(i64, usize, bool)],
) -> Option<ValidationIssue> {
    use crate::hsa_correction::CorrectionSource;
    if let Some((source, issue)) = crate::health_employer::reference_issue(
        candidate,
        crate::health_employer::bindings(candidate),
    ) {
        return Some(health_income_source_issue(issue, source, original, candidate, origins));
    }
    if let Some(failure) = crate::hsa_funding::source_reference_issue(candidate) {
        return Some(health_income_source_issue(
            failure.issue,
            failure.income_source,
            original,
            candidate,
            origins,
        ));
    }
    if let Some((location, issue)) = crate::medical_rollover::correction_reference_issue(candidate)
    {
        let source = match location {
            CorrectionSource::Hsa { correction, .. } => correction.failed_deposit,
            CorrectionSource::Archer { correction, .. } => correction.failed_deposit,
            CorrectionSource::Document { id, .. } => Some(id),
        };
        return Some(health_income_source_issue(issue, source, original, candidate, origins));
    }
    let correction_source = |(location, issue)| {
        let source = match location {
            CorrectionSource::Hsa { correction, .. } => correction.document,
            CorrectionSource::Archer { correction, .. } => correction.document,
            CorrectionSource::Document { id, .. } => Some(id),
        };
        health_income_source_issue(issue, source, original, candidate, origins)
    };
    crate::hsa_correction::reference_issue(hsa_accounts(candidate), &candidate.income)
        .or_else(|| {
            candidate.adjustments.as_ref().and_then(|adjustments| {
                crate::hsa_correction::archer_reference_issue(
                    &adjustments.archer,
                    &candidate.income,
                )
            })
        })
        .map(correction_source)
}
// Graph failures carry source facts, never a canonical-list position. Resolve
// those facts against this submitted page before composing its locator.
fn hsa_correction_page_issue(
    page: &HsaPage,
    draft: &FederalDraft,
    failure: crate::hsa_correction::CorrectionReferenceIssue,
) -> ValidationIssue {
    use crate::hsa_correction::CorrectionSource;
    let (source, issue) = failure;
    match source {
        CorrectionSource::Hsa { owner, correction } => {
            for (i, account) in page.accounts.iter().enumerate() {
                if account.owner == owner
                    && let Some(j) =
                        account.corrections.iter().position(|c| c.record() == correction)
                {
                    return issue
                        .in_list("corrections", j)
                        .in_list("accounts", i)
                        .in_field("value");
                }
            }
            issue.at_field("accounts").in_field("value")
        }
        CorrectionSource::Archer { owner, correction } => {
            if let crate::ArcherContributionsPage::Records { owners, .. } = &page.archer {
                for (i, account) in owners.iter().enumerate() {
                    if account.owner == owner
                        && let Some(j) =
                            account.corrections.iter().position(|c| c.record() == correction)
                    {
                        return issue
                            .in_list("corrections", j)
                            .in_list("owners", i)
                            .in_field("archer")
                            .in_field("value");
                    }
                }
            }
            issue.at_field("archer").in_field("value")
        }
        CorrectionSource::Document { owner, id } => {
            // Missing details and aggregate gross/earnings belong to the
            // editable correction collection; source-document fields are not
            // fields of an account or a particular submitted correction.
            let hsa = draft.income.iter().any(|e| {
                e.id == id
                    && e.owner == owner
                    && matches!(&e.income, FederalIncome::MedicalDistribution { data }
                    if matches!(data.account, crate::MedicalSaAccount::Hsa))
            });
            if hsa {
                if let Some(i) = page.accounts.iter().position(|a| a.owner == owner) {
                    return issue.at_field("corrections").in_list("accounts", i).in_field("value");
                }
                issue.at_field("accounts").in_field("value")
            } else {
                if let crate::ArcherContributionsPage::Records { owners, .. } = &page.archer
                    && let Some(i) = owners.iter().position(|a| a.owner == owner)
                {
                    return issue
                        .at_field("corrections")
                        .in_list("owners", i)
                        .in_field("archer")
                        .in_field("value");
                }
                issue.at_field("archer").in_field("value")
            }
        }
    }
}
fn hsa_funding_page_issue(
    page: &HsaPage,
    failure: crate::hsa_funding::FundingReferenceIssue,
) -> ValidationIssue {
    use crate::hsa_funding::FundingIssueLocation;
    let issue = failure.issue;
    match failure.location {
        FundingIssueLocation::Transfer { owner, transfer } => {
            if let Some(i) =
                page.funding.iter().position(|f| f.owner == owner && f.record() == transfer)
            {
                issue.in_list("funding", i).in_field("value")
            } else {
                issue.at_field("funding").in_field("value")
            }
        }
        FundingIssueLocation::Account { owner } => {
            if let Some(i) = page.accounts.iter().position(|a| a.owner == owner) {
                issue.in_list("accounts", i).in_field("value")
            } else {
                issue.at_field("accounts").in_field("value")
            }
        }
        FundingIssueLocation::Selection { owner } => {
            if page.accounts.iter().any(|a| a.owner == owner) {
                issue.in_field("value")
            } else {
                issue.at_field("accounts").in_field("value")
            }
        }
    }
}
fn hsa_limit_method(d: &FederalDraft) -> HsaAllocationMethod {
    let share = d.adjustments.as_ref().and_then(|a| a.hsa_family_share.as_ref());
    // Older records used the last-month rule automatically outside a
    // married family allocation. Reopen a material old December choice
    // explicitly so saving an unchanged record preserves its tax result.
    let legacy_december = share.is_none()
        && !(d.setup.as_ref().is_some_and(|s| s.marital_state.married())
            && hsa_accounts(d)
                .iter()
                .any(|h| (0..12).any(|m| h.coverage.month(m) == HsaCoverage::Family)))
        && hsa_accounts(d).iter().any(|h| {
            h.coverage.month(11) != HsaCoverage::None
                && (0..12).any(|m| h.coverage.month(m) != h.coverage.month(11))
        });
    share.map_or(
        if legacy_december { HsaAllocationMethod::December } else { HsaAllocationMethod::Monthly },
        |s| s.method,
    )
}
// An owner whose W-2 reports employer HSA contributions but who has no
// account on the HSA page.
fn hsa_account_missing(d: &FederalDraft) -> bool {
    if crate::health_employer::mandatory_rule(d, crate::health_employer::bindings(d)).is_some() {
        return true;
    }
    [Owner::Taxpayer, Owner::Spouse].into_iter().any(|owner| {
        crate::health_employer::source_totals(d, crate::health_employer::bindings(d), owner, crate::HealthEmployerKind::Hsa).is_ok_and(|(current, _)| current > 0) && !hsa_accounts(d).iter().any(|h| h.owner == owner)
    }) || crate::medical_rollover::deposit_choices(d,None).iter().any(|source| source.deposits.iter().any(|f| f.year == crate::HEALTH_TAX_YEAR && match f.destination {
        crate::MedicalRolloverDestination::Hsa => !hsa_accounts(d).iter().any(|h|h.owner == source.owner),
        crate::MedicalRolloverDestination::Archer => !d.adjustments.as_ref().is_some_and(|a|matches!(&a.archer,crate::ArcherContributions::Records{owners,..} if owners.iter().any(|v|v.owner == source.owner))),
    }))
}
// The existing contribution owners retain one derived current-year total,
// from accepted source-year allocations plus outside-source principal.
fn derive_hsa_employer(d: &mut FederalDraft) {
    let Some(a) = d.adjustments.as_ref() else {
        return;
    };
    let bindings = &a.health_employer_w2;
    let hsa: Vec<_> = a
        .hsa
        .iter()
        .map(|h| {
            crate::health_employer::effective_total(
                d,
                bindings,
                h.owner,
                crate::HealthEmployerKind::Hsa,
                h.employer_outside,
            )
        })
        .collect();
    let archer: Vec<_> = match &a.archer {
        crate::ArcherContributions::None => Vec::new(),
        crate::ArcherContributions::Records { owners, .. } => owners
            .iter()
            .map(|h| {
                crate::health_employer::effective_total(
                    d,
                    bindings,
                    h.owner,
                    crate::HealthEmployerKind::Archer,
                    h.employer_outside,
                )
            })
            .collect(),
    };
    if let Some(a) = d.adjustments.as_mut() {
        for (h, amount) in a.hsa.iter_mut().zip(hsa) {
            if let Ok(amount) = amount {
                h.employer = amount;
            }
        }
        if let crate::ArcherContributions::Records { owners, .. } = &mut a.archer {
            for (h, amount) in owners.iter_mut().zip(archer) {
                if let Ok(amount) = amount {
                    h.employer = amount;
                }
            }
        }
    }
}
// Both eligible spouses share the family limit when either has family
// coverage in that month. A self-only policy for the other spouse does not
// avoid Form8889 line6. Equal is the default; Agreed records an actual choice.
fn allowed_family_split(
    accounts: &[HsaAccount],
    d: &FederalDraft,
    other: Option<&HsaEligibility>,
    method: HsaAllocationMethod,
) -> Vec<i32> {
    let married = d.setup.as_ref().is_some_and(|s| s.marital_state.married());
    let eligible = [
        d.people.as_ref().is_some_and(|p| !p.taxpayer.dependency.claimable()),
        d.people.as_ref().and_then(|p| p.spouse.as_ref()).is_none_or(|p| !p.dependency.claimable()),
    ];
    let coverage = |m: usize| {
        let mut values = [HsaCoverage::None; 2];
        for i in 0..2 {
            if !eligible[i] {
                continue;
            }
            if let Some(a) = accounts.iter().find(|a| usize::from(a.owner == Owner::Spouse) == i) {
                values[i] = match &a.coverage {
                    HsaCoverageYear::SelfOnly => HsaCoverage::SelfOnly,
                    HsaCoverageYear::Family => HsaCoverage::Family,
                    HsaCoverageYear::Changed { months } => {
                        months.get(m).copied().unwrap_or(HsaCoverage::None)
                    }
                };
            } else if accounts.len() == 1 {
                values[i] = other.map_or(HsaCoverage::None, |c| c.month(m));
            }
        }
        values
    };
    let shared_month = |m| {
        let values = coverage(m);
        values.contains(&HsaCoverage::Family) && values.iter().all(|c| *c != HsaCoverage::None)
    };
    let shared = married
        && !accounts.is_empty()
        && (accounts.len() == 1 || accounts[0].owner != accounts[1].owner)
        && if method == HsaAllocationMethod::December {
            shared_month(11)
        } else {
            (0..12).any(shared_month)
        };
    if shared {
        alloc::vec![
            libertas_macros::variant_index!(FamilySplit::Equal) as i32,
            libertas_macros::variant_index!(FamilySplit::Agreed) as i32,
        ]
    } else {
        alloc::vec![libertas_macros::variant_index!(FamilySplit::NotApplicable) as i32]
    }
}

fn family_split_index(split: &FamilySplit) -> i32 {
    (match split {
        FamilySplit::NotApplicable => libertas_macros::variant_index!(FamilySplit::NotApplicable),
        FamilySplit::Equal => libertas_macros::variant_index!(FamilySplit::Equal),
        FamilySplit::Agreed { .. } => libertas_macros::variant_index!(FamilySplit::Agreed),
    }) as i32
}
// An account onto its record, with the IRA-to-HSA transfers of its owner (the
// page lists the transfers once, each naming its owner).
fn hsa_record(account: &HsaAccount, employer: i64, funding: &[crate::HsaFundingRow]) -> FederalHsa {
    FederalHsa {
        owner: account.owner,
        coverage: match &account.coverage {
            HsaCoverageYear::SelfOnly => {
                HsaEligibility::FullYear { coverage: HsaCoverage::SelfOnly }
            }
            HsaCoverageYear::Family => HsaEligibility::FullYear { coverage: HsaCoverage::Family },
            HsaCoverageYear::Changed { months } => {
                HsaEligibility::Monthly { months: months.clone() }
            }
        },
        personal: account.personal,
        employer,
        employer_outside: account.employer,
        late_excess: account.late_excess.clone(),
        prior_employer_excess: account.prior_employer_excess.clone(),
        corrections: account.corrections.iter().map(crate::HsaCorrectionPage::record).collect(),
        excess_accounting: account.excess_accounting.clone(),
        last_month_loss: account.last_month_loss.clone(),
        last_month_history: account.last_month_history.clone(),
        funding: funding
            .iter()
            .filter(|row| row.owner == account.owner)
            .map(crate::HsaFundingRow::record)
            .collect(),
        funding_history: account.funding_history.clone(),
        uses: account.uses.clone(),
    }
}
// The page's account for a stored record.
pub(crate) fn hsa_item(record: &FederalHsa, employer: i64) -> HsaAccount {
    let coverage = match &record.coverage {
        HsaEligibility::FullYear { coverage: HsaCoverage::SelfOnly } => HsaCoverageYear::SelfOnly,
        HsaEligibility::FullYear { coverage: HsaCoverage::Family } => HsaCoverageYear::Family,
        HsaEligibility::FullYear { coverage: HsaCoverage::None } => {
            HsaCoverageYear::Changed { months: alloc::vec![HsaCoverage::None; 12] }
        }
        HsaEligibility::Monthly { months } => HsaCoverageYear::Changed { months: months.clone() },
    };
    HsaAccount {
        owner: record.owner,
        coverage,
        personal: record.personal,
        employer,
        corrections: record.corrections.iter().map(crate::HsaCorrection::page).collect(),
        late_excess: record.late_excess.clone(),
        prior_employer_excess: record.prior_employer_excess.clone(),
        excess_accounting: record.excess_accounting.clone(),
        last_month_loss: record.last_month_loss.clone(),
        last_month_history: record.last_month_history.clone(),
        funding_history: record.funding_history.clone(),
        uses: record.uses.clone(),
    }
}
// An income record as a choice: its document and whose it is.
fn source_choice(entry: &FederalIncomeEntry) -> crate::RecordChoice {
    crate::RecordChoice {
        id: entry.id,
        label: crate::Message::new(
            "SOURCE_DOCUMENT_CHOICE",
            alloc::vec![
                crate::MessageArg::Nested(alloc::boxed::Box::new(
                    income_issue_context(entry).label()
                )),
                crate::MessageArg::Resource(
                    if entry.owner == Owner::Spouse { "PERSON_SPOUSE" } else { "PERSON_YOU" }
                        .into()
                ),
            ],
        )
        .encode(),
    }
}
// The split onto hsa_family_share: the monthly method, one part each when
// equal.
fn family_share_record(
    split: FamilySplit,
    method: HsaAllocationMethod,
    other_coverage: Option<HsaEligibility>,
    accounts: usize,
) -> Option<HsaFamilyShare> {
    if accounts == 0 {
        return None;
    }
    let (taxpayer_parts, spouse_parts) = match split {
        FamilySplit::NotApplicable | FamilySplit::Equal => (1, 1),
        FamilySplit::Agreed { you, spouse } => (you, spouse),
    };
    Some(HsaFamilyShare { method, taxpayer_parts, spouse_parts, other_coverage })
}
fn family_split_item(share: Option<&HsaFamilyShare>) -> FamilySplit {
    match share.map(|v| (v.taxpayer_parts, v.spouse_parts)) {
        None => FamilySplit::NotApplicable,
        Some((1, 1)) => FamilySplit::Equal,
        Some((you, spouse)) => FamilySplit::Agreed { you, spouse },
    }
}
// The self-employed benefits page's rows: one per business, built from
// FederalBusiness.health_insurance/.retirement (M3-P8). None for a business
// whose stored facts this page cannot represent (a shape only a direct
// fixture, not this page, can create).
pub(crate) fn business_benefit_rows(d: &FederalDraft) -> Option<Vec<BusinessBenefits>> {
    d.income
        .iter()
        .filter_map(|e| match &e.income {
            FederalIncome::Business { data } => Some((e, data)),
            _ => None,
        })
        .map(|(e, data)| {
            Some(BusinessBenefits {
                id: e.id,
                name: income_issue_context(e).label().encode(),
                health: se_health_page(&data.health_insurance)?,
                retirement: se_retirement_page(&data.retirement)?,
            })
        })
        .collect()
}
// The self-employed benefits page's partnership rows (T2-43p): one per
// Schedule K-1 (Form 1065), built from PartnerK1; boxes 13 code M and R and
// box 19 code A are copied from the K-1 record. None for a stored shape the
// page cannot show (an unconfirmed SEP).
pub(crate) fn partner_benefit_rows(d: &FederalDraft) -> Option<Vec<PartnerBenefits>> {
    d.income
        .iter()
        .filter_map(|e| match &e.income {
            FederalIncome::Partnership { data } => Some((e, data)),
            _ => None,
        })
        .map(|(e, data)| {
            let health = se_health_page(&data.health_insurance)?;
            Some(PartnerBenefits {
                id: e.id,
                name: income_issue_context(e).label().encode(),
                medical_insurance: data.health_guaranteed,
                pensions: data.pensions,
                cash_distributions: data.regular.basis.distributions,
                health,
                from_distributions: data.health_distributions,
                retirement: partner_plan_page(&data.retirement),
            })
        })
        .collect()
}
pub(crate) fn activity_partner_benefit_rows(
    d: &FederalDraft,
) -> Option<Vec<crate::K1ActivityPartnerBenefits>> {
    d.income
        .iter()
        .filter_map(|entry| match &entry.income {
            FederalIncome::PartnershipActivities { data } => Some((entry, data)),
            _ => None,
        })
        .map(|(entry, data)| {
            Some(crate::K1ActivityPartnerBenefits {
                id: entry.id,
                name: income_issue_context(entry).label().encode(),
                medical_insurance: data.person.as_ref().and_then(|v| v.health_guaranteed),
                pensions: data.person.as_ref().and_then(|v| v.pensions),
                cash_distributions: data.entity.regular.distributions,
                health: match data.health_insurance.as_ref() {
                    Some(value) => Some(se_health_page(value)?),
                    None => None,
                },
                from_distributions: data.person.as_ref().and_then(|v| v.health_distributions),
                retirement: data.retirement.as_ref().map(partner_plan_page),
            })
        })
        .collect()
}

pub(crate) fn activity_scorp_benefit_rows(
    d: &FederalDraft,
) -> Option<Vec<crate::K1ActivityScorpBenefits>> {
    d.income
        .iter()
        .filter_map(|entry| match &entry.income {
            FederalIncome::ScorpActivities { data } => Some((entry, data)),
            _ => None,
        })
        .map(|(entry, data)| {
            Some(crate::K1ActivityScorpBenefits {
                activity: entry.id,
                name: income_issue_context(entry).label().encode(),
                health: match data.health_insurance.as_ref() {
                    Some(value) => Some(se_health_page(value)?),
                    None => None,
                },
            })
        })
        .collect()
}
pub(crate) fn scorp_benefit_rows(d: &FederalDraft) -> Option<Vec<HealthPlanPage>> {
    d.income
        .iter()
        .filter_map(|e| match &e.income {
            FederalIncome::Scorp { data } => Some((e, data)),
            _ => None,
        })
        .map(|(e, data)| {
            Some(HealthPlanPage {
                activity: e.id,
                name: income_issue_context(e).label().encode(),
                health: se_health_page(&data.health_insurance)?,
            })
        })
        .collect()
}
// The names of the self-employed benefits page's rows with something
// entered, businesses first (T2-43p: partnerships too).
fn benefits_entered(d: &FederalDraft) -> Vec<Vec<u8>> {
    let businesses = business_benefit_rows(d).unwrap_or_default();
    let partnerships = partner_benefit_rows(d).unwrap_or_default();
    businesses
        .into_iter()
        .filter(|b| {
            !matches!(b.health, SeHealth::None) || !matches!(b.retirement, SeRetirement::None)
        })
        .map(|b| b.name)
        .chain(
            partnerships
                .into_iter()
                .filter(|p| {
                    !matches!(p.health, SeHealth::None)
                        || p.retirement != PartnerPlan::None
                        || p.from_distributions != 0
                })
                .map(|p| p.name),
        )
        .chain(
            scorp_benefit_rows(d)
                .unwrap_or_default()
                .into_iter()
                .filter(|p| !matches!(p.health, SeHealth::None))
                .map(|p| p.name),
        )
        .chain(
            activity_partner_benefit_rows(d)
                .unwrap_or_default()
                .into_iter()
                .filter(|v| {
                    v.health.as_ref().is_some_and(|h| !matches!(h, SeHealth::None))
                        || v.retirement.as_ref().is_some_and(|r| !matches!(r, PartnerPlan::None))
                        || v.from_distributions.is_some_and(|value| value != 0)
                })
                .map(|v| v.name),
        )
        .chain(
            activity_scorp_benefit_rows(d)
                .unwrap_or_default()
                .into_iter()
                .filter(|v| v.health.as_ref().is_some_and(|h| !matches!(h, SeHealth::None)))
                .map(|v| v.name),
        )
        .collect()
}
// The self-employed benefits topic is necessary while nothing is entered on
// it and a business exists or a partnership K-1 shows box 13 code M or R
// (T2-43p, question Q7: an investor's K-1 does not suggest an empty page).
fn benefits_needed(d: &FederalDraft) -> bool {
    benefits_entered(d).is_empty()
        && d.income.iter().any(|e| match &e.income {
            FederalIncome::Business { .. } | FederalIncome::Scorp { .. } => true,
            FederalIncome::Partnership { data } => {
                data.health_guaranteed != 0 || data.pensions != 0
            }
            FederalIncome::PartnershipActivities { data } => {
                data.person.as_ref().is_some_and(|v| {
                    v.health_guaranteed.is_some_and(|value| value != 0)
                        || v.pensions.is_some_and(|value| value != 0)
                })
            }
            FederalIncome::ScorpActivities { .. } => true,
            _ => false,
        })
}
// Native admission for one partnership row uses the accepted K-1 source,
// never the row's read-only copies. Canonical plan validation precedes these
// payment/plan relationships, which retain their existing native messages.
fn partner_benefit_issue(row: &PartnerBenefits, data: &PartnerK1) -> Option<ValidationIssue> {
    partner_benefit_source_issue(
        Some(&row.health),
        Some(data.health_guaranteed),
        Some(row.from_distributions),
        data.regular.basis.distributions,
        Some(data.pensions),
        Some(&row.retirement),
    )
    .map(|issue| {
        if issue.key == "PARTNER_PREMIUMS_BELOW_K1" {
            issue.map_field_prefix(&["health"], &["from_distributions"])
        } else {
            issue
        }
    })
}
fn partner_plan_page(value: &PartnerRetirement) -> PartnerPlan {
    match value {
        PartnerRetirement::None => PartnerPlan::None,
        PartnerRetirement::Sep { rate } => PartnerPlan::Sep { rate: *rate },
        PartnerRetirement::Plan(BusinessRetirement::Simple {
            deferral,
            employer,
            employer_contribution,
        }) => PartnerPlan::Simple {
            deferral: *deferral,
            employer: *employer,
            employer_contribution: *employer_contribution,
        },
        PartnerRetirement::Plan(BusinessRetirement::Qualified {
            rate,
            contribution,
            deferral,
            catch_up,
            roth,
        }) => PartnerPlan::Qualified {
            rate: *rate,
            contribution: *contribution,
            deferral: *deferral,
            catch_up: *catch_up,
            roth: *roth,
        },
        PartnerRetirement::Plan(BusinessRetirement::DefinedBenefit { contribution }) => {
            PartnerPlan::DefinedBenefit { contribution: *contribution }
        }
        PartnerRetirement::Plan(_) | PartnerRetirement::Other => PartnerPlan::Other,
    }
}

fn partner_plan_record(value: &PartnerPlan) -> PartnerRetirement {
    match value {
        PartnerPlan::None => PartnerRetirement::None,
        PartnerPlan::Sep { rate } => PartnerRetirement::Sep { rate: *rate },
        PartnerPlan::Simple { deferral, employer, employer_contribution } => {
            PartnerRetirement::Plan(BusinessRetirement::Simple {
                deferral: *deferral,
                employer: *employer,
                employer_contribution: *employer_contribution,
            })
        }
        PartnerPlan::Qualified { rate, contribution, deferral, catch_up, roth } => {
            PartnerRetirement::Plan(BusinessRetirement::Qualified {
                rate: *rate,
                contribution: *contribution,
                deferral: *deferral,
                catch_up: *catch_up,
                roth: *roth,
            })
        }
        PartnerPlan::DefinedBenefit { contribution } => {
            PartnerRetirement::Plan(BusinessRetirement::DefinedBenefit {
                contribution: *contribution,
            })
        }
        PartnerPlan::Other => PartnerRetirement::Other,
    }
}

fn partner_benefit_source_issue(
    health: Option<&SeHealth>,
    medical: Option<i64>,
    payment: Option<i64>,
    distributions: i64,
    pensions: Option<i64>,
    retirement: Option<&PartnerPlan>,
) -> Option<crate::validation::ValidationIssue> {
    if let Some(health) = health {
        let premiums = match health {
            SeHealth::None => Some(0),
            SeHealth::Plan { months, long_term_care, .. } => crate::kernel::ratio::checked_sum(
                months
                    .iter()
                    .map(|m| m.premiums)
                    .chain(long_term_care.iter().flat_map(|p| &p.months).map(|m| m.premiums)),
            ),
        };
        let Some(premiums) = premiums else {
            return Some(
                crate::validation::ValidationIssue::new("PROBLEM_INVALID_HEALTH_PLAN_SOURCE")
                    .at_field("health"),
            );
        };
        // Both sources are nonnegative. One actually known part exceeding the
        // complete premium total proves a contradiction independently of the
        // other unknown part; it is never used as a zero for a deduction.
        let known_parts = match (medical, payment) {
            (Some(a), Some(b)) => {
                // The medical part is an accepted nonnegative source, and the
                // canonical plan owner bounds every premium before this call.
                // Positive overflow therefore proves this same mathematical
                // sum exceeds premiums. Negative submitted payments still reach
                // the existing later intrinsic source guard in its old order.
                let Some(total) = crate::kernel::ratio::checked_sum([a, b]) else {
                    return Some(
                        crate::validation::ValidationIssue::new("PARTNER_PREMIUMS_BELOW_K1")
                            .at_field("health"),
                    );
                };
                Some(total)
            }
            (Some(a), None) | (None, Some(a)) => Some(a),
            (None, None) => None,
        };
        if known_parts.is_some_and(|v| v > premiums) {
            return Some(
                crate::validation::ValidationIssue::new("PARTNER_PREMIUMS_BELOW_K1")
                    .at_field("health"),
            );
        }
    }
    if payment.is_some_and(|v| v > distributions) {
        return Some(
            crate::validation::ValidationIssue::new("PARTNER_DISTRIBUTION_PREMIUMS_ABOVE_19A")
                .at_field("from_distributions"),
        );
    }
    match (pensions, retirement) {
        (Some(value), Some(PartnerPlan::None)) if value != 0 => Some(
            crate::validation::ValidationIssue::new("PARTNER_BOX_13R_NEEDS_PLAN")
                .at_field("retirement"),
        ),
        (Some(0), Some(plan)) if *plan != PartnerPlan::None => Some(
            crate::validation::ValidationIssue::new("PARTNER_PLAN_WITHOUT_BOX_13R")
                .at_field("retirement"),
        ),
        _ => None,
    }
}

fn activity_partner_benefit_record_issue(
    data: &crate::PartnerActivityK1,
) -> Option<crate::validation::ValidationIssue> {
    let health = match data.health_insurance.as_ref() {
        Some(source) => Some(se_health_page(source)?),
        None => None,
    };
    let retirement = data.retirement.as_ref().map(partner_plan_page);
    partner_benefit_source_issue(
        health.as_ref(),
        data.person.as_ref().and_then(|v| v.health_guaranteed),
        data.person.as_ref().and_then(|v| v.health_distributions),
        data.entity.regular.distributions,
        data.person.as_ref().and_then(|v| v.pensions),
        retirement.as_ref(),
    )
}
// Every accepted premium plan reopens with all its source facts.
fn se_health_page(value: &BusinessHealthInsurance) -> Option<SeHealth> {
    Some(match value {
        BusinessHealthInsurance::None => SeHealth::None,
        BusinessHealthInsurance::Plan { months, long_term_care, establishment } => SeHealth::Plan {
            establishment: establishment.clone().into(),
            months: months.clone(),
            long_term_care: long_term_care.iter().cloned().map(Into::into).collect(),
        },
    })
}
fn se_health_insurance(value: &SeHealth) -> BusinessHealthInsurance {
    match value {
        SeHealth::None => BusinessHealthInsurance::None,
        SeHealth::Plan { months, long_term_care, establishment } => BusinessHealthInsurance::Plan {
            establishment: establishment.clone().into(),
            months: months.clone(),
            long_term_care: long_term_care.iter().cloned().map(Into::into).collect(),
        },
    }
}
// The page's retirement choice for a stored plan.
fn se_retirement_page(value: &BusinessRetirement) -> Option<SeRetirement> {
    Some(match value {
        BusinessRetirement::None => SeRetirement::None,
        BusinessRetirement::Sep { contribution, rate } => {
            SeRetirement::Sep { contribution: *contribution, rate: *rate }
        }
        BusinessRetirement::Simple { deferral, employer, employer_contribution } => {
            SeRetirement::Simple {
                deferral: *deferral,
                employer: *employer,
                employer_contribution: *employer_contribution,
            }
        }
        BusinessRetirement::Qualified { rate, contribution, deferral, catch_up, roth } => {
            SeRetirement::Qualified {
                rate: *rate,
                contribution: *contribution,
                deferral: *deferral,
                catch_up: *catch_up,
                roth: *roth,
            }
        }
        BusinessRetirement::DefinedBenefit { contribution } => {
            SeRetirement::DefinedBenefit { contribution: *contribution }
        }
    })
}
fn se_retirement(value: &SeRetirement) -> BusinessRetirement {
    match value {
        SeRetirement::None => BusinessRetirement::None,
        SeRetirement::Sep { contribution, rate } => {
            BusinessRetirement::Sep { contribution: *contribution, rate: *rate }
        }
        SeRetirement::Simple { deferral, employer, employer_contribution } => {
            BusinessRetirement::Simple {
                deferral: *deferral,
                employer: *employer,
                employer_contribution: *employer_contribution,
            }
        }
        SeRetirement::Qualified { rate, contribution, deferral, catch_up, roth } => {
            BusinessRetirement::Qualified {
                rate: *rate,
                contribution: *contribution,
                deferral: *deferral,
                catch_up: *catch_up,
                roth: *roth,
            }
        }
        SeRetirement::DefinedBenefit { contribution } => {
            BusinessRetirement::DefinedBenefit { contribution: *contribution }
        }
    }
}
// "Covered by a retirement plan at work" (M3-P8): a W-2 box 13 retirement
// plan or a SEP contribution of this owner's own business or partnership.
pub(crate) fn ira_covered(d: &FederalDraft, owner: Owner) -> bool {
    d.income.iter().any(|e| {
        e.owner == owner
            && match &e.income {
                FederalIncome::Wage { data } => data.retirement_plan,
                FederalIncome::Business { data } => {
                    !matches!(data.retirement, BusinessRetirement::None)
                }
                FederalIncome::Partnership { data } => {
                    data.pensions != 0 || data.retirement != PartnerRetirement::None
                }
                _ => false,
            }
    }) || d.adjustments.as_ref().is_some_and(|a| {
        a.pension_contributions.iter().any(|p| p.owner == owner && p.contributions > 0)
    })
}
// Box 12 elective-deferral codes (401(k)/403(b)/SEP/457(b)/SIMPLE): one of
// the adjustments hub's hints to suggest the IRA topic.
fn ira_deferral_codes(d: &FederalDraft) -> bool {
    d.income.iter().any(|e| match &e.income {
        FederalIncome::Wage { data } => data
            .other_box12
            .iter()
            .any(|c| matches!(c.code, W2Code::D | W2Code::E | W2Code::F | W2Code::G | W2Code::S)),
        _ => false,
    })
}
// A 529-to-Roth transfer on a Form 1099-Q (box 4b): the earlier transfers the
// $35,000 lifetime ceiling counts are asked on the IRA topic.
fn ira_qtp_transfer(d: &FederalDraft) -> bool {
    !crate::ira::QtpTransfers::of(&d.income).is_empty()
}
// A prior year's Form 8606: the other hint to suggest the IRA topic.
fn ira_prior_return(d: &FederalDraft) -> bool {
    d.adjustments.as_ref().is_some_and(|a| !a.ira_basis.is_empty())
}
// The IRA page's rows for the stored FederalIras; empty when nothing is
// entered. None for a shape the page does not ask (a timely-returned
// contribution or a completed recharacterization).
fn ira_contributor_rows(d: &FederalDraft) -> Option<Vec<IraContributor>> {
    let Some(iras) = d.adjustments.as_ref().and_then(|a| a.entered_iras()) else {
        // An owner with a Form 8606 gets a zero row carrying its year-end
        // value, so an excess record added there need not repeat it (C18);
        // a zero row saves as no contributions.
        let joint = d.setup.as_ref().is_some_and(|s| s.filing_status() == FederalStatus::Joint);
        return Some(
            [Owner::Taxpayer, Owner::Spouse]
                .into_iter()
                .filter(|owner| *owner == Owner::Taxpayer || joint)
                .filter_map(|owner| {
                    form_8606_year_end(d, owner).map(|value| IraContributor {
                        owner,
                        traditional: 0,
                        roth: 0,
                        covered: ira_covered(d, owner),
                        form_8606_value: Some(value),
                        more: IraMore::default(),
                    })
                })
                .collect(),
        );
    };
    let mut people = alloc::vec![ira_contributor_item(Owner::Taxpayer, &iras.taxpayer, false, d)?];
    match &iras.spouse {
        IraSpouse::Joint { facts } => {
            people.push(ira_contributor_item(Owner::Spouse, facts, false, d)?);
        }
        // The spouse's coverage on a separate return folds into the
        // taxpayer's own row: this page has no spouse row to file it under.
        IraSpouse::SeparateTogether { covered_at_work } => {
            people[0] = ira_contributor_item(Owner::Taxpayer, &iras.taxpayer, *covered_at_work, d)?;
        }
        IraSpouse::NotApplicable => {}
    }
    Some(people)
}
// The owner's Form 8606 year-end traditional IRA value (IraBasis.year_end),
// when the Retirement page holds that owner's Form 8606.
pub(crate) fn form_8606_year_end(d: &FederalDraft, owner: Owner) -> Option<i64> {
    d.adjustments.as_ref()?.ira_basis.iter().find(|b| b.owner == owner).map(|b| b.year_end)
}
// Form 5329 line 17's traditional IRA value from the owner's Form 8606: the
// December 31, 2026 value (Form 8606 line 6) plus the 2026 contributions made
// in 2027 (i5329 line 17 includes them; line 6 does not), T2-cy.
fn form_5329_traditional_value(
    d: &FederalDraft,
    owner: Owner,
) -> Option<crate::kernel::ratio::exact::Exact> {
    d.adjustments
        .as_ref()?
        .ira_basis
        .iter()
        .find(|b| b.owner == owner)
        .map(crate::IraBasis::form_5329_value_exact)
}
// Keeps a stored IRA excess record's traditional value equal to the
// owner's Form 8606 year-end value plus 2026 contributions made in 2027
// whenever the return changes: the facts have their home on the Form 8606
// and the IRA contributions page (C18). The Form 8606's paid_next_year is
// derived from that page's 2027 deposits, so it follows them first.
fn follow_ira_year_end(d: &mut FederalDraft) {
    if let Some(adjustments) = d.adjustments.as_mut() {
        let deposits = [Owner::Taxpayer, Owner::Spouse]
            .map(|owner| ira_next_year_deposit(Some(&*adjustments), owner));
        for basis in &mut adjustments.ira_basis {
            basis.paid_next_year = deposits[usize::from(basis.owner == Owner::Spouse)];
        }
    }
    let values =
        [Owner::Taxpayer, Owner::Spouse].map(|owner| form_5329_traditional_value(d, owner));
    let Some(iras) = d.adjustments.as_mut().map(|a| &mut a.iras) else {
        return;
    };
    let spouse = match &mut iras.spouse {
        IraSpouse::Joint { facts } => Some(facts),
        _ => None,
    };
    for (facts, value) in [Some(&mut iras.taxpayer), spouse].into_iter().zip(values) {
        if let (Some(facts), Some(value)) = (facts, value)
            && let Some(excess) = facts.excess.as_mut()
        {
            excess.traditional_value = crate::kernel::ratio::exact::rounded(&value);
        }
    }
}
fn ira_contributor_item(
    owner: Owner,
    facts: &FederalIraContribution,
    spouse_covered_if_separate: bool,
    d: &FederalDraft,
) -> Option<IraContributor> {
    let form_8606_value = form_8606_year_end(d, owner);
    let excess = match &facts.excess {
        Some(record) => Some(crate::IraExcessEntry::from_record(record, form_8606_value)?),
        None => None,
    };
    let more = IraMore {
        nondeductible: facts.nondeductible_election,
        paid_next_year: facts.next_year_deposits.clone(),
        spouse_covered_if_separate,
        excess,
        returned_in_following_year: facts.returned_next_year.clone(),
        qtp_roth_prior: facts.qtp_roth_lifetime_prior,
    };
    Some(IraContributor {
        owner,
        traditional: facts.traditional,
        roth: facts.roth,
        covered: ira_covered(d, owner),
        form_8606_value,
        more,
    })
}
// A contributor row onto its record; absent (no row submitted) is a
// complete zero contribution with the owner's derived coverage.
fn ira_contribution_record(
    d: &FederalDraft,
    row: Option<&IraContributor>,
    owner: Owner,
) -> FederalIraContribution {
    let none = IraMore::default();
    let (traditional, roth, more) = match row {
        Some(p) => (p.traditional, p.roth, &p.more),
        None => (0, 0, &none),
    };
    let nondeductible_election = more.nondeductible;
    let next_year_deposits = more.paid_next_year.clone();
    // The save checked the traditional value's one home first.
    let excess = more.excess.as_ref().and_then(|e| e.record(form_5329_traditional_value(d, owner)));
    FederalIraContribution {
        traditional,
        roth,
        nondeductible_election,
        covered_at_work: ira_covered(d, owner),
        next_year_deposits,
        qtp_roth_lifetime_prior: more.qtp_roth_prior,
        returned_next_year: more.returned_in_following_year.clone(),
        excess,
    }
}
fn distribution_treatment(
    code: &DistributionCode,
    gross: i64,
    taxable: i64,
    more: &RMore,
    box7: u32,
) -> RetirementTreatment {
    match code {
        // A code G box 2a above zero is the taxable part of a rollover to a Roth IRA or an
        // in-plan Roth rollover, which the person chooses as the Roth target (taxed in the Roth
        // rollover treatment). Box 2a with another target (box 2a left blank on a plan
        // rollover) is taxed as printed, with no rollover.
        DistributionCode::DirectRollover { to } if taxable > 0 && *to != RolloverTarget::Roth => {
            RetirementTreatment::Ordinary
        }
        DistributionCode::NormalLumpSum {
            tax: crate::LumpSumTax::WithOtherIncome { what_happened },
        } => disposition_treatment(what_happened, false),
        DistributionCode::NormalLumpSum { tax } => crate::Form4972Election::from_own(tax, more)
            .map_or(RetirementTreatment::Unsupported, |data| RetirementTreatment::LumpSum { data }),
        DistributionCode::DeathLumpSum {
            died,
            tax: crate::InheritedLumpSumTax::WithOtherIncome,
        } => RetirementTreatment::Exception {
            distributed: 20261231,
            facts: crate::RetirementException::Death { died: *died },
            second: None,
            early_simple: false,
        },
        DistributionCode::DeathLumpSum { died, tax } => {
            crate::Form4972Election::from_decedent(*died, tax, more)
                .map_or(RetirementTreatment::Unsupported, |data| RetirementTreatment::LumpSum {
                    data,
                })
        }
        DistributionCode::Normal { what_happened } => disposition_treatment(what_happened, false),
        DistributionCode::Early {
            what_happened: Disposition::Kept,
            exception: EarlyException::Applies { distributed, facts, second, .. },
        }
        | DistributionCode::ProhibitedTransaction {
            exception: EarlyException::Applies { distributed, facts, second, .. },
        } => RetirementTreatment::Exception {
            distributed: *distributed,
            facts: facts.clone(),
            second: second.clone(),
            early_simple: false,
        },
        // The whole IRA is treated as paid out on January 1, 2026: an early distribution
        // unless the owner was 59½ that day or an exception applies (retirement::early_tax).
        DistributionCode::ProhibitedTransaction { .. } => RetirementTreatment::Early,
        DistributionCode::Early { what_happened: Disposition::Kept, .. } => {
            RetirementTreatment::Early
        }
        DistributionCode::Early { what_happened, .. } => disposition_treatment(what_happened, true),
        DistributionCode::Disability { began, .. } => RetirementTreatment::Exception {
            distributed: 20261231,
            facts: crate::RetirementException::Disability { began: *began },
            second: None,
            early_simple: false,
        },
        DistributionCode::Death { died } => RetirementTreatment::Exception {
            distributed: 20261231,
            facts: crate::RetirementException::Death { died: *died },
            second: None,
            early_simple: false,
        },
        DistributionCode::DirectRollover { to } => RetirementTreatment::Rollover {
            destination: match to {
                RolloverTarget::Ira => crate::RolloverDestination::Ira,
                RolloverTarget::EmployerPlan => crate::RolloverDestination::EmployerPlan,
                RolloverTarget::Roth => crate::RolloverDestination::Roth,
            },
            amount: gross,
            early: false,
        },
        DistributionCode::EarlySimple { what_happened } => what_happened.treatment(),
        DistributionCode::EmployerRothContribution => RetirementTreatment::EmployerRothContribution,
        DistributionCode::Nonqualified
        | DistributionCode::Exchange
        | DistributionCode::NotIncome
        | DistributionCode::Inherited { .. } => RetirementTreatment::Ordinary,
        // A charitable gift annuity's box 3 capital gain (28% and section 1250 characters the
        // payer reports separately) is not calculated; every other payment is taxed as printed.
        DistributionCode::NoAdditionalTax
            if box7 & DistributionCodes::CODE_F.0 != 0 && more.box_3 > 0 =>
        {
            RetirementTreatment::Unsupported
        }
        DistributionCode::NoAdditionalTax => RetirementTreatment::Ordinary,
        DistributionCode::Corrective { excess_deferral } => {
            RetirementTreatment::Corrective { excess_deferral: *excess_deferral }
        }
        DistributionCode::QualifiedCareCharge => {
            RetirementTreatment::QualifiedCareCharge { investment_reduction: more.box_8a }
        }
        DistributionCode::Other => RetirementTreatment::Unsupported,
        // document_income stores a Roth IRA code as the Roth income kind and a
        // Trump account code as its own income kind.
        DistributionCode::RothIra { .. }
        | DistributionCode::TrumpDeath { .. }
        | DistributionCode::TrumpToAble { .. } => {
            unreachable!("this 1099-R is not a FederalRetirement record")
        }
    }
}
fn disposition_treatment(what_happened: &Disposition, early: bool) -> RetirementTreatment {
    match what_happened {
        Disposition::Kept => RetirementTreatment::Ordinary,
        Disposition::RolledOver { amount, into } => {
            RetirementTreatment::Rollover { destination: *into, amount: *amount, early }
        }
        Disposition::Converted { amount } => {
            RetirementTreatment::Conversion { amount: *amount, early }
        }
        Disposition::SoldAndRolledOver { amount, into, .. } => {
            RetirementTreatment::Rollover { destination: *into, amount: *amount, early }
        }
    }
}
// FederalRetirement field for field; the IRA basis worksheet override (an
// IRA document whose owner has a Form 8606 on this page) is applied by the
// caller, once every document of the topic is known.
fn retirement_record(v: &R1099) -> FederalRetirement {
    // The kind comes from the printed box 7a and box 7b, not from the branch:
    // code D printed with 1, 2, 3, 4 or 7 is a nonqualified annuity too.
    // Code F, a charitable gift annuity, is a nonqualified annuity too, and a
    // recharacterization (code N) moves an IRA contribution: box 7b is unchecked for both.
    // Code J, an early distribution from a Roth IRA, is an IRA amount even when the payer
    // leaves box 7b unchecked (a Roth IRA payer's usual print): Form 1040 lines 4a/4b.
    let kind = if v.box7
        & (DistributionCodes::CODE_D.0 | DistributionCodes::CODE_F.0 | DistributionCodes::CODE_W.0)
        != 0
    {
        RetirementKind::Nonqualified
    } else if v.ira && matches!(v.code, DistributionCode::Inherited { .. }) {
        RetirementKind::Inherited
    } else if v.ira || v.box7 & (DistributionCodes::CODE_N.0 | DistributionCodes::CODE_J.0) != 0 {
        RetirementKind::Ira
    } else {
        RetirementKind::Pension
    };
    let (method, disability) = (v.more.taxable_method.clone(), v.more.disability.clone());
    let sold =
        crate::retirement::disposition_of(&v.code).and_then(crate::Disposition::property).cloned();
    use crate::RetirementTaxable as T;
    use TaxableMethod as M;
    let taxable = match (&v.code, method) {
        (DistributionCode::Inherited { account }, _) => {
            T::Inherited { account: *account, payer: v.taxable }
        }
        // An empty cost takes box 9b (rule R_COST_NEEDS_BOX_9B); the stored worksheet always
        // holds the resolved cost.
        (_, M::Simplified { mut data }) => {
            data.cost = data.cost.or(v.more.box_9b);
            T::Simplified { data }
        }
        (_, M::GeneralRule { data }) => T::GeneralAnnuity { data },
        (_, M::VariablePayments { data }) => T::VariableAnnuity { data },
        (_, M::WholeContract { data }) => T::FullDischarge { data },
        (_, M::PlanWithdrawal { data }) => T::QualifiedWithdrawal { data },
        (_, M::AnnuityWithdrawal { data }) => T::DeferredWithdrawal { data },
        (_, M::Pre1982Withdrawal { data }) => T::LegacyAnnuity { data },
        (_, M::CivilServiceLumpSum { data }) => T::CivilServiceDeath { data },
        (_, M::ChildAnnuity { data }) => T::ChildAnnuity { data },
        (_, M::BoxTwoA) => match sold {
            Some(data) => T::PropertyProceeds { data },
            None => T::Payer { amount: v.taxable },
        },
    };
    FederalRetirement {
        disability,
        kind,
        // Only a code 3 pension carries the minimum-retirement-age answer.
        disability_wages: match &v.code {
            DistributionCode::Disability { wages, .. } if kind == RetirementKind::Pension => *wages,
            _ => crate::DisabilityWages::None,
        },
        gross: v.gross,
        taxable,
        withholding: v.withholding,
        box7: v.box7,
        ordinary_distribution: distribution_treatment(&v.code, v.gross, v.taxable, &v.more, v.box7),
        disaster: v.disaster.clone(),
        after_death: v.after_death.clone(),
        box_10: if v.box7 & DistributionCodes::CODE_B.0 != 0 { v.more.box_10 } else { 0 },
        box_9b: v.more.box_9b,
    }
}
// A Trump account distribution (Form 1099-R box 7c) is its own income kind:
// code 4 the acquirer's income at the child's death (section 530A(d)(6)), box 1
// the value and box 2a its excess over the basis; code G the whole account
// moved to the child's ABLE account (section 530A(d)(4)).
fn trump_record(v: &R1099) -> Option<FederalIncome> {
    Some(match v.code {
        DistributionCode::TrumpDeath { estate } => FederalIncome::TrumpDeath {
            data: crate::TrumpDeathAcquisition {
                beneficiary_estate: estate,
                value: v.gross,
                basis: v.gross - v.taxable,
                withholding: v.withholding,
            },
        },
        DistributionCode::TrumpToAble { transferred } => FederalIncome::TrumpAbleRollover {
            data: crate::TrumpAbleRollover { amount: v.gross, transferred },
        },
        _ => return None,
    })
}
fn trump_item(income: &FederalIncome) -> Option<R1099> {
    let (gross, taxable, withholding, box7, code) = match income {
        FederalIncome::TrumpDeath { data } => (
            data.value,
            data.taxable(),
            data.withholding,
            DistributionCodes::CODE_4.0,
            DistributionCode::TrumpDeath { estate: data.beneficiary_estate },
        ),
        FederalIncome::TrumpAbleRollover { data } => (
            data.amount,
            0,
            0,
            DistributionCodes::CODE_G.0,
            DistributionCode::TrumpToAble { transferred: data.transferred },
        ),
        _ => return None,
    };
    Some(R1099 {
        state_details: Default::default(),
        gross,
        taxable,
        withholding,
        box7,
        allowed_treatments: DistributionCodes::treatments(box7, false, true),
        allowed_methods: DistributionCodes::methods(box7, false, true),
        code,
        ira: false,
        trump: true,
        more: RMore::default(),
        disaster: crate::DisasterDistribution::No,
        public_safety: Vec::new(),
        after_death: None,
    })
}
// The RRB-1099-R onto the pension record of the Railroad kind: box 7 is the
// gross (code 7 is "the distribution code if you are asked for one"), box 4
// the part box 3 can be recovered from, boxes 5 and 6 fully taxable. An
// employee or spouse annuity is ordinary, a survivor annuity the death
// exception (what the code 4 branch stores).
fn rrb_record(v: &crate::Rrb1099R) -> FederalRetirement {
    use crate::{RailroadRecipient as W, RailroadRecovery as R};
    let basis = |recovery: &R| match recovery {
        R::None => None,
        R::SimplifiedMethod { data } => Some(data.clone()),
    };
    let (holder, basis, ordinary_distribution) = match &v.recipient {
        W::Employee { recovery } => {
            (crate::RailroadHolder::Employee, basis(recovery), RetirementTreatment::Ordinary)
        }
        W::Spouse => (crate::RailroadHolder::Spouse, None, RetirementTreatment::Ordinary),
        W::Survivor { died, recovery } => (
            crate::RailroadHolder::Survivor { died: *died },
            basis(recovery),
            RetirementTreatment::Exception {
                distributed: 20261231,
                facts: crate::RetirementException::Death { died: *died },
                second: None,
                early_simple: false,
            },
        ),
    };
    FederalRetirement {
        disability: crate::DisabilityIncome::None,
        kind: RetirementKind::Pension,
        disability_wages: crate::DisabilityWages::None,
        gross: v.gross,
        taxable: crate::RetirementTaxable::Railroad {
            repayments: v.repayments.clone(),
            contributory: v.box_4,
            box_5: v.box_5,
            box_6: v.box_6,
            holder,
            basis,
        },
        withholding: v.withholding,
        box7: DistributionCodes::CODE_7.0,
        ordinary_distribution,
        disaster: crate::DisasterDistribution::No,
        after_death: None,
        box_10: 0,
        box_9b: None,
    }
}
// The reverse: the record keeps the whole page (the answer about whose
// annuity it is, boxes 5 and 6 apart), so it reopens as entered; box 8 is the
// total of the repayment rows.
fn rrb_item(data: &FederalRetirement) -> Option<crate::Rrb1099R> {
    use crate::{RailroadHolder as H, RailroadRecipient as W, RailroadRecovery as R};
    let crate::RetirementTaxable::Railroad {
        repayments,
        contributory,
        box_5,
        box_6,
        holder,
        basis,
    } = &data.taxable
    else {
        return None;
    };
    let recovery = || match basis {
        Some(data) => R::SimplifiedMethod { data: data.clone() },
        None => R::None,
    };
    let recipient = match holder {
        H::Employee => W::Employee { recovery: recovery() },
        H::Spouse => W::Spouse,
        H::Survivor { died } => W::Survivor { died: *died, recovery: recovery() },
    };
    Some(crate::Rrb1099R {
        box_4: *contributory,
        box_5: *box_5,
        box_6: *box_6,
        gross: data.gross,
        box_8: repayments.iter().map(|p| p.amount).sum(),
        withholding: data.withholding,
        recipient,
        repayments: repayments.clone(),
    })
}
// The existing RRB-1099-R source checks, including box 8's actual row total.
fn rrb_issue(v: &crate::Rrb1099R) -> Option<ValidationIssue> {
    let rows: i128 = v.repayments.iter().map(|p| i128::from(p.amount)).sum();
    if v.box_4 + v.box_5 + v.box_6 != v.gross {
        Some(ValidationIssue::new("RRB_BOX7_NOT_SUM").at_field("gross"))
    } else if v.withholding > v.gross {
        Some(ValidationIssue::new("R_WITHHOLDING_ABOVE_GROSS").at_field("withholding"))
    } else if v.box_8 == 0 && !v.repayments.is_empty() {
        Some(ValidationIssue::new("RRB_REPAYMENTS_WITHOUT_BOX_8").at_field("repayments"))
    } else if v.box_8 > 0 && v.repayments.is_empty() {
        Some(ValidationIssue::new("RRB_BOX_8_NOT_SPLIT").at_field("repayments"))
    } else if rows != i128::from(v.box_8) {
        Some(ValidationIssue::new("RRB_REPAYMENTS_NOT_BOX_8").at_field("repayments"))
    } else {
        None
    }
}
// SSA-1099 field for field; special_treatment is never asked on this page.
fn ssa_record(v: &Ssa1099) -> FederalSocial {
    FederalSocial { benefits: v.benefits, withholding: v.withholding, special_treatment: false }
}
fn ssa_item(data: &FederalSocial) -> Ssa1099 {
    Ssa1099 {
        statement: Default::default(),
        benefits: data.benefits,
        withholding: data.withholding,
    }
}
// The reverse of distribution_treatment. The stored box 7a codes choose the
// branch (the save held them to R_BOX7_TREATMENT), and the treatment fills
// its answers: a code 1 or 2 exception and a code 3 or 4 date keep their
// own branch, and a rollover or conversion is what happened to a 7, 1, 2 or
// S distribution.
fn distribution_code(v: &FederalRetirement) -> DistributionCode {
    let ira = page_ira(v);
    let what_happened = || match &v.ordinary_distribution {
        RetirementTreatment::Rollover { destination, amount, .. } => match &v.taxable {
            crate::RetirementTaxable::PropertyProceeds { data } => Disposition::SoldAndRolledOver {
                data: data.clone(),
                amount: *amount,
                into: *destination,
            },
            _ => Disposition::RolledOver { amount: *amount, into: *destination },
        },
        RetirementTreatment::Conversion { amount, .. } => {
            Disposition::Converted { amount: *amount }
        }
        _ => Disposition::Kept,
    };
    let date = |pick: fn(&crate::RetirementException) -> Option<u32>| match &v.ordinary_distribution
    {
        RetirementTreatment::Exception { facts, .. } => pick(facts).unwrap_or(0),
        _ => 0,
    };
    let branches = [
        DistributionCode::Normal { what_happened: what_happened() },
        DistributionCode::Early {
            what_happened: what_happened(),
            exception: match &v.ordinary_distribution {
                RetirementTreatment::Exception { distributed, facts, second, .. } => {
                    EarlyException::Applies {
                        distributed: *distributed,
                        facts: facts.clone(),
                        second: second.clone(),
                        repaid: None,
                    }
                }
                _ => EarlyException::None,
            },
        },
        DistributionCode::Disability {
            began: date(|f| match f {
                crate::RetirementException::Disability { began, .. } => Some(*began),
                _ => None,
            }),
            wages: v.disability_wages,
        },
        DistributionCode::Death {
            died: date(|f| match f {
                crate::RetirementException::Death { died } => Some(*died),
                _ => None,
            }),
        },
        DistributionCode::DirectRollover {
            to: match &v.ordinary_distribution {
                RetirementTreatment::Rollover {
                    destination: crate::RolloverDestination::EmployerPlan,
                    ..
                } => RolloverTarget::EmployerPlan,
                RetirementTreatment::Rollover {
                    destination: crate::RolloverDestination::Roth,
                    ..
                } => RolloverTarget::Roth,
                _ => RolloverTarget::Ira,
            },
        },
        DistributionCode::EarlySimple {
            what_happened: match &v.ordinary_distribution {
                RetirementTreatment::Rollover {
                    destination: crate::RolloverDestination::SimpleIra,
                    amount,
                    ..
                } => crate::SimpleDisposition::RolledOver { amount: *amount },
                _ => crate::SimpleDisposition::Kept,
            },
        },
        DistributionCode::Nonqualified,
        DistributionCode::NormalLumpSum {
            tax: match &v.ordinary_distribution {
                RetirementTreatment::LumpSum { data } => data.own_page(),
                _ => None,
            }
            .unwrap_or(crate::LumpSumTax::WithOtherIncome { what_happened: what_happened() }),
        },
        DistributionCode::DeathLumpSum {
            died: match &v.ordinary_distribution {
                RetirementTreatment::LumpSum { data } => data.decedent_page().map(|(died, _)| died),
                _ => None,
            }
            .unwrap_or_else(|| {
                date(|f| match f {
                    crate::RetirementException::Death { died } => Some(*died),
                    _ => None,
                })
            }),
            tax: match &v.ordinary_distribution {
                RetirementTreatment::LumpSum { data } => data.decedent_page().map(|(_, tax)| tax),
                _ => None,
            }
            .unwrap_or(crate::InheritedLumpSumTax::WithOtherIncome),
        },
        DistributionCode::QualifiedCareCharge,
        DistributionCode::Exchange,
        DistributionCode::Inherited {
            account: match v.taxable {
                crate::RetirementTaxable::Inherited { account, .. } => account,
                _ => None,
            },
        },
        DistributionCode::Corrective {
            excess_deferral: match v.ordinary_distribution {
                RetirementTreatment::Corrective { excess_deferral } => excess_deferral,
                _ => 0,
            },
        },
        DistributionCode::NotIncome,
        DistributionCode::NoAdditionalTax,
        DistributionCode::ProhibitedTransaction {
            exception: match &v.ordinary_distribution {
                RetirementTreatment::Exception { distributed, facts, second, .. } => {
                    EarlyException::Applies {
                        distributed: *distributed,
                        facts: facts.clone(),
                        second: second.clone(),
                        repaid: None,
                    }
                }
                _ => EarlyException::None,
            },
        },
    ];
    // Code A alone leads to two branches: a decedent's plan (or inherited IRA) when the record
    // is one, the participant's own otherwise.
    let decedent = match &v.ordinary_distribution {
        RetirementTreatment::LumpSum { data } => data.decedent_page().is_some(),
        RetirementTreatment::Exception {
            facts: crate::RetirementException::Death { .. }, ..
        } => true,
        _ => false,
    };
    let inherited = v.kind == RetirementKind::Inherited;
    // An employer's Roth SEP or Roth SIMPLE contribution shares box 7a with an ordinary
    // distribution; the stored treatment tells them apart.
    if v.ordinary_distribution == RetirementTreatment::EmployerRothContribution {
        return DistributionCode::EmployerRothContribution;
    }
    branches
        .into_iter()
        .filter(|code| {
            !(decedent && matches!(code, DistributionCode::NormalLumpSum { .. })
                || inherited && matches!(code, DistributionCode::Normal { .. }))
        })
        .find(|code| DistributionCodes::leads_to(v.box7, ira, false, code))
        .unwrap_or(DistributionCode::Other)
}
// Box 7b as the page showed it: the record's kind, except that a recharacterization (code N)
// is an IRA record whose box 7b is unchecked.
fn page_ira(v: &FederalRetirement) -> bool {
    v.kind.ira() && v.box7 & DistributionCodes::CODE_N.0 == 0
}
// The reverse of retirement_record. Box 2a is not retained once the IRA
// basis worksheet or the Simplified Method applies (never asked per
// document); it reopens at the gross distribution, a benign placeholder.
fn retirement_item(data: &FederalRetirement) -> R1099 {
    use crate::RetirementTaxable as T;
    use TaxableMethod as M;
    let code = distribution_code(data);
    let method = match &data.taxable {
        T::Simplified { data } => M::Simplified { data: data.clone() },
        T::GeneralAnnuity { data } => M::GeneralRule { data: *data },
        T::VariableAnnuity { data } => M::VariablePayments { data: *data },
        T::FullDischarge { data } => M::WholeContract { data: data.clone() },
        T::QualifiedWithdrawal { data } => M::PlanWithdrawal { data: data.clone() },
        T::DeferredWithdrawal { data } => M::AnnuityWithdrawal { data: data.clone() },
        T::LegacyAnnuity { data } => M::Pre1982Withdrawal { data: data.clone() },
        T::CivilServiceDeath { data } => M::CivilServiceLumpSum { data: data.clone() },
        T::ChildAnnuity { data } => M::ChildAnnuity { data: data.clone() },
        _ => M::BoxTwoA,
    };
    let taxable = match &data.taxable {
        T::Payer { amount } => *amount,
        T::Inherited { payer, .. } => *payer,
        _ => data.gross,
    };
    let ira = page_ira(data);
    R1099 {
        state_details: Default::default(),
        gross: data.gross,
        taxable,
        withholding: data.withholding,
        box7: data.box7,
        allowed_treatments: DistributionCodes::treatments(data.box7, ira, false),
        allowed_methods: DistributionCodes::methods(data.box7, ira, false),
        code,
        ira,
        trump: false,
        more: {
            let mut more = RMore {
                taxable_method: method,
                disability: data.disability.clone(),
                box_10: data.box_10,
                // A refused charitable gift annuity gain is not kept; the row reopens with a
                // gain no larger than its taxable amount, which stays refused.
                box_3: if data.ordinary_distribution == RetirementTreatment::Unsupported
                    && data.box7 & DistributionCodes::CODE_F.0 != 0
                {
                    taxable
                } else {
                    0
                },
                ..RMore::default()
            };
            if let RetirementTreatment::LumpSum { data } = &data.ordinary_distribution {
                data.boxes(&mut more);
            }
            if let RetirementTreatment::QualifiedCareCharge { investment_reduction } =
                data.ordinary_distribution
            {
                more.box_8a = investment_reduction;
            }
            more
        },
        disaster: data.disaster.clone(),
        public_safety: Vec::new(),
        after_death: data.after_death.clone(),
    }
}

pub(crate) fn document_income(document: &IncomeDocument) -> FederalIncome {
    match document {
        IncomeDocument::W2(w) => FederalIncome::Wage { data: wage_record(w) },
        IncomeDocument::Int1099(v) => FederalIncome::Interest { data: interest_record(v) },
        IncomeDocument::SellerMortgageInterest(v) => {
            FederalIncome::Interest { data: seller_interest_record(v) }
        }
        IncomeDocument::Div1099(v) => FederalIncome::Dividend { data: dividend_record(v) },
        IncomeDocument::Oid1099(v) => FederalIncome::Oid { data: oid_record(v) },
        IncomeDocument::Form8814(v) => FederalIncome::ChildElection { data: v.record() },
        IncomeDocument::Sale1099B(v) => FederalIncome::Sale { data: sale_record(v) },
        IncomeDocument::OpportunityFund(v) => FederalIncome::OpportunityFund { data: v.clone() },
        IncomeDocument::OpportunityFundDeferral(v) => {
            FederalIncome::OpportunityFundDeferral { data: v.clone() }
        }
        IncomeDocument::Contracts1099B(v) => {
            FederalIncome::Section1256 { data: contracts_record(v) }
        }
        IncomeDocument::IsoShareSale(v) => FederalIncome::IsoSale { data: v.record() },
        IncomeDocument::EmployeeShareSale(v) => {
            FederalIncome::EmployeeStockSale { data: v.record() }
        }
        IncomeDocument::EsppShareSale(v) => FederalIncome::EsppSale { data: v.record() },
        IncomeDocument::NuaShareSale(v) => FederalIncome::NuaSale { data: v.record() },
        IncomeDocument::QsbsSale(v) => {
            FederalIncome::QualifiedSmallBusinessSale { data: v.record() }
        }
        IncomeDocument::SmallBusinessStockLoss(v) => {
            FederalIncome::SmallBusinessStock { data: v.clone() }
        }
        IncomeDocument::WorthlessSecurity(v) => {
            FederalIncome::WorthlessSecurity { data: v.clone() }
        }
        IncomeDocument::BadDebt(v) => FederalIncome::NonbusinessBadDebt { data: v.clone() },
        IncomeDocument::CapitalReturn1099Div(v) => v.record(),
        IncomeDocument::Form2439(v) => FederalIncome::UndistributedGain { data: v.record() },
        // A Roth IRA code is the Roth income kind (Form 8606 Part III).
        IncomeDocument::R1099(
            v @ R1099 { code: DistributionCode::RothIra { roth, rolled_over, sequence }, .. },
        ) => FederalIncome::Roth { data: roth.record(v, *rolled_over, *sequence) },
        IncomeDocument::MainHomeSale(v) => FederalIncome::HomeSale { data: v.record() },
        IncomeDocument::SavingsBonds(v) => {
            FederalIncome::SavingsBonds { data: savings_bonds_record(v) }
        }
        IncomeDocument::Q1099(v) => FederalIncome::EducationDistribution { data: q1099_record(v) },
        IncomeDocument::EducationAccountExpenses(v) => {
            FederalIncome::EducationAccountExpenses { data: education_expenses_record(v) }
        }
        // A Trump account code (box 7c) is its own income kind.
        IncomeDocument::R1099(v) if trump_record(v).is_some() => {
            trump_record(v).expect("a Trump account branch")
        }
        IncomeDocument::R1099(v) => FederalIncome::Retirement { data: retirement_record(v) },
        IncomeDocument::Rrb1099R(v) => FederalIncome::Retirement { data: rrb_record(v) },
        IncomeDocument::InheritedIra(v) => FederalIncome::InheritedIra { data: v.record() },
        IncomeDocument::Sa1099(v) => FederalIncome::MedicalDistribution { data: v.record() },
        IncomeDocument::Ltc1099(v) => FederalIncome::LtcBenefits { data: v.record() },
        IncomeDocument::LtcInsured(v) => FederalIncome::LtcInsured { data: v.record() },
        IncomeDocument::Qa1099(v) => FederalIncome::Able { data: v.record() },
        IncomeDocument::Ssa1099(v) => FederalIncome::SocialSecurity { data: ssa_record(v) },
        // Form 8606 and QCD gifts affect Adjustments, not an income entry;
        // documents_candidate and PreviewDocument split them out before
        // calling document_income.
        adjustment_kinds!() => {
            unreachable!(
                "Form 8606, QCD gifts and the retirement adjustments are not income entries"
            )
        }
        // The data answers are FederalScreening facts, split out the same way.
        data_answer_kinds!() => {
            unreachable!("the data answers are not income entries")
        }
        IncomeDocument::Farm(f) => {
            FederalIncome::Business { data: crate::farm_page::farm_record(f, None) }
        }
        IncomeDocument::FarmRental(f) => {
            FederalIncome::FarmRental { data: crate::farm_page::farm_rental_record(f) }
        }
        IncomeDocument::Business(b) => FederalIncome::Business { data: business_record(b, None) },
        IncomeDocument::Rental(r) => FederalIncome::Rental { data: rental_record(r) },
        IncomeDocument::Form1099G(v) => {
            FederalIncome::Unemployment { data: unemployment_record(v) }
        }
        IncomeDocument::Patr1099(v) => FederalIncome::Cooperative { data: cooperative_record(v) },
        IncomeDocument::K1EstateTrust(v) => {
            FederalIncome::EstateTrustPortfolio { data: v.record() }
        }
        IncomeDocument::K1PartnershipActivities(v) => {
            FederalIncome::PartnershipActivities { data: alloc::boxed::Box::new(v.record()) }
        }
        IncomeDocument::K1ScorpActivities(v) => FederalIncome::ScorpActivities { data: v.record() },
        IncomeDocument::K1Scorp(v) => FederalIncome::Scorp { data: v.record() },
        IncomeDocument::K1Partnership(v) => FederalIncome::Partnership { data: v.record() },
        IncomeDocument::Cancel1099C(v) => FederalIncome::PersonalDebt { data: v.record() },
        IncomeDocument::Acquisition1099A(v) => {
            FederalIncome::PropertyAcquisition { data: v.record() }
        }
        IncomeDocument::AlimonyReceived(v) => FederalIncome::Alimony { data: v.clone() },
        IncomeDocument::ForeignPay(v) => {
            FederalIncome::ForeignEmployment { data: crate::ForeignWages { wages: v.wages } }
        }
        IncomeDocument::Form8919(v) => FederalIncome::EmployeeWages { data: v.clone() },
        IncomeDocument::HealthLoanRepayment(v) => {
            FederalIncome::HealthLoanAssistance { data: v.clone() }
        }
        IncomeDocument::Scholarship(v) => FederalIncome::Scholarship { data: v.clone() },
        IncomeDocument::JuryPay(v) => FederalIncome::JuryDuty { data: v.clone() },
        IncomeDocument::HobbySales(v) => FederalIncome::HobbySales { data: v.clone() },
        IncomeDocument::WildfireRelief(v) => FederalIncome::WildfireRelief { data: v.clone() },
        IncomeDocument::DisasterRelief(v) => FederalIncome::DisasterRelief { data: v.clone() },
        IncomeDocument::CasualtyLivingInsurance(v) => {
            FederalIncome::CasualtyLivingInsurance { data: v.clone() }
        }
        IncomeDocument::DisasterMitigation(v) => {
            FederalIncome::DisasterMitigation { data: v.clone() }
        }
        IncomeDocument::Refund1099G(v) => FederalIncome::TaxRefund {
            amount: v.amount,
            history: refund_history(v),
            withholding: v.withholding,
        },
        IncomeDocument::OtherIncome(v) => FederalIncome::OtherIncome { data: v.clone() },
        IncomeDocument::Form1099Nec(v) => FederalIncome::Nec1099 { data: v.record() },
        IncomeDocument::Form1099Misc(v) => FederalIncome::Misc1099 { data: v.record() },
        IncomeDocument::Form1099K(v) => FederalIncome::K1099 { data: v.record() },
        IncomeDocument::W2g(v) => FederalIncome::Gambling {
            data: FederalGambling {
                winnings: v.winnings,
                losses: 0,
                withholding: v.withholding,
                own_records: false,
                ordinary: !v.special,
            },
        },
        IncomeDocument::GamblingLosses(v) => FederalIncome::Gambling {
            data: FederalGambling {
                winnings: v.other_winnings,
                losses: v.losses,
                withholding: 0,
                own_records: true,
                ordinary: !v.special,
            },
        },
        IncomeDocument::Royalties(v) => FederalIncome::Royalty {
            data: crate::FederalRoyalty {
                kind: v.kind.clone(),
                receipts: v.receipts,
                advance: v.advance,
                expenses: rental_expense_records(&v.expenses),
                depletion: v.depletion.clone(),
                ordinary: !v.special,
            },
        },
        IncomeDocument::EquipmentRental(v) => FederalIncome::NonbusinessProperty {
            kind: NonbusinessPropertyKind::PersonalRental {
                basis: v.basis,
                depreciable_basis: v.depreciable_basis,
                assets: v.assets.iter().map(|asset| asset_record(asset, false)).collect(),
                history: v.history,
            },
            receipts: v.receipts,
            expenses: v.expenses,
            ordinary: true,
        },
    }
}

// Form 8606 items (already known to be at most one per owner) onto the
// stored IRA basis worksheet. `paid_next_year` is derived from the IRA
// contributions page's 2027 deposits (Adjustments), never asked here.
fn ira_basis_records(
    items: &[IncomeDocumentItem],
    adjustments: Option<&FederalAdjustments>,
    repayments: Vec<(Owner, crate::IraRepayment)>,
) -> Vec<crate::IraBasis> {
    items
        .iter()
        .filter_map(|item| match &item.document {
            IncomeDocument::Form8606(f) => Some(crate::IraBasis {
                owner: item.owner,
                prior: f.basis,
                adjustment: f.adjustment,
                year_end: f.year_end,
                paid_next_year: ira_next_year_deposit(adjustments, item.owner),
                reservist_repayments: f.reservist_repayments.clone(),
                // The 1099-R rows' repayments of their special distributions.
                special_repayments: repayments
                    .iter()
                    .filter(|(owner, _)| *owner == item.owner)
                    .map(|(_, repayment)| repayment.clone())
                    .collect(),
            }),
            _ => None,
        })
        .collect()
}
fn ira_next_year_deposit(adjustments: Option<&FederalAdjustments>, owner: Owner) -> i64 {
    let Some(iras) = adjustments.and_then(|a| a.entered_iras()) else {
        return 0;
    };
    let contribution = match owner {
        Owner::Taxpayer => Some(&iras.taxpayer),
        Owner::Spouse => iras.spouse.as_ref(),
    };
    contribution.and_then(|c| c.next_year_deposits.as_ref()).map_or(0, |n| n.traditional)
}
// The save rules that read more than one document of the Retirement page (server only: a
// client rule sees one row at a time), in the order they are reported:
// - IRA_ROLLOVER_ONCE_A_YEAR: a person's 60-day rollovers from IRAs to IRAs are tax-free once in
//   any 1-year period across all of their IRAs (section 408(d)(3)(B)); trustee-to-trustee
//   transfers and plan rollovers are not counted.
// - R_EXCESS_DEFERRAL_ABOVE_W2_EXCESS: the excess deferrals the 1099-R rows say they returned
//   are no more than the excess the App counted from the person's W-2s (Form 1040 line 1h).
// - QCD_SPLIT_INTEREST_ABOVE_LIMIT: the one-time split-interest gifts of a person are within
//   the indexed limit (section 408(d)(8)(F)).
// - DISASTER_ABOVE_QCD_REST: a gift to charity is excluded first, so the designated qualified
//   disaster distributions come from the rest of the person's own IRA distributions.
fn retirement_save_rules(
    draft: &FederalDraft,
    adjustment_items: &[IncomeDocumentItem],
    origins: &[(i64, usize, bool)],
    adjustment_positions: &[usize],
) -> Result<(), SaveFailure> {
    let source_failure = |key, ids: Vec<i64>, issue: ValidationIssue| {
        ids.iter().find_map(|id| origins.iter().find(|(source, _, _)| source == id)).map_or_else(
            || SaveFailure::from(status(key)),
            |(_, index, _)| SaveFailure::from(submitted_data_answer_issue(issue, *index)),
        )
    };
    let rows = |owner: Owner| {
        draft.income.iter().filter_map(move |e| match &e.income {
            FederalIncome::Retirement { data } if e.owner == owner => Some(data),
            _ => None,
        })
    };
    for owner in [Owner::Taxpayer, Owner::Spouse] {
        let rolled_row = |v: &FederalRetirement| {
            v.kind == RetirementKind::Ira
                && v.box7
                    & (DistributionCodes::CODE_G.0
                        | DistributionCodes::CODE_H.0
                        | DistributionCodes::CODE_N.0)
                    == 0
                && matches!(
                    v.ordinary_distribution,
                    RetirementTreatment::Rollover {
                        destination: crate::RolloverDestination::Ira
                            | crate::RolloverDestination::IraNextYear
                            | crate::RolloverDestination::SimpleIra,
                        ..
                    }
                )
        };
        let rolled = rows(owner).filter(|v| rolled_row(v)).count();
        // All of a person's IRAs, Roth ones too, are one for the rule (section 408(d)(3)(B)).
        let rolled_roth = draft
            .income
            .iter()
            .filter(|e| e.owner == owner)
            .filter(|e| {
                matches!(&e.income, FederalIncome::Roth { data }
                    if data.rolled_over > 0 && data.inherited == crate::InheritedLink::No)
            })
            .count();
        if rolled + rolled_roth > 1 {
            let key = if rolled_roth > 0 {
                "ROTH_ROLLOVER_ONCE_A_YEAR"
            } else {
                "IRA_ROLLOVER_ONCE_A_YEAR"
            };
            let mut ids: Vec<i64> = draft
                .income
                .iter()
                .filter(|e| e.owner == owner)
                .filter_map(|e| match &e.income {
                    FederalIncome::Retirement { data } if rolled_row(data) => Some(e.id),
                    FederalIncome::Roth { data }
                        if data.rolled_over > 0 && data.inherited == crate::InheritedLink::No =>
                    {
                        Some(e.id)
                    }
                    _ => None,
                })
                .collect();
            ids.rotate_left(1);
            return Err(source_failure(key, ids, ValidationIssue::new(key).at_field("code")));
        }
        // A Roth repayment is figured on the owner's Roth history (the 2026 Line 25c Worksheet).
        if draft.income.iter().any(|e| {
            e.owner == owner
                && matches!(&e.income, FederalIncome::Roth { data } if data.repaid.is_some())
        }) && !adjustment_items.iter().any(|item| {
            item.owner == owner && matches!(item.document, IncomeDocument::RothHistory(_))
        }) {
            let key = "R_ROTH_REPAYMENT_NEEDS_HISTORY";
            let ids = draft
                .income
                .iter()
                .filter(|e| e.owner == owner)
                .filter_map(|e| {
                    matches!(&e.income, FederalIncome::Roth { data } if data.repaid.is_some())
                        .then_some(e.id)
                })
                .collect();
            return Err(source_failure(key, ids, ValidationIssue::new(key).at_field("code")));
        }
        let returned: i64 = rows(owner)
            .map(|v| match v.ordinary_distribution {
                RetirementTreatment::Corrective { excess_deferral } if !v.kind.ira() => {
                    excess_deferral
                }
                _ => 0,
            })
            .sum();
        let person = draft.people.as_ref().and_then(|p| p.person(owner));
        let mut returned_cap = None;
        if returned > 0
            && person.is_none_or(|person| {
                let cap =
                    crate::elective_deferrals::excess(draft, owner, person.birth_date).taxable;
                returned_cap = Some(cap);
                returned > cap
            })
        {
            let key = "R_EXCESS_DEFERRAL_ABOVE_W2_EXCESS";
            let mut prefix = 0_i64;
            let ids = draft
                .income
                .iter()
                .filter(|e| e.owner == owner)
                .filter_map(|e| {
                    if let FederalIncome::Retirement { data } = &e.income
                        && !data.kind.ira()
                        && let RetirementTreatment::Corrective { excess_deferral } =
                            data.ordinary_distribution
                    {
                        let before = prefix;
                        prefix += excess_deferral;
                        let contributes_to_failure = match returned_cap {
                            Some(cap) => before <= cap && prefix > cap,
                            // Missing person facts provide no cap. Identify the
                            // first positive contribution without inventing one.
                            None => before == 0 && excess_deferral > 0,
                        };
                        if contributes_to_failure {
                            return Some(e.id);
                        }
                    }
                    None
                })
                .collect();
            return Err(source_failure(
                key,
                ids,
                ValidationIssue::new(key).at_field("excess_deferral").in_field("code"),
            ));
        }
        let gifts = |own_only: bool, split_only: bool| -> i64 {
            adjustment_items
                .iter()
                .filter(|item| item.owner == owner)
                .filter_map(|item| match &item.document {
                    IncomeDocument::Qcd(gift)
                        if (!own_only || gift.inherited.is_none())
                            && (!split_only || gift.split_interest) =>
                    {
                        Some(gift.amount)
                    }
                    _ => None,
                })
                .sum()
        };
        if gifts(false, true) > crate::year_constants::SPLIT_INTEREST_QCD_LIMIT_CENTS {
            let key = "QCD_SPLIT_INTEREST_ABOVE_LIMIT";
            // The gate above owns the sum. This scan only selects its first
            // crossing submitted contributor, so later zero rows are not blamed.
            let mut prefix = 0_i64;
            if let Some(index) = adjustment_items.iter().enumerate().find_map(|(index, item)| {
                if item.owner == owner
                    && let IncomeDocument::Qcd(gift) = &item.document
                    && gift.split_interest
                {
                    prefix += gift.amount;
                    if prefix > crate::year_constants::SPLIT_INTEREST_QCD_LIMIT_CENTS {
                        return Some(index);
                    }
                }
                None
            }) {
                return Err(submitted_data_answer_issue(
                    ValidationIssue::new(key).at_field("amount"),
                    adjustment_positions[index],
                )
                .into());
            }
            return Err(status(key).into());
        }
        let designated: i64 = rows(owner)
            .filter(|v| v.kind == RetirementKind::Ira)
            .filter_map(|v| match v.disaster {
                crate::DisasterDistribution::Qualified { amount, .. } => Some(amount),
                _ => None,
            })
            .sum();
        let own_gross: i64 =
            rows(owner).filter(|v| v.kind == RetirementKind::Ira).map(|v| v.gross).sum();
        if designated > 0 && designated + gifts(true, false) > own_gross {
            let key = "DISASTER_ABOVE_QCD_REST";
            let mut prefix = designated;
            if let Some(index) = adjustment_items.iter().enumerate().find_map(|(index, item)| {
                if item.owner == owner
                    && let IncomeDocument::Qcd(gift) = &item.document
                    && gift.inherited.is_none()
                {
                    let before = prefix;
                    prefix += gift.amount;
                    if before <= own_gross && prefix > own_gross {
                        return Some(index);
                    }
                }
                None
            }) {
                return Err(submitted_data_answer_issue(
                    ValidationIssue::new(key).at_field("amount"),
                    adjustment_positions[index],
                )
                .into());
            }
            let ids = draft.income.iter().filter(|e| e.owner == owner).filter_map(|e|
                matches!(&e.income, FederalIncome::Retirement { data } if data.kind == RetirementKind::Ira && matches!(data.disaster, crate::DisasterDistribution::Qualified { amount, .. } if amount > 0)).then_some(e.id)).collect();
            return Err(source_failure(
                key,
                ids,
                ValidationIssue::new(key).at_field("amount").in_field("disaster"),
            ));
        }
    }
    Ok(())
}
// QCD gift items grouped by owner into one QualifiedCharity worksheet per
// owner, each payment labelled from its date.
// The Retirement topic's lump-sum kind (u5-adjust): at most one for the
// return (LUMP_SUM_ELECTION_TWICE, the client rule on IncomeDocuments,
// checked again); none is the regular method.
fn social_election_record(
    items: &[IncomeDocumentItem],
    positions: &[usize],
) -> Result<SocialElection, SaveFailure> {
    let mut found = items.iter().enumerate().filter_map(|(index, item)| match &item.document {
        IncomeDocument::SocialLumpSums(v) => Some((index, v)),
        _ => None,
    });
    let Some((_, first)) = found.next() else {
        return Ok(SocialElection::Regular);
    };
    if let Some((index, _)) = found.next() {
        return Err(submitted_data_answer_issue(
            ValidationIssue::new("LUMP_SUM_ELECTION_TWICE").at_record(),
            positions[index],
        )
        .into());
    }
    let election = first.election();
    if !election.valid() {
        return Err(crate::interview::status(
            "MESSAGE_SOCIAL_SECURITY_FOR_EARLIER_YEARS_ENTER_EACH_EARLIER_YEAR_1984_2025_ONCE_WIT",
        )
        .into());
    }
    Ok(election)
}
// The Retirement topic's missed-RMD kind (u5-adjust): one Form 5329 Part IX
// group per row, the spouse's only on a joint return.
fn missed_distribution_records(
    interview: &Interview,
    items: &[IncomeDocumentItem],
    positions: &[usize],
) -> Result<Vec<crate::RequiredDistribution>, SaveFailure> {
    let mut records = Vec::new();
    for (index, item) in items.iter().enumerate() {
        let IncomeDocument::MissedRmd(v) = &item.document else {
            continue;
        };
        if item.owner == Owner::Spouse && !interview.joint() {
            return Err(ValidationIssue::new("MESSAGE_MISSED_REQUIRED_DISTRIBUTION_YOUR_SPOUSE_S_GO_ON_THIS_RETURN_ONLY_WHEN_YOU_F")
                .at_field("owner").in_list("documents", positions[index]).in_field("documents").into());
        }
        let record = v.record(item.owner);
        if record.label.trim().is_empty() || !record.valid() {
            return Err(crate::interview::status(
                "MESSAGE_MISSED_REQUIRED_DISTRIBUTION_ENTER_A_NAME_THE_AMOUNTS_CORRECTION_DATES_IN_20",
            ).into());
        }
        records.push(record);
    }
    Ok(records)
}
// The Retirement topic's Roth IRA history kind (u6-roth): one per owner
// (ROTH_HISTORY_TWICE, the client rule on IncomeDocuments, checked again).
fn roth_history_records(
    interview: &Interview,
    items: &[IncomeDocumentItem],
    positions: &[usize],
) -> Result<Vec<crate::RothHistory>, SaveFailure> {
    let mut records: Vec<crate::RothHistory> = Vec::new();
    for (index, item) in items.iter().enumerate() {
        let IncomeDocument::RothHistory(v) = &item.document else {
            continue;
        };
        if !interview.allowed_owners().contains(&(item.owner as i32)) {
            return Err(ValidationIssue::new("MESSAGE_ROTH_IRA_HISTORY_YOUR_SPOUSE_S_GOES_ON_THIS_RETURN_ONLY_WHEN_YOU_FILE_JOINTL")
                .at_field("owner").in_list("documents", positions[index]).in_field("documents").into());
        }
        if records.iter().any(|r| r.owner == item.owner) {
            return Err(ValidationIssue::new("ROTH_HISTORY_TWICE")
                .at_field("owner")
                .in_list("documents", positions[index])
                .in_field("documents")
                .into());
        }
        records.push(v.record(item.owner));
    }
    Ok(records)
}
// The Roth income kind back onto its 1099-R. Box 2a is not retained; it
// reopens at box 1, as a blank box 2a is entered.
fn roth_item(data: &crate::RothWithdrawal) -> R1099 {
    let (roth, ira) = crate::RothIraCode::from_record(data);
    // J printed with S (box 7b) is a Roth SIMPLE IRA inside its first two years.
    let box7 = DistributionCodes::of_roth(data.code)
        | if data.simple_early { DistributionCodes::CODE_S.0 } else { 0 };
    R1099 {
        state_details: Default::default(),
        gross: data.gross,
        taxable: data.gross,
        withholding: data.withholding,
        box7,
        allowed_treatments: DistributionCodes::treatments(box7, ira, false),
        allowed_methods: DistributionCodes::methods(box7, ira, false),
        code: DistributionCode::RothIra {
            roth,
            rolled_over: data.rolled_over,
            sequence: data.sequence,
        },
        ira,
        trump: false,
        more: RMore::default(),
        disaster: data.disaster.clone(),
        public_safety: Vec::new(),
        after_death: None,
    }
}
fn qcd_records(items: &[IncomeDocumentItem]) -> Vec<crate::QualifiedCharity> {
    let mut by_owner: Vec<(Owner, Vec<crate::QcdPayment>)> = Vec::new();
    for item in items {
        if let IncomeDocument::Qcd(gift) = &item.document {
            let payment = crate::QcdPayment {
                inherited: gift.inherited,
                date: gift.date,
                amount: gift.amount,
                split_interest: gift.split_interest,
            };
            match by_owner.iter_mut().find(|(owner, _)| *owner == item.owner) {
                Some((_, payments)) => payments.push(payment),
                None => by_owner.push((item.owner, alloc::vec![payment])),
            }
        }
    }
    by_owner
        .into_iter()
        .map(|(owner, payments)| crate::QualifiedCharity { owner, payments, prior_deductions: 0 })
        .collect()
}

// The data answers of M3-P15: kinds of an income topic that are
// FederalScreening facts, not income entries.
fn is_data_answer(document: &IncomeDocument) -> bool {
    matches!(document, data_answer_kinds!())
}
// A topic page's data answers onto the FederalScreening fields that topic
// owns; a topic without data answers owns none.
enum DataAnswers {
    None,
    Clergy(Vec<crate::ClergyClaim>),
    Foreign {
        account: Option<ForeignAccountOrTrust>,
        premium: Option<bool>,
    },
    // Investment sales: the 2025 returns and the Form 3921 exercises (T2-iso).
    InvestmentSales {
        capital: Vec<crate::PriorCapitalReturn>,
        iso: Vec<crate::IsoExercise>,
        installments: Vec<crate::EarlierInstallment>,
        carryback: Option<crate::Section1256Carryback>,
        related: Vec<crate::EarlierRelatedExchange>,
    },
    QbiLoss(Option<QbiLossCarryforward>),
    // Self-employment: the QBI carryforward and the earlier-year operating
    // losses it shares with Farming.
    SelfEmployment {
        qbi: Option<QbiLossCarryforward>,
        losses: Option<crate::LossCarryforward>,
        nonfarm: Vec<(Owner, crate::NonfarmSeHistory)>,
    },
    // The Retirement topic: earlier Forms 8915-F (T3-8915).
    Disaster(Vec<crate::DisasterCarry>),
    // The Work abroad topic: each person's Form 2555.
    WorkAbroad(Vec<crate::ForeignEarnedClaim>),
    // The Other income topic: each ABLE beneficiary's contributions (unit B6a).
    Able(Vec<crate::AbleContributions>),
    // The Farming topic (T2-45p): the QBI carryforward it shares with
    // Self-employment, Schedule J and the farm loss choice.
    Farming {
        qbi: Option<QbiLossCarryforward>,
        losses: Option<crate::LossCarryforward>,
        averaging: Option<crate::FarmAveraging>,
        nol: Option<crate::FarmNolElection>,
    },
}
// The operating-loss kind onto Form 172's and Form 6251 line 2f's histories;
// none entered is no history.
fn apply_losses(screening: &mut FederalScreening, losses: Option<crate::LossCarryforward>) {
    (screening.nol, screening.atnol) = match losses {
        Some(losses) => losses.histories(),
        None => (NolHistory::None, AtnolHistory::None),
    };
}
impl DataAnswers {
    fn apply(self, screening: &mut FederalScreening) {
        match self {
            Self::None => {}
            Self::Foreign { account: value, premium } => {
                screening.taxable_premium_election = premium;
                let value = value.unwrap_or(ForeignAccountOrTrust {
                    account: false,
                    fbar_required: None,
                    fbar_countries: Vec::new(),
                    trust: false,
                    highest_value: None,
                });
                screening.foreign_account = value.account;
                screening.fbar_required = value.fbar_required;
                screening.fbar_countries = value.fbar_countries;
                screening.foreign_trust = value.trust;
                screening.foreign_asset_max =
                    value.highest_value.filter(|_| value.account || value.trust);
            }
            Self::InvestmentSales { capital, iso, installments, carryback, related } => {
                screening.capital_history = capital;
                screening.iso_exercises = iso;
                screening.installment_payments = installments;
                screening.section_1256_carryback = carryback.as_ref().map(|v| v.amount);
                screening.section_1256_carryback_owners = carryback.and_then(|v| v.injured_owners);
                screening.related_exchanges = related;
            }
            Self::SelfEmployment { qbi, losses, nonfarm } => {
                Self::QbiLoss(qbi).apply(screening);
                apply_losses(screening, losses);
                for election in &mut screening.optional_se {
                    election.nonfarm = None;
                }
                for (owner, history) in nonfarm {
                    if let Some(election) =
                        screening.optional_se.iter_mut().find(|e| e.owner == owner)
                    {
                        election.nonfarm = Some(history);
                    } else {
                        screening.optional_se.push(SeElection {
                            owner,
                            farm: false,
                            nonfarm: Some(history),
                        });
                    }
                }
                screening.optional_se.retain(|e| e.farm || e.nonfarm.is_some());
            }
            Self::Farming { qbi, losses, averaging, nol } => {
                Self::QbiLoss(qbi).apply(screening);
                apply_losses(screening, losses);
                screening.farm_averaging = averaging;
                screening.farm_nol = nol;
            }
            Self::QbiLoss(value) => {
                screening.qbi_history = value.map_or(QbiHistory::NONE, |value| QbiHistory {
                    business: value.business,
                    reit_ptp: value.reit_ptp,
                    injured_owners: value.injured_owners.clone(),
                })
            }
            Self::Disaster(records) => screening.disaster_carries = records,
            Self::WorkAbroad(records) => screening.foreign_earned = records,
            Self::Clergy(records) => screening.clergy = records,
            Self::Able(records) => screening.able_contributions = records,
        }
    }
}
// The page's data answers, with their server checks: at most one foreign
// account item, one QBI carryforward and two 2025 returns; one real estate
// professional per owner, your spouse only on a joint return, and only with
// a rental property on the page.
// The section 1231 lookback (Form 4797 line 9) is one record for the whole
// return, shown and saved on both the self-employment and rentals pages;
// None for a page that does not show it.
fn lookback_records(
    topic: TaxSection,
    items: &[IncomeDocumentItem],
) -> Result<Option<Option<crate::Section1231History>>, SaveFailure> {
    if !matches!(
        topic,
        TaxSection::SelfEmployment
            | TaxSection::Rentals
            | TaxSection::Farming
            | TaxSection::InvestmentSales
    ) {
        return Ok(None);
    }
    let mut found = items.iter().enumerate().filter_map(|(index, item)| match &item.document {
        IncomeDocument::BusinessPropertyLosses(value) => Some((index, value.history())),
        _ => None,
    });
    let first = found.next();
    if let Some((index, _)) = found.next() {
        return Err(submitted_data_answer_issue(
            ValidationIssue::new("BUSINESS_PROPERTY_LOSSES_TWICE").at_record(),
            index,
        )
        .into());
    }
    if first.as_ref().is_some_and(|(_, value)| !value.valid()) {
        return Err(crate::interview::status(
            "MESSAGE_ENTER_EACH_LOSS_YEAR_FROM_2021_THROUGH_2025_ONCE_WITH_A_REMAINING_BALANCE_NO",
        )
        .into());
    }
    Ok(Some(first.map(|(_, value)| value)))
}
// The QBI loss carryforward kind, shared by Self-employment and Farming.
fn qbi_loss_answer(
    items: &[IncomeDocumentItem],
) -> Result<Option<QbiLossCarryforward>, SaveFailure> {
    let mut found = items.iter().enumerate().filter_map(|(index, item)| match &item.document {
        IncomeDocument::QbiLossCarryforward(value) => Some((index, value)),
        _ => None,
    });
    let first = found.next();
    if let Some((index, _)) = found.next() {
        return Err(submitted_data_answer_issue(
            ValidationIssue::new("QBI_LOSS_CARRYFORWARD_TWICE").at_record(),
            index,
        )
        .into());
    }
    if let Some((index, value)) = first
        && value
            .injured_owners
            .as_ref()
            .is_some_and(|owners| !owners.valid([value.business, value.reit_ptp]))
    {
        return Err(submitted_data_answer_issue(
            ValidationIssue::new("INJURED_QBI_OWNER_TOTAL").at_field("injured_owners"),
            index,
        )
        .into());
    }
    Ok(first.map(|(_, value)| value.clone()))
}

// The earlier-year operating-loss kind (u5-losses), shared by
// Self-employment and Farming: at most one (NOL_TWICE), with the server
// twins of its client rules and the stored ranges.
fn loss_answer(
    items: &[IncomeDocumentItem],
) -> Result<Option<crate::LossCarryforward>, crate::validation::SaveFailure> {
    let mut found = items.iter().enumerate().filter_map(|(index, item)| match &item.document {
        IncomeDocument::NetOperatingLoss(value) => Some((index, value.clone())),
        _ => None,
    });
    let first = found.next();
    if let Some((index, _)) = found.next() {
        return Err(ValidationIssue::new("NOL_TWICE")
            .at_field("document")
            .in_list("documents", index)
            .in_field("documents")
            .into());
    }
    if let Some((index, value)) = &first {
        if let Some(issue) = value.issue() {
            return Err(issue
                .in_field("document")
                .in_list("documents", *index)
                .in_field("documents")
                .into());
        }
        let (regular, amt) = value.histories();
        if !regular.valid() || !amt.valid() {
            return Err(crate::interview::status(
                "MESSAGE_NET_OPERATING_LOSS_ENTER_LOSS_YEARS_FROM_1900_THROUGH_2025_WITH_AMOUNTS_IN_T",
            ).into());
        }
    }
    Ok(first.map(|(_, value)| value))
}
// The Form 3921 kind (T2-iso) onto FederalScreening.iso_exercises, with
// the server twins of the kind's client rules and the 2026 recognition
// check: the shares enter AMT income (Form 6251 line 2i) on a 2026 exercise
// or, for restricted shares without an election, a 2026 vesting date.
fn form3921_records(
    interview: &Interview,
    items: &[IncomeDocumentItem],
) -> Result<Vec<crate::IsoExercise>, SaveFailure> {
    let mut records = Vec::new();
    for (index, item) in items.iter().enumerate() {
        let IncomeDocument::Form3921(form) = &item.document else {
            continue;
        };
        if form.granted > form.exercised {
            return Err(ValidationIssue::new("ISO_EXERCISED_BEFORE_GRANTED")
                .at_field("exercised")
                .in_field("document")
                .in_list("documents", index)
                .in_field("documents")
                .into());
        }
        if form.more.sold > form.shares {
            return Err(ValidationIssue::new("ISO_SOLD_ABOVE_TRANSFERRED")
                .at_field("sold")
                .in_field("more")
                .in_field("document")
                .in_list("documents", index)
                .in_field("documents")
                .into());
        }
        if let crate::IsoRecognition::Vesting { date, .. } = &form.more.recognition
            && *date < form.exercised
        {
            return Err(ValidationIssue::new("ISO_VESTED_BEFORE_EXERCISED")
                .at_field("date")
                .in_field("recognition")
                .in_field("more")
                .in_field("document")
                .in_list("documents", index)
                .in_field("documents")
                .into());
        }
        if item.owner == Owner::Spouse && !interview.joint() {
            return Err(crate::interview::status(
                "MESSAGE_FORM_3921_YOUR_SPOUSE_S_STOCK_OPTIONS_GO_ON_THIS_RETURN_ONLY_WHEN_YOU_FILE_J",
            ).into());
        }
        let record = form.record(item.owner);
        if !record.valid_timing() {
            return Err(crate::interview::status(
                "MESSAGE_FORM_3921_THESE_SHARES_ENTER_ALTERNATIVE_MINIMUM_TAXABLE_INCOME_FORM_6251_LI",
            ).into());
        }
        if !crate::extended_rules::valid_exercises(core::slice::from_ref(&record)) {
            return Err(crate::interview::status(
                "MESSAGE_FORM_3921_CHECK_THE_SHARE_COUNTS_UP_TO_SIX_DECIMAL_PLACES_AND_THE_NAMES",
            )
            .into());
        }
        records.push(record);
    }
    Ok(records)
}
// The earlier-year installment kind (T3-6252) onto
// FederalScreening.installment_payments, with the server twins of the
// kind's client rules. Refusals (Something else applies) are stored.
fn installment_payment_issue(sale: &crate::InstallmentPayments) -> Option<ValidationIssue> {
    if sale.gross_profit > sale.contract_price {
        Some(ValidationIssue::new("INSTALLMENT_PROFIT_ABOVE_CONTRACT").at_field("gross_profit"))
    } else if i128::from(sale.earlier_payments) + i128::from(sale.payments)
        > i128::from(sale.contract_price)
    {
        Some(ValidationIssue::new("INSTALLMENT_PAID_ABOVE_CONTRACT").at_field("payments"))
    } else {
        None
    }
}
fn repeated_document_issue(
    items: &[IncomeDocumentItem],
    key: &'static str,
    selects: impl Fn(&IncomeDocument) -> bool,
) -> Option<ValidationIssue> {
    items
        .iter()
        .enumerate()
        .filter(|(_, item)| selects(&item.document))
        .nth(1)
        .map(|(index, _)| submitted_data_answer_issue(ValidationIssue::new(key).at_record(), index))
}
fn submitted_data_answer_issue(issue: ValidationIssue, index: usize) -> ValidationIssue {
    issue.in_field("document").in_list("documents", index).in_field("documents")
}
fn installment_records(
    interview: &Interview,
    items: &[IncomeDocumentItem],
) -> Result<Vec<crate::EarlierInstallment>, crate::validation::SaveFailure> {
    let mut records = Vec::new();
    for (index, item) in items.iter().enumerate() {
        let IncomeDocument::InstallmentPayments(page) = &item.document else {
            continue;
        };
        let sale = page.record();
        if let Some(issue) = installment_payment_issue(&sale) {
            return Err(submitted_data_answer_issue(issue, index).into());
        }
        if item.owner == Owner::Spouse && !interview.joint() {
            return Err(crate::interview::status(
                "MESSAGE_INSTALLMENT_PAYMENTS_YOUR_SPOUSE_S_SALES_GO_ON_THIS_RETURN_ONLY_WHEN_YOU_FIL",
            ).into());
        }
        if !sale.valid() {
            return Err(crate::interview::status(
                "MESSAGE_INSTALLMENT_PAYMENTS_ENTER_THE_PROPERTY_A_SALE_DATE_BEFORE_2026_AND_THE_AMOU",
            ).into());
        }
        records.push(crate::EarlierInstallment { owner: item.owner, sale: sale.clone() });
    }
    Ok(records)
}
// The 2026 section 1256 loss carryback (Form 6781 line6), preserving the
// existing duplicate-first, amount, then actual ownership predicate order.
fn section1256_carryback_issue(value: &crate::Section1256Carryback) -> Option<ValidationIssue> {
    if !(1..=100_000_000_000).contains(&value.amount) {
        return Some(
            ValidationIssue::new(
                "MESSAGE_SECTION_1256_ENTER_A_CARRYBACK_AMOUNT_WITHIN_THE_SUPPORTED_RANGE",
            )
            .at_field("amount"),
        );
    }
    if value.injured_owners.as_ref().is_some_and(|owners| !owners.valid(value.amount)) {
        // This existing composite native owner does not expose a narrower leaf.
        return Some(
            ValidationIssue::new("INJURED_CARRYBACK_OWNER_TOTAL").at_field("injured_owners"),
        );
    }
    None
}
fn carryback_record(
    items: &[IncomeDocumentItem],
) -> Result<Option<crate::Section1256Carryback>, crate::validation::SaveFailure> {
    let mut found = items.iter().enumerate().filter_map(|(index, item)| match &item.document {
        IncomeDocument::Section1256Carryback(value) => Some((index, value)),
        _ => None,
    });
    let first = found.next();
    if let Some((index, _)) = found.next() {
        return Err(submitted_data_answer_issue(
            ValidationIssue::new("SECTION_1256_CARRYBACK_TWICE").at_record(),
            index,
        )
        .into());
    }
    if let Some((index, value)) = first
        && let Some(issue) = section1256_carryback_issue(value)
    {
        return Err(submitted_data_answer_issue(issue, index).into());
    }
    Ok(first.map(|(_, value)| value.clone()))
}
fn nonfarm_optional_records(
    interview: &Interview,
    items: &[IncomeDocumentItem],
) -> Result<Vec<(Owner, crate::NonfarmSeHistory)>, crate::validation::SaveFailure> {
    let mut records: Vec<(Owner, crate::NonfarmSeHistory)> = Vec::new();
    for (index, item) in items.iter().enumerate() {
        let IncomeDocument::NonfarmOptionalMethod(history) = &item.document else {
            continue;
        };
        if !interview.allowed_owners().contains(&(item.owner as i32)) {
            return Err(ValidationIssue::new("NONFARM_OPTIONAL_OWNER_INVALID")
                .at_field("owner")
                .in_list("documents", index)
                .in_field("documents")
                .into());
        }
        if records.iter().any(|(owner, _)| *owner == item.owner) {
            return Err(submitted_data_answer_issue(
                ValidationIssue::new("NONFARM_OPTIONAL_TWICE").at_record(),
                index,
            )
            .into());
        }
        if let Some(issue) = history.issue() {
            return Err(submitted_data_answer_issue(issue, index).into());
        }
        records.push((item.owner, history.clone()));
    }
    Ok(records)
}
// The earlier-year related-party exchange kind (Form 8824 Part II) onto
// FederalScreening.related_exchanges, with the server twins of the kind's
// client rule. Refusals (Something else applies) are stored.
fn related_exchange_records(
    interview: &Interview,
    items: &[IncomeDocumentItem],
) -> Result<Vec<crate::EarlierRelatedExchange>, SaveFailure> {
    let mut records = Vec::new();
    for (index, item) in items.iter().enumerate() {
        let IncomeDocument::RelatedExchange(exchange) = &item.document else {
            continue;
        };
        if let Some(issue) = exchange.issue() {
            return Err(submitted_data_answer_issue(issue, index).into());
        }
        if item.owner == Owner::Spouse && !interview.joint() {
            return Err(ValidationIssue::new("MESSAGE_RELATED_EXCHANGE_YOUR_SPOUSE_S_GOES_ON_THIS_RETURN_ONLY_WHEN_YOU_FILE_JOINTLY")
                .at_field("owner").in_list("documents", index).in_field("documents").into());
        }
        if !exchange.valid() {
            return Err(crate::interview::status(
                "MESSAGE_RELATED_EXCHANGE_ENTER_THE_PROPERTY_A_LAST_TRANSFER_IN_2024_OR_2025_AND_THE_DATE_IN_2026",
            ).into());
        }
        records
            .push(crate::EarlierRelatedExchange { owner: item.owner, exchange: exchange.clone() });
    }
    Ok(records)
}
// The Work abroad topic's Form 2555 kind onto FederalScreening.foreign_earned,
// with the server twins of the kind's client rules: one per person
// (FORM_2555_TWICE), a spouse only on a joint return.
fn foreign_earned_records(
    interview: &Interview,
    items: &[IncomeDocumentItem],
) -> Result<Vec<crate::ForeignEarnedClaim>, SaveFailure> {
    let mut records: Vec<crate::ForeignEarnedClaim> = Vec::new();
    for (index, item) in items.iter().enumerate() {
        let IncomeDocument::Form2555(v) = &item.document else {
            continue;
        };
        if let Some(key) = v.rule() {
            return Err(libertas_formatted_text(key, &[]).into());
        }
        if !interview.allowed_owners().contains(&(item.owner as i32)) {
            return Err(ValidationIssue::new(
                "MESSAGE_FORM_2555_YOUR_SPOUSE_S_GOES_ON_THIS_RETURN_ONLY_WHEN_YOU_FILE_JOINTLY",
            )
            .at_field("owner")
            .in_list("documents", index)
            .in_field("documents")
            .into());
        }
        if records.iter().any(|r| r.owner == item.owner) {
            return Err(submitted_data_answer_issue(
                ValidationIssue::new("FORM_2555_TWICE").at_record(),
                index,
            )
            .into());
        }
        if !v.housing.valid() {
            return Err(crate::interview::status(
                "MESSAGE_FORM_2555_ENTER_VALID_HOUSING_EXPENSES_ALLOWANCES_HOUSEHOLD_AMOUNTS_AND_2026_STAY_DATES",
            ).into());
        }
        records.push(v.record(item.owner));
    }
    Ok(records)
}
fn data_answer_records(
    interview: &Interview,
    topic: TaxSection,
    items: &[IncomeDocumentItem],
) -> Result<DataAnswers, crate::validation::SaveFailure> {
    let key = |key: &str| crate::validation::SaveFailure::from(libertas_formatted_text(key, &[]));
    Ok(match topic {
        TaxSection::Wages => {
            let mut records: Vec<crate::ClergyClaim> = Vec::new();
            for (index, item) in items.iter().enumerate() {
                let IncomeDocument::Clergy(record) = &item.document else {
                    continue;
                };
                if !interview.allowed_owners().contains(&(item.owner as i32)) {
                    return Err(key("CLERGY_OWNER_INVALID"));
                }
                if records.iter().any(|r| r.owner == item.owner) {
                    return Err(ValidationIssue::new("CLERGY_TWICE")
                        .at_field("owner")
                        .in_list("documents", index)
                        .in_field("documents")
                        .into());
                }
                if !record.role.valid() {
                    return Err(key("CLERGY_AMOUNT_INVALID"));
                }
                records.push(crate::ClergyClaim { owner: item.owner, role: record.role.clone() });
            }
            DataAnswers::Clergy(records)
        }
        TaxSection::InterestDividends => {
            let mut found =
                items.iter().enumerate().filter_map(|(index, item)| match &item.document {
                    IncomeDocument::ForeignAccountOrTrust(value) => Some((index, value.clone())),
                    _ => None,
                });
            let first = found.next();
            if let Some((index, _)) = found.next() {
                return Err(submitted_data_answer_issue(
                    ValidationIssue::new("FOREIGN_ACCOUNT_TWICE").at_record(),
                    index,
                )
                .into());
            }
            // The client rule on the kind, checked again.
            if first
                .as_ref()
                .is_some_and(|(_, v)| (v.account || v.trust) && v.highest_value.is_none())
            {
                return Err(key("FOREIGN_ASSETS_VALUE_NEEDED"));
            }
            let mut elections =
                items.iter().enumerate().filter_map(|(index, item)| match item.document {
                    IncomeDocument::TaxableBondPremium(value) => Some((index, value)),
                    _ => None,
                });
            let premium = elections.next();
            if let Some((index, _)) = elections.next() {
                return Err(submitted_data_answer_issue(
                    ValidationIssue::new("TAXABLE_PREMIUM_ELECTION_TWICE").at_record(),
                    index,
                )
                .into());
            }
            DataAnswers::Foreign {
                account: first.map(|(_, value)| value),
                premium: premium.map(|(_, value)| value),
            }
        }
        TaxSection::InvestmentSales => {
            let returns: Vec<_> = items
                .iter()
                .filter_map(|item| match &item.document {
                    IncomeDocument::CapitalLossCarryover(value) => Some(value.clone().into()),
                    _ => None,
                })
                .collect();
            // Tax structure: one prior return per taxpayer/spouse; a joint return represents both.
            if returns.len() > 2 {
                return Err(key("CAPITAL_LOSS_CARRYOVER_LIMIT"));
            }
            DataAnswers::InvestmentSales {
                capital: returns,
                iso: form3921_records(interview, items)?,
                installments: installment_records(interview, items)?,
                carryback: carryback_record(items)?,
                related: related_exchange_records(interview, items)?,
            }
        }
        TaxSection::SelfEmployment => {
            // Preserve history refusal priority before QBI and loss collection.
            let nonfarm = nonfarm_optional_records(interview, items)?;
            DataAnswers::SelfEmployment {
                qbi: qbi_loss_answer(items)?,
                losses: loss_answer(items)?,
                nonfarm,
            }
        }
        TaxSection::Retirement => DataAnswers::Disaster(disaster_records(interview, items)?),
        TaxSection::WorkAbroad => {
            DataAnswers::WorkAbroad(foreign_earned_records(interview, items)?)
        }
        // At most one record of ABLE contributions for each beneficiary
        // (ABLE_CONTRIBUTIONS_TWICE, the client rule on IncomeDocuments, checked
        // again); your spouse's only on a joint return.
        TaxSection::OtherIncome => {
            let mut records: Vec<crate::AbleContributions> = Vec::new();
            for (index, item) in items.iter().enumerate() {
                let IncomeDocument::AbleContributions(page) = &item.document else {
                    continue;
                };
                if !interview.allowed_owners().contains(&(item.owner as i32)) {
                    return Err(ValidationIssue::new("MESSAGE_ABLE_CONTRIBUTIONS_YOUR_SPOUSE_S_GO_ON_THIS_RETURN_ONLY_WHEN_YOU_FILE_JOINTLY")
                .at_field("owner").in_list("documents", index).in_field("documents").into());
                }
                if records.iter().any(|r| r.owner == item.owner) {
                    return Err(ValidationIssue::new("ABLE_CONTRIBUTIONS_TWICE")
                        .at_field("owner")
                        .in_list("documents", index)
                        .in_field("documents")
                        .into());
                }
                records.push(page.record(item.owner));
            }
            if records.iter().any(|r| !r.valid()) {
                return Err(key("ABLE_CONTRIBUTIONS_INVALID"));
            }
            DataAnswers::Able(records)
        }
        // The two return-level farm kinds, at most one of each (the client
        // rules FARM_AVERAGING_TWICE and FARM_LOSS_TWICE, checked again).
        TaxSection::Farming => {
            let averaging: Vec<_> = items
                .iter()
                .filter_map(|item| match &item.document {
                    IncomeDocument::FarmAveraging(value) => {
                        Some(crate::farm_page::averaging_record(value))
                    }
                    _ => None,
                })
                .collect();
            if let Some(issue) =
                repeated_document_issue(items, "FARM_AVERAGING_TWICE", |document| {
                    matches!(document, IncomeDocument::FarmAveraging(_))
                })
            {
                return Err(issue.into());
            }
            let nol: Vec<_> = items
                .iter()
                .filter_map(|item| match &item.document {
                    IncomeDocument::FarmLoss(value) => {
                        Some(crate::farm_page::farm_loss_record(value))
                    }
                    _ => None,
                })
                .collect();
            if let Some(issue) = repeated_document_issue(items, "FARM_LOSS_TWICE", |document| {
                matches!(document, IncomeDocument::FarmLoss(_))
            }) {
                return Err(issue.into());
            }
            DataAnswers::Farming {
                qbi: qbi_loss_answer(items)?,
                losses: loss_answer(items)?,
                averaging: averaging.into_iter().next(),
                nol: nol.into_iter().next(),
            }
        }
        _ => DataAnswers::None,
    })
}
// The answer of a row that is no income item (a Form 8606, a QCD gift, an IRA
// history or a return-wide answer): on a community-property return the account
// owner's own, whatever the page's allowed set asks of the income rows.
fn fixed_community(d: &FederalDraft) -> CommunityShare {
    if d.setup.as_ref().is_some_and(crate::community::applies) {
        CommunityShare::Separate
    } else {
        CommunityShare::NotNeeded
    }
}
// The reverse of data_answer_records: the rows a topic page reopens with, or
// None for a stored answer this page could not have written.
fn data_answer_items(d: &FederalDraft, topic: TaxSection) -> Option<Vec<IncomeDocumentItem>> {
    let Some(screening) = d.screening.as_ref() else {
        return Some(Vec::new());
    };
    let item = |owner: Owner, document: IncomeDocument| IncomeDocumentItem {
        refund_management: None,
        refund_management_needed: None,
        allowed_community: Vec::new(),
        investment_caps: match &document {
            IncomeDocument::CapitalLossCarryover(v) => {
                Some(crate::extended_rules::capital_caps(&v.clone().into()))
            }
            _ => None,
        },
        id: 0,
        owner,
        document,
        preview: None,
        community: fixed_community(d),
    };
    Some(match topic {
        TaxSection::Wages => screening
            .clergy
            .iter()
            .map(|c| {
                item(c.owner, IncomeDocument::Clergy(crate::ClergyRecord { role: c.role.clone() }))
            })
            .collect(),
        TaxSection::InterestDividends => {
            let (account, trust) = (screening.foreign_account, screening.foreign_trust);
            let mut items = if account || trust {
                alloc::vec![item(
                    Owner::Taxpayer,
                    IncomeDocument::ForeignAccountOrTrust(ForeignAccountOrTrust {
                        account,
                        fbar_required: screening.fbar_required,
                        fbar_countries: screening.fbar_countries.clone(),
                        trust,
                        highest_value: screening.foreign_asset_max,
                    }),
                )]
            } else if screening.fbar_required.is_some()
                || !screening.fbar_countries.is_empty()
                || screening.foreign_asset_max.is_some()
            {
                return None;
            } else {
                Vec::new()
            };
            if let Some(answer) = screening.taxable_premium_election {
                items.push(item(Owner::Taxpayer, IncomeDocument::TaxableBondPremium(answer)));
            }
            items
        }
        TaxSection::InvestmentSales => screening
            .capital_history
            .iter()
            .map(|value| {
                Some(item(
                    Owner::Taxpayer,
                    IncomeDocument::CapitalLossCarryover(value.clone().into()),
                ))
            })
            .chain(screening.iso_exercises.iter().map(|value| {
                Some(item(
                    value.owner,
                    IncomeDocument::Form3921(crate::Form3921::from_record(value)?),
                ))
            }))
            .chain(screening.installment_payments.iter().map(|value| {
                Some(item(value.owner, IncomeDocument::InstallmentPayments(value.sale.page())))
            }))
            .chain(screening.section_1256_carryback.map(|amount| {
                Some(item(
                    Owner::Taxpayer,
                    IncomeDocument::Section1256Carryback(crate::Section1256Carryback {
                        amount,
                        injured_owners: screening.section_1256_carryback_owners.clone(),
                    }),
                ))
            }))
            .chain(screening.related_exchanges.iter().map(|value| {
                Some(item(value.owner, IncomeDocument::RelatedExchange(value.exchange.clone())))
            }))
            .collect::<Option<Vec<_>>>()?,
        TaxSection::SelfEmployment | TaxSection::Farming => {
            // Zero carryforwards are no carryforward: the kind reopens only
            // with an amount.
            let history = &screening.qbi_history;
            let mut items = if history.any() {
                alloc::vec![item(
                    Owner::Taxpayer,
                    IncomeDocument::QbiLossCarryforward(QbiLossCarryforward {
                        business: history.business,
                        reit_ptp: history.reit_ptp,
                        injured_owners: history.injured_owners.clone(),
                    }),
                )]
            } else {
                Vec::new()
            };
            if let Some(losses) =
                crate::LossCarryforward::from_histories(&screening.nol, &screening.atnol)
            {
                items.push(item(Owner::Taxpayer, IncomeDocument::NetOperatingLoss(losses?)));
            }
            if topic == TaxSection::SelfEmployment {
                items.extend(screening.optional_se.iter().filter_map(|e| {
                    e.nonfarm
                        .as_ref()
                        .map(|h| item(e.owner, IncomeDocument::NonfarmOptionalMethod(h.clone())))
                }));
            }
            if topic == TaxSection::Farming {
                if let Some(value) = &screening.farm_averaging {
                    items.push(item(
                        Owner::Taxpayer,
                        IncomeDocument::FarmAveraging(crate::farm_page::averaging_item(value)?),
                    ));
                }
                if let Some(value) = &screening.farm_nol {
                    items.push(item(
                        Owner::Taxpayer,
                        IncomeDocument::FarmLoss(crate::farm_page::farm_loss_item(value)?),
                    ));
                }
            }
            items
        }
        TaxSection::Retirement => screening
            .disaster_carries
            .iter()
            .map(|c| item(c.owner, IncomeDocument::Form8915(c.form.clone())))
            .collect(),
        TaxSection::WorkAbroad => screening
            .foreign_earned
            .iter()
            .map(|c| item(c.owner, IncomeDocument::Form2555(crate::Form2555::from_record(c))))
            .collect(),
        TaxSection::OtherIncome => screening
            .able_contributions
            .iter()
            .map(|c| item(c.owner, IncomeDocument::AbleContributions(c.page())))
            .collect(),
        _ => Vec::new(),
    })
}
// The Retirement topic's Form 8915-F checks (T3-8915): one earlier form per
// owner, tax year and disaster year (FORM_8915_TWICE), and across the page's
// 1099-R folds one line 1b amount per disaster (DISASTER_EARLIER_DIFFERS),
// the $22,000 line 1e limit per disaster (DISASTER_ABOVE_LIMIT, the client
// rule checks one 1099-R) and one lines 11/22 election per disaster year
// (DISASTER_ELECTION_DIFFERS). A spouse's forms only on a joint return.
fn disaster_records(
    interview: &Interview,
    items: &[IncomeDocumentItem],
) -> Result<Vec<crate::DisasterCarry>, SaveFailure> {
    let mut limits: Vec<(Owner, u32, i64, i64)> = Vec::new();
    let mut elections: Vec<(Owner, u32, crate::DisasterSpread)> = Vec::new();
    for (index, item) in items.iter().enumerate() {
        let IncomeDocument::R1099(R1099 {
            disaster:
                crate::DisasterDistribution::Qualified { fema, began, amount, earlier, spread, .. },
            ..
        }) = &item.document
        else {
            continue;
        };
        match limits.iter_mut().find(|(owner, id, ..)| *owner == item.owner && id == fema) {
            Some((_, _, _, other)) if other != earlier => {
                return Err(submitted_data_answer_issue(
                    ValidationIssue::new("DISASTER_EARLIER_DIFFERS")
                        .at_field("earlier")
                        .in_field("disaster"),
                    index,
                )
                .into());
            }
            Some((_, _, total, _)) => *total += amount,
            None => limits.push((item.owner, *fema, *amount, *earlier)),
        }
        let year = began / 10000;
        match elections.iter().find(|(owner, y, _)| *owner == item.owner && *y == year) {
            Some((_, _, other)) if other != spread => {
                return Err(submitted_data_answer_issue(
                    ValidationIssue::new("DISASTER_ELECTION_DIFFERS")
                        .at_field("spread")
                        .in_field("disaster"),
                    index,
                )
                .into());
            }
            Some(_) => {}
            None => elections.push((item.owner, year, *spread)),
        }
    }
    if let Some((owner, fema, _, earlier)) =
        limits.iter().find(|(_, _, total, earlier)| total + earlier > crate::disaster::LIMIT)
    {
        // Admission was decided once above, after the original complete group
        // scan. This prefix scan selects metadata only for that rejected group;
        // a later zero/tiny contribution must not hide the first crossing row.
        let mut running = *earlier;
        let (index, field) = items
            .iter()
            .enumerate()
            .find_map(|(index, item)| {
                let IncomeDocument::R1099(R1099 {
                    disaster: crate::DisasterDistribution::Qualified { fema: source, amount, .. },
                    ..
                }) = &item.document
                else {
                    return None;
                };
                if item.owner != *owner || source != fema {
                    return None;
                }
                if running > crate::disaster::LIMIT {
                    return Some((index, "earlier"));
                }
                running += amount;
                (running > crate::disaster::LIMIT).then_some((index, "amount"))
            })
            .expect("failed complete disaster total has a crossing source row");
        return Err(submitted_data_answer_issue(
            ValidationIssue::new("DISASTER_ABOVE_LIMIT").at_field(field).in_field("disaster"),
            index,
        )
        .into());
    }
    let mut records: Vec<crate::DisasterCarry> = Vec::new();
    for (index, item) in items.iter().enumerate() {
        let IncomeDocument::Form8915(form) = &item.document else {
            continue;
        };
        if item.owner == Owner::Spouse && !interview.joint() {
            return Err(crate::interview::status(
                "MESSAGE_FORM_8915_F_YOUR_SPOUSE_S_FORMS_GO_ON_THIS_RETURN_ONLY_WHEN_YOU_FILE_JOINTLY",
            ).into());
        }
        if records.iter().any(|c| {
            c.owner == item.owner
                && core::mem::discriminant(&c.form.year) == core::mem::discriminant(&form.year)
                && c.form.disaster_year == form.disaster_year
        }) {
            return Err(submitted_data_answer_issue(
                ValidationIssue::new("FORM_8915_TWICE").at_record(),
                index,
            )
            .into());
        }
        records.push(crate::DisasterCarry { owner: item.owner, form: form.clone() });
    }
    Ok(records)
}

// Supporting facts have no income-property classification. Their one fixed
// answer remains available and hidden by the existing single-choice template.
fn document_community_answers(draft: &FederalDraft, document: &IncomeDocument) -> Vec<i32> {
    if matches!(document, adjustment_kinds!() | data_answer_kinds!()) {
        alloc::vec![crate::community::index(fixed_community(draft))]
    } else {
        crate::injured_spouse::community_answers(draft)
    }
}
fn document_community_issue(
    draft: &FederalDraft,
    item: &IncomeDocumentItem,
) -> Option<ValidationIssue> {
    if matches!(item.document, adjustment_kinds!() | data_answer_kinds!()) {
        (item.community != fixed_community(draft))
            .then(|| ValidationIssue::new("COMMUNITY_ANSWER_NOT_ALLOWED").at_record())
    } else {
        crate::injured_spouse::community_row_issue(draft, item.community)
    }
    .map(|issue| issue.in_field("community"))
}

// Supporting history and adjustment answers never become income entries.
fn document_refund_management_needed(
    draft: &FederalDraft,
    result: &FederalResult,
    item: &IncomeDocumentItem,
) -> Option<bool> {
    if !crate::injured_spouse::texas(draft)
        || matches!(item.document, adjustment_kinds!() | data_answer_kinds!())
    {
        return Some(false);
    }
    let entry = draft.income.iter().find(|e| item.id > 0 && e.id == item.id)?;
    crate::injured_spouse::management_needed(draft, result, entry)
}

fn income_refund_management(
    draft: &FederalDraft,
    result: &FederalResult,
    origins: &[(i64, usize, bool)],
    rows: usize,
) -> Vec<crate::IncomeRefundManagementDerived> {
    (0..rows)
        .map(|index| {
            let mut known = Some(false);
            for (id, _, _) in origins.iter().filter(|(_, submitted, _)| *submitted == index) {
                let current = draft
                    .income
                    .iter()
                    .find(|e| e.id == *id)
                    .and_then(|e| crate::injured_spouse::management_needed(draft, result, e));
                known = match (known, current) {
                    (Some(true), _) | (_, Some(true)) => Some(true),
                    (Some(false), Some(false)) => Some(false),
                    _ => None,
                };
            }
            crate::IncomeRefundManagementDerived { refund_management_needed: known }
        })
        .collect()
}

// One page row onto its stored record.
fn document_entry(item: IncomeDocumentItem, accepted: &[FederalIncomeEntry]) -> FederalIncomeEntry {
    let state_source = crate::IncomeStateSource::from_document(&item.document);
    let mut income = document_income(&item.document);
    // A business keeps the owner health insurance and retirement plan the
    // adjustments page stored on the accepted record.
    if let FederalIncome::Business { data } = &mut income
        && let Some(FederalIncome::Business { data: kept }) =
            accepted.iter().find(|e| item.id != 0 && e.id == item.id).map(|e| &e.income)
    {
        data.health_insurance = kept.health_insurance.clone();
        data.retirement = kept.retirement.clone();
    }
    // A partnership K-1 keeps the partner's coverage, distribution-paid
    // premiums and plan choice of the self-employed benefits page; boxes 13
    // code M and R are the K-1 page's own (T2-43p).
    if let FederalIncome::Partnership { data } = &mut income
        && let Some(FederalIncome::Partnership { data: kept }) =
            accepted.iter().find(|e| item.id != 0 && e.id == item.id).map(|e| &e.income)
    {
        data.health_insurance = kept.health_insurance.clone();
        data.health_distributions = kept.health_distributions;
        data.retirement = kept.retirement.clone();
    }
    if let FederalIncome::Scorp { data } = &mut income
        && let Some(FederalIncome::Scorp { data: kept }) =
            accepted.iter().find(|e| item.id != 0 && e.id == item.id).map(|e| &e.income)
    {
        data.health_insurance = kept.health_insurance.clone();
    }
    crate::k1_activity::preserve_person_sources(
        &mut income,
        accepted.iter().find(|e| item.id != 0 && e.id == item.id).map(|e| &e.income),
    );
    // The name the person typed; the page does not ask a W-2's, so a W-2 row
    // that keeps an accepted identity keeps its accepted name. A source with no
    // name stays unnamed: the document kind and identity name it where shown.
    let label = match item.document {
        IncomeDocument::W2(_) => accepted
            .iter()
            .find(|e| item.id != 0 && e.id == item.id)
            .map(|e| e.label.clone())
            .unwrap_or_default(),
        IncomeDocument::Int1099(Int1099 { payer, .. })
        | IncomeDocument::Div1099(Div1099 { payer, .. })
        | IncomeDocument::Oid1099(Oid1099 { payer, .. }) => payer,
        IncomeDocument::SellerMortgageInterest(v) => v.buyer.buyer,
        IncomeDocument::Sale1099B(Sale1099B { description, .. }) => description,
        IncomeDocument::OpportunityFund(ref v) => v.fund.clone(),
        IncomeDocument::OpportunityFundDeferral(ref v) => v.fund.clone(),
        IncomeDocument::Contracts1099B(Contracts1099B { broker, .. }) => broker,
        IncomeDocument::IsoShareSale(ref v) => v.label(),
        IncomeDocument::EmployeeShareSale(ref v) => v.label(),
        IncomeDocument::EsppShareSale(ref v) => v.label(),
        IncomeDocument::NuaShareSale(ref v) => v.label(),
        IncomeDocument::QsbsSale(ref v) => v.issuer.clone(),
        IncomeDocument::SmallBusinessStockLoss(_)
        | IncomeDocument::WorthlessSecurity(_)
        | IncomeDocument::BadDebt(_) => Default::default(),
        IncomeDocument::CapitalReturn1099Div(ref v) => v.label(),
        IncomeDocument::Form2439(ref v) => v.label(),
        IncomeDocument::MainHomeSale(ref v) => v.label(),
        IncomeDocument::Farm(ref f) => crate::farm_page::farm_label(f),
        IncomeDocument::FarmRental(ref f) => crate::farm_page::farm_rental_label(f),
        IncomeDocument::OtherIncome(ref v) => match &v.kind {
            crate::OtherIncomeKind::Other { description } => description.clone(),
            _ => alloc::string::String::new(),
        },
        IncomeDocument::Business(Business { name, .. }) => name,
        IncomeDocument::Rental(Rental { address, .. }) => address,
        IncomeDocument::K1EstateTrust(K1EstateTrust { name, .. }) => name,
        IncomeDocument::K1PartnershipActivities(v) => v.name,
        IncomeDocument::K1ScorpActivities(v) => v.name,
        IncomeDocument::K1Scorp(K1Scorp { name, .. }) => name,
        IncomeDocument::K1Partnership(K1Partnership { name, .. }) => name,
        IncomeDocument::InheritedIra(ref v) => v.decedent.clone(),
        IncomeDocument::ForeignPay(ref v) => v.employer.clone(),
        // The name the person typed for an insured who is not on the return.
        IncomeDocument::LtcInsured(ref v) => match &v.insured {
            crate::LtcInsuredPerson::Other { name } => name.clone(),
            crate::LtcInsuredPerson::OnReturn { .. } => alloc::string::String::new(),
        },
        IncomeDocument::Cancel1099C(Cancel1099C { creditor, .. }) => creditor,
        IncomeDocument::Acquisition1099A(Acquisition1099A { lender, .. }) => lender,
        // A child's election is named by its child on the people page.
        IncomeDocument::Form8814(_)
        | IncomeDocument::SavingsBonds(_)
        | IncomeDocument::Q1099(_)
        | IncomeDocument::Sa1099(_)
        | IncomeDocument::Ltc1099(_)
        | IncomeDocument::Qa1099(_)
        | IncomeDocument::EducationAccountExpenses(_)
        | IncomeDocument::R1099(_)
        | IncomeDocument::Rrb1099R(_)
        | IncomeDocument::Ssa1099(_)
        | IncomeDocument::Form1099G(_)
        | IncomeDocument::Patr1099(_)
        | IncomeDocument::AlimonyReceived(_)
        | IncomeDocument::Refund1099G(_)
        | IncomeDocument::Royalties(_)
        | IncomeDocument::EquipmentRental(_)
        | IncomeDocument::Form1099Nec(_)
        | IncomeDocument::Form1099Misc(_)
        | IncomeDocument::Form1099K(_)
        | IncomeDocument::W2g(_)
        | IncomeDocument::GamblingLosses(_)
        | IncomeDocument::Form8919(_)
        | IncomeDocument::HealthLoanRepayment(_)
        | IncomeDocument::Scholarship(_)
        | IncomeDocument::JuryPay(_)
        | IncomeDocument::HobbySales(_)
        | IncomeDocument::WildfireRelief(_)
        | IncomeDocument::DisasterRelief(_)
        | IncomeDocument::CasualtyLivingInsurance(_)
        | IncomeDocument::DisasterMitigation(_) => alloc::string::String::new(),
        adjustment_kinds!() | data_answer_kinds!() => {
            unreachable!("Form 8606, QCD gifts and the data answers are not income entries")
        }
    };
    FederalIncomeEntry {
        id: item.id,
        label,
        owner: item.owner,
        income,
        state_source,
        community: item.community,
        refund_management: item.refund_management,
    }
}

// One stored record onto its page row; None for a record the page cannot show.
// `farm_se` lists the owners whose farm optional method is stored, for the
// farm kind (T2-45p).
pub(crate) fn document_item(
    entry: &FederalIncomeEntry,
    farm_se: &[Owner],
    separate: bool,
) -> Option<IncomeDocumentItem> {
    let payer = || entry.label.clone();
    let mut document = match &entry.income {
        FederalIncome::Wage { data } => IncomeDocument::W2(W2 {
            state_details: Default::default(),
            wages: data.wages,
            withholding: data.withholding,
            social_wages: data.social_wages,
            social_tax: data.social_tax,
            medicare_wages: data.medicare_wages,
            medicare_tax: data.medicare_tax,
            more: W2More {
                social_tips: data.social_tips,
                allocated_tips: unreported_tips_item(&data.employee_tips).0,
                care_benefits: data.care_benefits,
                box12: box12_items(data),
                statutory: data.statutory_employee,
                retirement_plan: data.retirement_plan,
                payroll: data.payroll.clone(),
            },
            answers: w2_answers(data),
        }),
        FederalIncome::Interest { data } if data.seller_mortgage.is_some() => {
            IncomeDocument::SellerMortgageInterest(crate::SellerMortgageInterest {
                buyer: data.seller_mortgage.clone().unwrap(),
                interest: data.taxable,
            })
        }
        FederalIncome::Interest { data } => IncomeDocument::Int1099(interest_page(
            data,
            &crate::federal_model::ChildStatementKept {
                payer: payer(),
                state_details: Default::default(),
            },
        )),
        FederalIncome::Dividend { data } => IncomeDocument::Div1099(dividend_page(
            data,
            &crate::federal_model::ChildStatementKept {
                payer: payer(),
                state_details: Default::default(),
            },
        )),
        FederalIncome::Oid { data } => IncomeDocument::Oid1099(oid_page(
            data,
            &crate::federal_model::ChildStatementKept {
                payer: payer(),
                state_details: Default::default(),
            },
        )),
        FederalIncome::ChildElection { data } => {
            IncomeDocument::Form8814(crate::Form8814::from_record(data))
        }
        FederalIncome::Sale { data } => IncomeDocument::Sale1099B(sale_item(data, &entry.label)),
        FederalIncome::OpportunityFund { data } => IncomeDocument::OpportunityFund(data.clone()),
        FederalIncome::OpportunityFundDeferral { data } => {
            IncomeDocument::OpportunityFundDeferral(data.clone())
        }
        FederalIncome::Section1256 { data } => {
            IncomeDocument::Contracts1099B(contracts_item(data, payer()))
        }
        FederalIncome::IsoSale { data } => {
            IncomeDocument::IsoShareSale(crate::IsoShareSale::from_record(&entry.label, data)?)
        }
        FederalIncome::EmployeeStockSale { data } => IncomeDocument::EmployeeShareSale(
            crate::EmployeeShareSale::from_record(&entry.label, data),
        ),
        FederalIncome::EsppSale { data } => {
            IncomeDocument::EsppShareSale(crate::EsppShareSale::from_record(&entry.label, data)?)
        }
        FederalIncome::NuaSale { data } => {
            IncomeDocument::NuaShareSale(crate::NuaShareSale::from_record(&entry.label, data))
        }
        FederalIncome::QualifiedSmallBusinessSale { data } => {
            IncomeDocument::QsbsSale(crate::QsbsSale::from_record(data))
        }
        FederalIncome::SmallBusinessStock { data } => {
            IncomeDocument::SmallBusinessStockLoss(data.clone())
        }
        FederalIncome::WorthlessSecurity { data } => {
            IncomeDocument::WorthlessSecurity(data.clone())
        }
        FederalIncome::NonbusinessBadDebt { data } => IncomeDocument::BadDebt(data.clone()),
        FederalIncome::ReturnOfCapital { kind, amount, property, basis, term, special } => {
            IncomeDocument::CapitalReturn1099Div(crate::CapitalReturn1099Div {
                payer: payer(),
                kind: *kind,
                amount: *amount,
                property: property.clone(),
                basis: *basis,
                term: *term,
                special: *special,
            })
        }
        FederalIncome::UndistributedGain { data } => IncomeDocument::Form2439(crate::Form2439 {
            fund: payer(),
            gain: data.gain,
            unrecaptured: data.unrecaptured,
            small_business: data.small_business,
            section_1202_exclusion: data.section_1202_exclusion,
            collectibles: data.collectibles,
            tax_paid: data.tax_paid,
            special: data.special,
        }),
        FederalIncome::HomeSale { data } => {
            IncomeDocument::MainHomeSale(crate::MainHomeSale::from_record(&entry.label, data)?)
        }
        FederalIncome::SavingsBonds { data } => {
            IncomeDocument::SavingsBonds(savings_bonds_item(data))
        }
        FederalIncome::EducationDistribution { data } => IncomeDocument::Q1099(q1099_item(data)),
        FederalIncome::EducationAccountExpenses { data } => {
            IncomeDocument::EducationAccountExpenses(education_expenses_item(data))
        }
        FederalIncome::Retirement { data }
            if matches!(data.taxable, crate::RetirementTaxable::Railroad { .. }) =>
        {
            IncomeDocument::Rrb1099R(rrb_item(data)?)
        }
        FederalIncome::Retirement { data } => IncomeDocument::R1099(retirement_item(data)),
        FederalIncome::Roth { data } => IncomeDocument::R1099(roth_item(data)),
        FederalIncome::TrumpDeath { .. } | FederalIncome::TrumpAbleRollover { .. } => {
            IncomeDocument::R1099(trump_item(&entry.income)?)
        }
        FederalIncome::InheritedIra { data } => IncomeDocument::InheritedIra(data.account()),
        FederalIncome::MedicalDistribution { data } => IncomeDocument::Sa1099(data.page()),
        FederalIncome::LtcBenefits { data } => IncomeDocument::Ltc1099(data.page()),
        FederalIncome::LtcInsured { data } => IncomeDocument::LtcInsured(data.page()),
        FederalIncome::Able { data } => IncomeDocument::Qa1099(data.page()),
        FederalIncome::SocialSecurity { data } if !data.special_treatment => {
            IncomeDocument::Ssa1099(ssa_item(data))
        }
        FederalIncome::Unemployment { data } => IncomeDocument::Form1099G(unemployment_item(data)),
        FederalIncome::Cooperative { data } => IncomeDocument::Patr1099(cooperative_item(data)),
        FederalIncome::EstateTrustPortfolio { data } => {
            IncomeDocument::K1EstateTrust(K1EstateTrust::from_record(&entry.label, data)?)
        }
        FederalIncome::PartnershipActivities { data } => {
            IncomeDocument::K1PartnershipActivities(alloc::boxed::Box::new(
                crate::K1PartnershipActivitiesPage::from_record(&entry.label, data),
            ))
        }
        FederalIncome::ScorpActivities { data } => IncomeDocument::K1ScorpActivities(
            crate::K1ScorpActivitiesPage::from_record(&entry.label, data),
        ),
        FederalIncome::Scorp { data } => {
            IncomeDocument::K1Scorp(K1Scorp::from_record(&entry.label, data)?)
        }
        FederalIncome::Partnership { data } => {
            IncomeDocument::K1Partnership(K1Partnership::from_record(&entry.label, data)?)
        }
        FederalIncome::PersonalDebt { data } => {
            IncomeDocument::Cancel1099C(Cancel1099C::from_record(&entry.label, data)?)
        }
        FederalIncome::PropertyAcquisition { data } => {
            IncomeDocument::Acquisition1099A(Acquisition1099A::from_record(&entry.label, data))
        }
        FederalIncome::Alimony { data } => IncomeDocument::AlimonyReceived(data.clone()),
        FederalIncome::ForeignEmployment { data } => {
            IncomeDocument::ForeignPay(crate::ForeignPay {
                employer: entry.label.clone(),
                wages: data.wages,
            })
        }
        FederalIncome::EmployeeWages { data } => IncomeDocument::Form8919(data.clone()),
        FederalIncome::HealthLoanAssistance { data } => {
            IncomeDocument::HealthLoanRepayment(data.clone())
        }
        FederalIncome::Scholarship { data } => IncomeDocument::Scholarship(data.clone()),
        FederalIncome::JuryDuty { data } => IncomeDocument::JuryPay(data.clone()),
        FederalIncome::HobbySales { data } => IncomeDocument::HobbySales(data.clone()),
        FederalIncome::WildfireRelief { data } => IncomeDocument::WildfireRelief(data.clone()),
        FederalIncome::DisasterRelief { data } => IncomeDocument::DisasterRelief(data.clone()),
        FederalIncome::CasualtyLivingInsurance { data } => {
            IncomeDocument::CasualtyLivingInsurance(data.clone())
        }
        FederalIncome::DisasterMitigation { data } => {
            IncomeDocument::DisasterMitigation(data.clone())
        }
        FederalIncome::TaxRefund { amount, history, withholding } => {
            let (year, deducted) = refund_deduction(history);
            IncomeDocument::Refund1099G(Refund1099G {
                state_details: Default::default(),
                amount: *amount,
                year,
                withholding: *withholding,
                deducted,
            })
        }
        FederalIncome::OtherIncome { data } => IncomeDocument::OtherIncome(data.clone()),
        FederalIncome::Nec1099 { data } => IncomeDocument::Form1099Nec(data.page()),
        FederalIncome::Misc1099 { data } => IncomeDocument::Form1099Misc(data.page()),
        FederalIncome::K1099 { data } => IncomeDocument::Form1099K(data.page()),
        FederalIncome::Royalty { data } => IncomeDocument::Royalties(RoyaltyProperty {
            kind: data.kind.clone(),
            receipts: data.receipts,
            advance: data.advance,
            expenses: rental_expense_items(&data.expenses),
            depletion: data.depletion.clone(),
            special: !data.ordinary,
        }),
        FederalIncome::NonbusinessProperty {
            kind:
                NonbusinessPropertyKind::PersonalRental { basis, depreciable_basis, assets, history },
            receipts,
            expenses,
            ..
        } => IncomeDocument::EquipmentRental(EquipmentRent {
            receipts: *receipts,
            expenses: *expenses,
            basis: *basis,
            depreciable_basis: *depreciable_basis,
            assets: assets.iter().map(asset_item).collect(),
            history: *history,
        }),
        FederalIncome::Business { data }
            if matches!(data.activity, BusinessActivity::Farming { .. }) =>
        {
            IncomeDocument::Farm(crate::farm_page::farm_item(
                &entry.label,
                data,
                farm_se.contains(&entry.owner),
            )?)
        }
        FederalIncome::Business { data } => {
            IncomeDocument::Business(business_item(&entry.label, data)?)
        }
        FederalIncome::Rental { data } => IncomeDocument::Rental(rental_item(&entry.label, data)?),
        FederalIncome::FarmRental { data } => {
            IncomeDocument::FarmRental(crate::farm_page::farm_rental_item(&entry.label, data)?)
        }
        // The losses kind is the record kept without a W-2G; any other
        // gambling record without losses is a W-2G (C6). A record the page
        // could not have written (a W-2G with losses, losses with
        // withholding) is not shown.
        FederalIncome::Gambling { data } if data.own_records => {
            if data.withholding != 0 {
                return None;
            }
            IncomeDocument::GamblingLosses(GamblingLosses {
                other_winnings: data.winnings,
                losses: data.losses,
                special: !data.ordinary,
            })
        }
        FederalIncome::Gambling { data } if data.losses == 0 => IncomeDocument::W2g(W2g {
            state_details: Default::default(),
            winnings: data.winnings,
            withholding: data.withholding,
            special: !data.ordinary,
        }),
        _ => return None,
    };
    if let Some(source) = &entry.state_source
        && !source.apply(&mut document)
    {
        return None;
    }
    // A business shows no amount: its profit depends on the whole return.
    // A farm's line 34 is filled from the calculation by topic_page.
    let preview = match document {
        IncomeDocument::Business(_) | IncomeDocument::Farm(_) => None,
        _ => document_amount(&entry.income, separate),
    };
    Some(IncomeDocumentItem {
        refund_management: entry.refund_management,
        refund_management_needed: None,
        allowed_community: Vec::new(),
        investment_caps: None,
        id: entry.id,
        owner: entry.owner,
        preview,
        document,
        community: entry.community,
    })
}

// The people page is a projection of the stored dependent records: the stored
// record keeps the page's situation and the "Does any of these apply" fold
// (PersonFacts: citizenship, a joint return, a competing claim, the Form 8332
// release, the Form 2120 agreement, the marital status and the person's own
// support) as chosen, and family() reads both through FederalDependent's
// accessors (M3-P15).
// The page's client rules repeated on save and in the running estimate (the
// server twins); DEPENDENT_OLDER_THAN_YOU alone is server-only because it
// compares with the filers' birth dates, which this page does not hold:
// `filers` are the birth dates of you and, on a joint return, your spouse.
fn dependent_issue(
    person: &Dependent,
    filers: &[u32],
    alive: Option<u32>,
) -> Option<ValidationIssue> {
    let born = person.birth_date;
    // The birthday rule (Rev. Rul. 2003-72, sections 24, 32 and 151).
    let year_end_age =
        crate::federal_model::birthday_age_at_close_or_death(born, person.death_date);
    let fact = |flag: PersonFacts| person.facts & flag.0 != 0;
    let (you_released, released_to_you, multiple_support) = (
        fact(PersonFacts::YOU_RELEASED),
        fact(PersonFacts::RELEASED_TO_YOU),
        fact(PersonFacts::MULTIPLE_SUPPORT),
    );
    if fact(PersonFacts::ADOPTED_US_CITIZEN_PARENT) && person.relationship != Relationship::Child {
        return Some(
            ValidationIssue::new("MEDICAL_ADOPTED_CHILD_RELATIONSHIP").at_field("relationship"),
        );
    }
    if fact(PersonFacts::MEDICAL_SEPARATED_PARENTS)
        && (person.relationship != Relationship::Child
            || fact(PersonFacts::OWN_SUPPORT)
            || multiple_support)
    {
        return Some(
            ValidationIssue::new("MEDICAL_PARENT_SUPPORT_FACTS_CONFLICT").at_field("facts"),
        );
    }
    let supported_without_support = matches!(
        person.situation,
        DependentSituation::Supported { your_support_over_half: false, .. }
    );
    // IRC 152(d)(3), 152(e): another person you support needs your support,
    // the agreement, or the other parent's release (the support test is
    // waived by either).
    if person.use_for == crate::PersonUse::TaxDependent
        && supported_without_support
        && !multiple_support
        && !released_to_you
    {
        return Some(
            ValidationIssue::new("SUPPORTED_NEEDS_YOUR_SUPPORT")
                .at_field("your_support_over_half")
                .in_field("situation"),
        );
    }
    if you_released && released_to_you {
        return Some(ValidationIssue::new("CUSTODY_RELEASE_ONE_WAY").at_field("facts"));
    }
    if (you_released || released_to_you) && person.relationship != Relationship::Child {
        return Some(
            ValidationIssue::new("CUSTODY_RELEASE_NEEDS_YOUR_CHILD").at_field("relationship"),
        );
    }
    // IRC 152(e)(4): the release goes to the parent the child lived with for
    // fewer nights, so more than six months in your home cannot be released to you.
    if released_to_you
        && !matches!(person.lived, LivedWithYou::PartOfYear { months } if months <= 6)
        && !matches!(person.lived, LivedWithYou::Days { days } if days * 2 <= alive.unwrap_or(365))
    {
        return Some(
            ValidationIssue::new("CUSTODY_RELEASE_TO_YOU_NEEDS_FEWER_NIGHTS").at_field("lived"),
        );
    }
    if multiple_support && !supported_without_support {
        return Some(
            ValidationIssue::new("MULTIPLE_SUPPORT_NEEDS_SHARED_SUPPORT").at_field("situation"),
        );
    }
    // IRC 152(c)(1)(D), (d)(1)(C), (e)(1)(A): a person who paid more than half
    // of their own support cannot also be supported mostly by you, by the
    // parents who release the claim, or by several supporters together.
    let own_support = fact(PersonFacts::OWN_SUPPORT);
    if own_support
        && matches!(
            person.situation,
            DependentSituation::Supported { your_support_over_half: true, .. }
        )
    {
        return Some(ValidationIssue::new("OWN_SUPPORT_NOT_WITH_YOUR_SUPPORT").at_field("facts"));
    }
    if own_support && (multiple_support || you_released || released_to_you) {
        return Some(ValidationIssue::new("OWN_SUPPORT_NOT_WITH_SHARED_SUPPORT").at_field("facts"));
    }
    // IRC 152(e)(5): a multiple support agreement and a release exclude each other.
    if multiple_support && (you_released || released_to_you) {
        return Some(
            ValidationIssue::new("MULTIPLE_SUPPORT_NOT_WITH_CUSTODY_RELEASE").at_field("facts"),
        );
    }
    match person.situation {
        // IRC 152(c)(3): under 19, or under 24 and a student, at the close of
        // 2026; a child attains an age on the birthday (a child born January 1,
        // 2008 is 18 on December 31, 2026 and 19 on January 1, 2027).
        DependentSituation::ChildUnder19 if year_end_age >= 19 => {
            return Some(ValidationIssue::new("DEPENDENT_AGE_SITUATION").at_field("situation"));
        }
        DependentSituation::Student if year_end_age >= 24 => {
            return Some(ValidationIssue::new("DEPENDENT_AGE_SITUATION").at_field("situation"));
        }
        DependentSituation::ChildUnder19 | DependentSituation::Student
            if !filers.is_empty() && filers.iter().all(|filer| born <= *filer) =>
        {
            return Some(ValidationIssue::new("DEPENDENT_OLDER_THAN_YOU").at_field("birth_date"));
        }
        _ => {}
    }
    // IRC 21(b)(1)(A), as family() tests it: care counts when the person is
    // under 13 on at least one 2026 day (tested on January 1, on the birthday).
    if matches!(person.care, CareCosts::Yes { incapable_self_care: false, .. })
        && crate::federal_model::attained_on(born, 13, false, 20260101)
    {
        return Some(
            ValidationIssue::new("CARE_NEEDS_UNDER_13_OR_SELF_CARE")
                .at_field("incapable_self_care")
                .in_field("care"),
        );
    }
    // The adopted-child exception is your own child living with you all year.
    if fact(PersonFacts::ADOPTED_ALL_YEAR)
        && !(person.relationship == Relationship::Child && person.lived == LivedWithYou::AllYear)
    {
        return Some(ValidationIssue::new("ADOPTED_NEEDS_CHILD_ALL_YEAR").at_field("facts"));
    }
    // The born-and-died fact belongs to a child born in 2026.
    if fact(PersonFacts::BORN_AND_DIED) && born / 10000 != 2026 {
        return Some(ValidationIssue::new("BORN_AND_DIED_NEEDS_2026_BIRTH").at_field("birth_date"));
    }
    if person.death_date.is_some_and(|died| died < born) {
        return Some(ValidationIssue::new("DEATH_BEFORE_BIRTH").at_field("death_date"));
    }
    // A child born and died in 2026 has no SSN to show it: the date does.
    if fact(PersonFacts::BORN_AND_DIED) && person.death_date.is_none() {
        return Some(ValidationIssue::new("BORN_AND_DIED_NEEDS_DEATH_DATE").at_field("death_date"));
    }
    // IRC 152(d)(1)(D): only another person you support can be another
    // taxpayer's qualifying child instead of your qualifying relative.
    (fact(PersonFacts::ANOTHERS_QUALIFYING_CHILD)
        && !matches!(person.situation, DependentSituation::Supported { .. }))
    .then_some(ValidationIssue::new("ANOTHERS_CHILD_NEEDS_SUPPORTED").at_field("situation"))
}
fn dependent_rule(person: &Dependent, filers: &[u32], alive: Option<u32>) -> Option<&'static str> {
    dependent_issue(person, filers, alive).map(|issue| issue.key)
}

// The filers' birth dates the people page checks its people against.
// The residence answers the Children page offers: the days through the death
// where the filer's year is shorter (the final return of a person who died,
// not joint), months otherwise. Whole-year stays an answer either way.
fn lived_index(lived: &LivedWithYou) -> i32 {
    (match lived {
        LivedWithYou::AllYear => libertas_macros::variant_index!(LivedWithYou::AllYear),
        LivedWithYou::PartOfYear { .. } => {
            libertas_macros::variant_index!(LivedWithYou::PartOfYear)
        }
        LivedWithYou::Days { .. } => libertas_macros::variant_index!(LivedWithYou::Days),
    }) as i32
}
pub(crate) fn allowed_lived(alive: Option<u32>) -> Vec<i32> {
    alloc::vec![
        libertas_macros::variant_index!(LivedWithYou::AllYear) as i32,
        if alive.is_some() {
            libertas_macros::variant_index!(LivedWithYou::Days) as i32
        } else {
            libertas_macros::variant_index!(LivedWithYou::PartOfYear) as i32
        },
    ]
}
fn filer_births(d: &FederalDraft) -> Vec<u32> {
    let people = d.people.as_ref();
    people
        .map(|p| p.taxpayer.birth_date)
        .into_iter()
        .chain(people.and_then(|p| p.spouse.as_ref()).filter(|_| joint(d)).map(|s| s.birth_date))
        .collect()
}
// The pages whose answers are their only mark (the people page and Form
// 8379's): a stored answer their own rules now refuse after an earlier
// change (a child no longer younger than you, an agreed part above the
// payments) cannot be reopened by a mark, so the review names the page with
// the rule's message (walk-owned data, level 2).
fn unmarked_refusals(d: &FederalDraft) -> Vec<(TaxSection, &'static str)> {
    let filers = filer_births(d);
    let alive = crate::federal_rules::short_year_days(d);
    let people = d
        .dependents()
        .iter()
        .filter_map(|record| dependent_item(record, alive))
        .find_map(|person| dependent_rule(&person, &filers, alive))
        .map(|key| (TaxSection::Children, key));
    let joint_estimated = crate::injured_spouse::joint_estimated(d);
    let injured = d
        .injured_spouse
        .as_ref()
        .filter(|_| injured_chosen(d))
        .and_then(|a| crate::injured_spouse::rule(&a.page(d, &estimate(d)), &joint_estimated).err())
        .map(|key| (TaxSection::InjuredSpouse, key));
    people.into_iter().chain(injured).collect()
}
// The days a person who died was alive in 2026: from the birth (or January
// 1) through the date of death.
fn days_alive_of(person: &Dependent) -> u32 {
    let first = if person.birth_date / 10000 == 2026 { person.birth_date } else { 20260101 };
    (crate::dates::days_between(first, person.death_date.unwrap_or(20261231)) + 1).max(1) as u32
}
// One page row onto its stored record.
fn federal_dependent(person: &Dependent, alive: Option<u32>) -> FederalDependent {
    let (residency, us_home_over_half_year) = match person.lived {
        // A child born, or a person who died, in 2026 is in the home for the
        // days alive (Pub. 501 "Death or birth of child").
        LivedWithYou::AllYear
            if person.birth_date / 10000 == 2026 || person.death_date.is_some() =>
        {
            (DependentResidency::WholeYearException, true)
        }
        LivedWithYou::AllYear => (DependentResidency::Days { days: 365 }, true),
        // A person who died lived in the home for more than half of the days
        // alive, not of the year (Pub. 501 "Death or birth of child").
        LivedWithYou::PartOfYear { months } if person.death_date.is_some() => (
            DependentResidency::Days { days: months * 30 },
            months * 30 * 2 > days_alive_of(person),
        ),
        LivedWithYou::PartOfYear { months } => {
            (DependentResidency::Days { days: months * 30 }, months >= 7)
        }
        // More than half of the days the filer was alive.
        LivedWithYou::Days { days } => {
            (DependentResidency::Days { days }, days * 2 > alive.unwrap_or(365))
        }
    };
    let (care, incapable_self_care) = match person.care {
        CareCosts::No => (DependentCare::No, false),
        CareCosts::Yes { expenses, incapable_self_care } => {
            (DependentCare::Yes { care_expenses: expenses }, incapable_self_care)
        }
    };
    FederalDependent {
        use_for: person.use_for,
        id: person.id,
        first_name: person.first_name.clone(),
        last_name: person.last_name.clone(),
        birth_date: person.birth_date,
        death_date: person.death_date,
        relationship: person.relationship,
        residency,
        us_home_over_half_year,
        incapable_self_care,
        care,
        valid_ssn: person.identification == Identification::SocialSecurityNumber,
        valid_tin: person.identification != Identification::NoneByDueDate,
        situation: person.situation,
        facts: person.facts,
        competing: person.competing,
    }
}

// One stored record onto its page row; None for a record the page cannot
// show, i.e. one the page's answers would not reproduce. The names reopen as
// entered.
fn dependent_item(record: &FederalDependent, alive: Option<u32>) -> Option<Dependent> {
    let lived = match record.residency {
        DependentResidency::WholeYearException => LivedWithYou::AllYear,
        DependentResidency::Days { days: 365 } => LivedWithYou::AllYear,
        // A shortened year asks days; any other year asks months.
        DependentResidency::Days { days } if alive.is_some() => LivedWithYou::Days { days },
        DependentResidency::Days { days } => LivedWithYou::PartOfYear { months: days / 30 },
    };
    let care = match record.care {
        DependentCare::No => CareCosts::No,
        DependentCare::Yes { care_expenses, .. } => CareCosts::Yes {
            expenses: care_expenses,
            incapable_self_care: record.incapable_self_care,
        },
    };
    let item = Dependent {
        use_for: record.use_for,
        id: record.id,
        first_name: record.first_name.clone(),
        last_name: record.last_name.clone(),
        birth_date: record.birth_date,
        death_date: record.death_date,
        relationship: record.relationship,
        lived,
        situation: record.situation,
        identification: if record.valid_ssn {
            Identification::SocialSecurityNumber
        } else if !record.valid_tin {
            Identification::NoneByDueDate
        } else {
            Identification::Itin
        },
        care,
        facts: record.facts,
        competing: record.competing,
    };
    (!item.first_name.is_empty()
        && !item.last_name.is_empty()
        && federal_dependent(&item, alive) == *record)
        .then_some(item)
}

// The itemized facts a route holds: Compare's and Itemize's (M3-P9); None
// for the standard deduction, whose stored `ItemizedChoice::No` holds none.
fn itemized_facts(d: &FederalDraft) -> Option<&ItemizedExpenses> {
    match d.deductions.as_ref().map(|v| &v.choice) {
        Some(
            DeductionSelection::Automatic { expenses: ItemizedChoice::Yes { facts } }
            | DeductionSelection::Itemized { facts },
        ) => Some(facts),
        _ => None,
    }
}
fn itemized_facts_mut(d: &mut FederalDraft) -> Option<&mut ItemizedExpenses> {
    match d.deductions.as_mut().map(|v| &mut v.choice) {
        Some(
            DeductionSelection::Automatic { expenses: ItemizedChoice::Yes { facts } }
            | DeductionSelection::Itemized { facts },
        ) => Some(facts),
        _ => None,
    }
}
// Any route but the standard deduction opens the itemized hub.
fn itemizing(d: &FederalDraft) -> bool {
    itemized_facts(d).is_some()
}
fn no_itemized_facts() -> ItemizedExpenses {
    ItemizedExpenses {
        investment_income_tax: crate::InvestmentIncomeTax::Unresolved,
        medical: 0,
        long_term_care: Vec::new(),
        personal_tax: PersonalTaxElection::None,
        real_estate_taxes: 0,
        other_lines: Vec::new(),
        personal_property_taxes: 0,
        investment_property_taxes: 0,
        investment_property_tax_owners: None,
        income_tax_owners: None,
    }
}
// The route a stored deduction choice reopens as. The explicit
// `DeductionSelection::Standard`, which no page writes, has none.
fn deduction_route(d: &FederalDraft) -> Option<DeductionRoute> {
    let spouse_itemizes = d.deductions.as_ref().is_some_and(|v| v.spouse_itemizes);
    match d.deductions.as_ref().map(|v| &v.choice) {
        None | Some(DeductionSelection::Automatic { expenses: ItemizedChoice::No }) => {
            Some(DeductionRoute::Standard)
        }
        Some(DeductionSelection::Automatic { .. }) => Some(DeductionRoute::Compare),
        Some(DeductionSelection::Itemized { .. }) if spouse_itemizes => {
            Some(DeductionRoute::SpouseItemizes)
        }
        Some(DeductionSelection::Itemized { .. }) => Some(DeductionRoute::Itemize),
        Some(DeductionSelection::Standard) => None,
    }
}
fn route_key(route: DeductionRoute) -> &'static str {
    match route {
        DeductionRoute::Standard => "REVIEW_ROUTE_NAME_STANDARD",
        DeductionRoute::Compare => "REVIEW_ROUTE_NAME_COMPARE",
        DeductionRoute::Itemize => "REVIEW_ROUTE_NAME_ITEMIZE",
        DeductionRoute::SpouseItemizes => "REVIEW_ROUTE_NAME_SPOUSEITEMIZES",
    }
}
// The itemized hub's topics after the route (M3-P9). A topic saved from the
// hub is recorded in `finished_sections`, so the hub suggests the first one
// not yet visited; the standard deduction clears them with the hub.
fn itemized_topic_visited(d: &FederalDraft, topic: TaxSection) -> bool {
    d.finished_sections.contains(&topic)
}
// The children whose interest and dividends the return can report on Form
// 8814, in the dependents' order: a child, adopted child or stepchild (not a
// foster child) under 19 or a full-time student under 24 at the end of 2026,
// without a joint return of their own (child_election::eligible_child).
pub(crate) fn child_election_children(d: &FederalDraft) -> Vec<&FederalDependent> {
    d.dependents().iter().filter(|c| crate::child_election::eligible_child(c)).collect()
}
// The same children as the page's read-only catalog: the stored identity is
// the key, the label the child's name as FormattedText.
fn child_election_choices(d: &FederalDraft) -> Vec<crate::ChildChoice> {
    child_election_children(d)
        .into_iter()
        .map(|c| crate::ChildChoice { id: c.id, label: c.name() })
        .collect()
}
// The people a long-term-care premium can insure: you, your spouse on a
// joint return and the people you support, each with the age at the end of
// 2026 that sets the premium limit. The catalog reuses the student type.
pub(crate) fn medical_people(d: &FederalDraft) -> Vec<(PersonChoice, u32)> {
    // IRC 213(d)(10): the age attained before the close of the year, day-exact.
    let age = |birth: u32| crate::federal_model::age_at_year_end(birth).min(120);
    crate::federal_rules::people_students(d)
        .into_iter()
        .filter_map(|person| {
            let birth = match person.id {
                -1 => d.people.as_ref()?.taxpayer.birth_date,
                -2 => d.people.as_ref()?.spouse.as_ref()?.birth_date,
                id => d.dependents().iter().find(|v| v.id == id)?.birth_date,
            };
            Some((person, age(birth)))
        })
        .collect()
}
// The age at the end of 2026 that sets a person's premium limit, by the
// person's identity (-1 you, -2 your spouse, otherwise a dependent); None for
// someone not on the return.
pub(crate) fn person_age(d: &FederalDraft, person: i64) -> Option<u32> {
    medical_people(d).into_iter().find(|(p, _)| p.id == person).map(|(_, age)| age)
}
// A stored premium as its page row: the insured person's identity, the EnumSource key.
// None when the record is not one the page writes (another person or an
// unconfirmed policy).
fn care_premium_item(
    record: &MedicalCarePremium,
    people: &[(PersonChoice, u32)],
) -> Option<CarePremium> {
    let person = people.iter().find(|(p, _)| p.id == record.person)?.0.id;
    Some(CarePremium { person, premiums: record.premiums, qualified: record.qualified.clone() })
}
// The Taxes page's SALT election onto the stored one: an income tax of zero
// is no election, so the page's default saves as `None` and reopens the same.
fn personal_tax_record(
    kind: &SaltElection,
    kept: Option<&PersonalTaxElection>,
) -> PersonalTaxElection {
    match kind {
        SaltElection::IncomeTax { paid: 0 } => PersonalTaxElection::None,
        SaltElection::IncomeTax { paid } => PersonalTaxElection::Income {
            paid: *paid,
            allocation: match kept {
                Some(PersonalTaxElection::Income { allocation, .. }) => allocation.clone(),
                _ => TaxIncomeAllocation::CurrentReturn,
            },
        },
        SaltElection::SalesTax { paid } => PersonalTaxElection::Sales { paid: *paid },
    }
}
fn salt_item(record: &PersonalTaxElection) -> SaltElection {
    match record {
        PersonalTaxElection::None => SaltElection::IncomeTax { paid: 0 },
        PersonalTaxElection::Income { paid, .. } => SaltElection::IncomeTax { paid: *paid },
        PersonalTaxElection::Sales { paid } => SaltElection::SalesTax { paid: *paid },
    }
}
// Each document keeps its identity; transferred forms share only the first
// lender's year-wide ledger. Page projection preserves every stored fact.
// Native loan metadata projects through the exact existing Form1098 conversion.
// MortgageDetails/Points/refund-origin variants are transparent in field paths.
fn mortgage_page_issue(issue: ValidationIssue) -> ValidationIssue {
    issue
        .map_field_prefix(&["outstanding_principal"], &["principal"])
        .map_field_prefix(&["incurred"], &["originated"])
        .map_field_prefix(&["details"], &["more", "details"])
        .map_field_prefix(&["refund_of_interest", "origin"], &["more", "refund_origin"])
}

fn mortgage_loan_record(page: &Mortgage1098) -> MortgageLoan {
    MortgageLoan {
        id: page.id,
        property: page.more.property.clone(),
        lender: page.more.lender.clone(),
        interest: page.interest,
        outstanding_principal: page.principal,
        incurred: page.originated,
        details: match &page.more.details {
            MortgageDetails::EarlierLender { loan } => {
                MortgageLoanDetails::EarlierLender { loan: *loan }
            }
            MortgageDetails::FirstLender(facts) => {
                MortgageLoanDetails::FirstLender(MortgageLedger {
                    home: facts.home,
                    purpose: facts.purpose.clone(),
                    average: match &facts.average {
                        AverageBalance::WithinLimit => MortgageAverageBalance::WithinLimit,
                        AverageBalance::FirstAndLast { last_balance } => {
                            MortgageAverageBalance::FirstAndLast { last_balance: *last_balance }
                        }
                        AverageBalance::InterestOverRate { rate } => {
                            MortgageAverageBalance::InterestOverRate {
                                rate_thousandths_percent: *rate,
                            }
                        }
                        AverageBalance::Statements { average } => {
                            MortgageAverageBalance::Statements { average_balance: *average }
                        }
                        AverageBalance::Monthly { balances } => {
                            MortgageAverageBalance::Monthly { balances: balances.clone() }
                        }
                    },
                })
            }
        },
        refund_of_interest: if page.refund > 0 {
            page.more.refund_origin.as_ref().map_or(MortgageInterestRefund::No, |origin| {
                MortgageInterestRefund::Yes { amount: page.refund, origin: origin.clone() }
            })
        } else {
            MortgageInterestRefund::No
        },
        mortgage_insurance_premiums: page.insurance,
        points: match &page.points {
            Points::None => MortgagePoints::No,
            Points::Purchase { amount } => MortgagePoints::Purchase { amount: *amount },
            Points::Amortized { amount, term_months, ended } => MortgagePoints::Amortized {
                amount: *amount,
                term_months: *term_months,
                ended: *ended,
            },
            Points::Improvement { amount, term_months } => {
                MortgagePoints::Improvement { amount: *amount, term_months: *term_months }
            }
        },
    }
}
fn mortgage_1098_item(loan: &MortgageLoan) -> Option<Mortgage1098> {
    let details = match &loan.details {
        MortgageLoanDetails::EarlierLender { loan } => {
            MortgageDetails::EarlierLender { loan: *loan }
        }
        MortgageLoanDetails::FirstLender(facts) => {
            MortgageDetails::FirstLender(MortgageFirstLender {
                home: facts.home,
                purpose: facts.purpose.clone(),
                average: match &facts.average {
                    MortgageAverageBalance::WithinLimit => AverageBalance::WithinLimit,
                    MortgageAverageBalance::FirstAndLast { last_balance } => {
                        AverageBalance::FirstAndLast { last_balance: *last_balance }
                    }
                    MortgageAverageBalance::InterestOverRate { rate_thousandths_percent } => {
                        AverageBalance::InterestOverRate { rate: *rate_thousandths_percent }
                    }
                    MortgageAverageBalance::Statements { average_balance } => {
                        AverageBalance::Statements { average: *average_balance }
                    }
                    MortgageAverageBalance::Monthly { balances } => {
                        AverageBalance::Monthly { balances: balances.clone() }
                    }
                },
            })
        }
    };
    let points = match &loan.points {
        MortgagePoints::No => Points::None,
        MortgagePoints::Purchase { amount } => Points::Purchase { amount: *amount },
        MortgagePoints::Amortized { amount, term_months, ended } => {
            Points::Amortized { amount: *amount, term_months: *term_months, ended: *ended }
        }
        MortgagePoints::Improvement { amount, term_months } => {
            Points::Improvement { amount: *amount, term_months: *term_months }
        }
    };
    let (refund, refund_origin) = match &loan.refund_of_interest {
        MortgageInterestRefund::No => (0, None),
        MortgageInterestRefund::Yes { amount, origin } => (*amount, Some(origin.clone())),
    };
    Some(Mortgage1098 {
        id: loan.id,
        interest: loan.interest,
        principal: loan.outstanding_principal,
        originated: loan.incurred,
        insurance: loan.mortgage_insurance_premiums,
        refund,
        points,
        more: MortgageMore {
            property: loan.property.clone(),
            refund_origin,
            lender: loan.lender.clone(),
            details,
        },
    })
}
fn mortgage_average_balance_needed(loans: &[Mortgage1098], separate: bool) -> bool {
    let loans: Vec<_> = loans
        .iter()
        .filter_map(|loan| {
            let MortgageDetails::FirstLender(facts) = &loan.more.details else {
                return None;
            };
            (facts.home != MortgageHome::NotQualified
                && !matches!(facts.purpose, MortgageUse::Other))
            .then_some((loan, facts))
        })
        .collect();
    if !loans.iter().any(|(_, f)| f.average == AverageBalance::WithinLimit) {
        return false;
    }
    let all_earlier = loans.iter().all(|(l, f)| match &f.purpose {
        MortgageUse::Home => {
            l.originated <= crate::year_constants::MORTGAGE_EARLIER_LIMIT_LAST_DATE
        }
        MortgageUse::Partly(p) => {
            p.improvement_incurred <= crate::year_constants::MORTGAGE_EARLIER_LIMIT_LAST_DATE
        }
        MortgageUse::Refinance(r) => {
            r.earlier_incurred <= crate::year_constants::MORTGAGE_EARLIER_LIMIT_LAST_DATE
                && (l.originated <= crate::year_constants::MORTGAGE_EARLIER_LIMIT_LAST_DATE
                    || r.earlier_term_ends
                        .is_some_and(|end| end >= crate::year_constants::TAX_YEAR_END_DATE))
                && (r.improvement == 0
                    || l.originated <= crate::year_constants::MORTGAGE_EARLIER_LIMIT_LAST_DATE)
        }
        MortgageUse::Other => true,
    });
    let limit = match (all_earlier, separate) {
        (true, true) => crate::year_constants::MORTGAGE_DEBT_LIMIT_GRANDFATHERED_SEPARATE_CENTS,
        (true, false) => crate::year_constants::MORTGAGE_DEBT_LIMIT_GRANDFATHERED_CENTS,
        (false, true) => crate::year_constants::MORTGAGE_DEBT_LIMIT_SEPARATE_CENTS,
        (false, false) => crate::year_constants::MORTGAGE_DEBT_LIMIT_CENTS,
    };
    // Arithmetic safety: any Vec<i64> admitted on a 32/64-bit target has an
    // exactly representable i128 sum; compare the statutory debt limit in that unit.
    loans.iter().map(|(loan, _)| i128::from(loan.principal)).sum::<i128>() > i128::from(limit)
}
fn mortgage_available(d: &FederalDraft) -> bool {
    d.deductions.is_some()
}
fn mortgage_parent(d: &FederalDraft) -> i32 {
    if itemizing(d) { ITEMIZED_PAGE } else { DEDUCTIONS_PAGE }
}
// Shared source facts are edited and retained directly; tax-specific appraisal
// placement and validation have one owner in charity.rs.
fn gift_issue(value: &GiftCarryovers) -> Option<ValidationIssue> {
    crate::charity::page_issue(
        &value.gifts.iter().map(crate::PropertyGiftPage::stored).collect::<Vec<_>>(),
        &value.appraisals,
        &value.carryovers.iter().cloned().map(Into::into).collect::<Vec<_>>(),
        value.basis_election,
    )
}
fn appraisal_catalog(values: &[crate::Appraisal]) -> Vec<crate::RecordChoice> {
    values
        .iter()
        .map(|a| crate::RecordChoice {
            id: a.id,
            label: crate::Message::new(
                "GIFT_APPRAISAL_CHOICE",
                alloc::vec![
                    crate::MessageArg::Text(a.appraiser.clone()),
                    crate::MessageArg::DateOnly(i64::from(a.report_date))
                ],
            )
            .encode(),
        })
        .collect()
}
// The deductions page's repayment answers: the comparison only while the
// income entries record more than $3,000 of earlier-year repayments.
fn allowed_repayment(d: &FederalDraft) -> Vec<i32> {
    let mut allowed = alloc::vec![libertas_macros::variant_index!(RepaymentClaim::None) as i32];
    if crate::claim_repayment::repayment_offered(d) {
        allowed.push(libertas_macros::variant_index!(RepaymentClaim::Claim) as i32);
    }
    allowed
}
fn repayment_index(claim: &RepaymentClaim) -> i32 {
    (match claim {
        RepaymentClaim::None => libertas_macros::variant_index!(RepaymentClaim::None),
        RepaymentClaim::Claim { .. } => libertas_macros::variant_index!(RepaymentClaim::Claim),
    }) as i32
}
// The server twins of the deductions page's client rules (T3-deduct), in
// the client's order, then the records' own checks by name.
fn deductions_rule(d: &FederalDraft, value: &Deductions) -> Result<(), SaveFailure> {
    if let Some((index, _)) =
        value.car_loans.iter().enumerate().find(|(_, v)| v.business > v.interest)
    {
        return Err(ValidationIssue::new("VEHICLE_BUSINESS_ABOVE_INTEREST")
            .at_field("business")
            .in_list("car_loans", index)
            .in_field("value")
            .into());
    }
    if value.car_loans.iter().any(|v| v.label.trim().is_empty()) {
        return Err(crate::interview::status(
            "MESSAGE_NAME_EACH_VEHICLE_LOAN_S_LENDER_UP_TO_80_CHARACTERS",
        )
        .into());
    }
    let events = &value.casualties;
    for (event_index, event) in events.iter().enumerate() {
        if let Some((property_index, _)) =
            event.properties.iter().enumerate().find(|(_, p)| p.after > p.before)
        {
            return Err(ValidationIssue::new("CASUALTY_AFTER_ABOVE_BEFORE")
                .at_field("after")
                .in_list("properties", property_index)
                .in_list("casualties", event_index)
                .in_field("value")
                .into());
        }
        if let Some((property_index, _)) =
            event.properties.iter().enumerate().find(|(_, p)| p.received > p.reimbursement)
        {
            return Err(ValidationIssue::new("CASUALTY_RECEIVED_ABOVE_REIMBURSEMENT")
                .at_field("received")
                .in_list("properties", property_index)
                .in_list("casualties", event_index)
                .in_field("value")
                .into());
        }
        let declared = !matches!(event.declaration, CasualtyDeclaration::Undeclared);
        // External format: a declared disaster area uses a five-digit ZIP code.
        if declared != (event.zip.len() == 5) || (!declared && !event.zip.is_empty()) {
            return Err(ValidationIssue::new("CASUALTY_ZIP")
                .at_field("zip")
                .in_list("casualties", event_index)
                .in_field("value")
                .into());
        }
        if !PersonalCasualty::from(event.clone()).valid() {
            return Err(libertas_formatted_text(
                "MESSAGE_CHECK_CASUALTY_EVENT_FACTS",
                &[LibertasMessageArgument::LiteralText(&event.label)],
            )
            .into());
        }
    }
    if !allowed_repayment(d).contains(&repayment_index(&value.repayment)) {
        return Err(ValidationIssue::new(
            "MESSAGE_THE_REPAYMENT_COMPARISON_IS_ASKED_ONLY_WHEN_YOUR_INCOME_ENTRIES_RECORD_MORE",
        )
        .at_field("repayment")
        .in_field("value")
        .into());
    }
    if let Some(issue) = value.repayment.issue() {
        return Err(issue.in_field("repayment").in_field("value").into());
    }
    Ok(())
}
// The gift page's less common rows (T3-deduct), as stored.
struct LessCommonGifts {
    hosted_students: Vec<crate::HostedStudent>,
    whaling_captains: Vec<crate::WhalingCaptainClaim>,
}
fn less_common_gifts(rows: &[LessCommonGift]) -> LessCommonGifts {
    let mut out = LessCommonGifts { hosted_students: Vec::new(), whaling_captains: Vec::new() };
    for row in rows {
        match row {
            LessCommonGift::HostedStudent(student) => out.hosted_students.push(student.clone()),
            LessCommonGift::WhalingCaptain(c) => {
                out.whaling_captains.push(crate::WhalingCaptainClaim {
                    owner: c.owner,
                    captain_record_reference: c.captain_record_reference.clone(),
                    aewc_report_reference: c.aewc_report_reference.clone(),
                    trip_log_reference: c.trip_log_reference.clone(),
                    expenses: c.expenses.clone(),
                    eligibility_and_records_confirmed: c.eligibility_and_records_confirmed,
                })
            }
        }
    }
    out
}
fn less_common_rows(ded: &FederalDeductions) -> Vec<LessCommonGift> {
    let mut rows: Vec<LessCommonGift> =
        ded.hosted_students.iter().cloned().map(LessCommonGift::HostedStudent).collect();
    rows.extend(ded.whaling_captains.iter().map(|c| {
        LessCommonGift::WhalingCaptain(WhalingCaptain {
            owner: c.owner,
            captain_record_reference: c.captain_record_reference.clone(),
            aewc_report_reference: c.aewc_report_reference.clone(),
            trip_log_reference: c.trip_log_reference.clone(),
            expenses: c.expenses.clone(),
            eligibility_and_records_confirmed: c.eligibility_and_records_confirmed,
        })
    }));
    rows
}
// Source owners return local fields; retain the submitted mixed-list indices.
fn less_common_issue(value: &GiftCarryovers, owners: &[i32]) -> Option<ValidationIssue> {
    let rows = &value.less_common;
    let gifts = less_common_gifts(rows);
    let captains: Vec<_> = rows
        .iter()
        .enumerate()
        .filter_map(|(index, row)| match row {
            LessCommonGift::WhalingCaptain(captain) => Some((index, captain)),
            _ => None,
        })
        .collect();
    let students: Vec<_> = rows
        .iter()
        .enumerate()
        .filter_map(|(index, row)| match row {
            LessCommonGift::HostedStudent(student) => Some((index, student)),
            _ => None,
        })
        .collect();
    for (position, (index, captain)) in captains.iter().enumerate() {
        if captains[..position].iter().any(|(_, prior)| prior.owner == captain.owner) {
            return Some(
                ValidationIssue::new("WHALING_CAPTAIN_TWICE")
                    .at_field("owner")
                    .in_list("less_common", *index),
            );
        }
    }
    for (position, (index, student)) in students.iter().enumerate() {
        if students[..position].iter().any(|(_, prior)| prior.label == student.label) {
            return Some(
                ValidationIssue::new("HOSTED_STUDENT_TWICE")
                    .at_field("label")
                    .in_list("less_common", *index),
            );
        }
    }
    for (index, captain) in &captains {
        if !owners.contains(&(captain.owner as i32)) {
            return Some(
                ValidationIssue::new(
                    "MESSAGE_A_WHALING_CAPTAIN_MUST_BE_YOU_OR_YOUR_SPOUSE_ON_A_JOINT_RETURN",
                )
                .at_field("owner")
                .in_list("less_common", *index),
            );
        }
    }
    for (index, volunteer) in value.volunteer.iter().enumerate() {
        if let Some(issue) = volunteer.issue() {
            return Some(issue.in_list("volunteer", index));
        }
    }
    for (index, student) in &students {
        if let Some(issue) = student.issue() {
            return Some(issue.in_list("less_common", *index));
        }
    }
    for ((index, _), captain) in captains.iter().zip(&gifts.whaling_captains) {
        if let Some(issue) = captain.issue() {
            return Some(issue.in_list("less_common", *index));
        }
    }
    None
}
// The retirement income an unrecovered annuity cost can belong to: each
// non-IRA retirement entry of a filer who died (the other itemized page's
// catalog, T3-deduct).
fn annuity_contracts(d: &FederalDraft) -> Vec<AnnuityContract> {
    let Some(people) = d.people.as_ref() else {
        return Vec::new();
    };
    d.income
        .iter()
        .filter(|e| {
            people.person(e.owner).is_some_and(|p| p.death_date().is_some())
                && matches!(&e.income, FederalIncome::Retirement { data } if !data.kind.ira())
        })
        .map(|e| AnnuityContract { id: e.id, label: income_issue_context(e).label().encode() })
        .collect()
}
// The amounts each itemized topic holds, for its hub row. Charity
// carryovers live on FederalDeductions directly (M3-P10), not in the route's
// ItemizedExpenses, so this reads the draft too.
// The gambling losses entered on the income topic, before any limit: the
// itemized hub's derived row (C7), which also opens the deductions page on
// Compare as an itemizable tick does.
fn gambling_losses(d: &FederalDraft) -> i64 {
    d.income
        .iter()
        .map(|e| match &e.income {
            FederalIncome::Gambling { data } => data.losses,
            _ => 0,
        })
        .sum()
}
fn itemized_topic_present(d: &FederalDraft, facts: &ItemizedExpenses, topic: TaxSection) -> bool {
    if topic == TaxSection::Medical {
        facts.medical != 0 || facts.long_term_care.iter().any(|premium| premium.premiums != 0)
    } else {
        itemized_topic_amount(d, facts, topic) != 0
    }
}
fn itemized_topic_amount(d: &FederalDraft, facts: &ItemizedExpenses, topic: TaxSection) -> i64 {
    match topic {
        TaxSection::Taxes => {
            facts.personal_tax.paid() + facts.real_estate_taxes + facts.personal_property_taxes
        }
        TaxSection::Mortgage => {
            d.deductions.as_ref().map_or(0, |v| v.mortgage_loans().iter().map(|l| l.interest).sum())
        }
        TaxSection::GiftCarryovers => d.deductions.as_ref().map_or(0, |v| {
            v.volunteer_expenses.iter().map(crate::VolunteerExpense::cents).sum::<i64>()
                + v.hosted_students.iter().map(crate::HostedStudent::allowed).sum::<i64>()
                + v.whaling_captains
                    .iter()
                    .map(crate::WhalingCaptainClaim::statutory_claim_cents)
                    .sum::<i64>()
                + v.charity_carryovers.iter().map(|c| c.balance).sum::<i64>()
                + v.property_gifts.iter().map(|g| g.claim(v.basis_election).1).sum::<i64>()
        }),
        TaxSection::OtherItemized => {
            d.deductions
                .as_ref()
                .and_then(FederalDeductions::investment_interest)
                .map_or(0, |v| v.paid + v.carryover)
                + facts.investment_property_taxes
        }
        _ => 0,
    }
}

// The people an education credit can be for: you, your spouse on a joint
// return and the people you support, the medical page's catalog without ages.
fn education_people(d: &FederalDraft) -> Vec<PersonChoice> {
    medical_people(d).into_iter().map(|(p, _)| p).collect()
}
// The credit is derived, not chosen: the American opportunity credit for an
// undergraduate at least half-time who has not used it up, else the
// lifetime learning credit. The American opportunity credit is never smaller
// for the same student, so the choice has one right answer.
fn education_method(value: &StudentCredit) -> EducationChoice {
    let used_up = value.more.american_opportunity_used_up;
    if value.half_time && !value.graduate && !used_up {
        EducationChoice::AmericanOpportunity
    } else {
        EducationChoice::LifetimeLearning
    }
}
fn education_record(value: &StudentCredit) -> FederalEducation {
    let StudentMore {
        books_from_school: school_materials,
        other_books: other_materials,
        refunds,
        tax_free_529: other_benefits,
        ..
    } = value.more;
    FederalEducation {
        student: value.student,
        method: education_method(value),
        expenses: FederalEducationExpenses {
            tuition: value.tuition,
            school_materials,
            other_materials,
            assistance: value.scholarships,
            refunds,
            other_benefits,
            scholarship_in_income: value.more.scholarship_in_income.clone(),
        },
    }
}
// A stored education row as its page row, the student by identity.
// The 1098-T boxes 8 and 9 and the "used up" answer are not stored, only the
// credit they decide: an American opportunity row reopens as half-time
// undergraduate, a lifetime learning row as a half-time graduate student.
// None for a row this page does not write (a student outside the catalog).
fn student_credit_item(
    record: &FederalEducation,
    people: &[PersonChoice],
) -> Option<StudentCredit> {
    let student = people.iter().find(|p| p.id == record.student)?.id;
    let graduate = match record.method {
        EducationChoice::AmericanOpportunity => false,
        EducationChoice::LifetimeLearning => true,
    };
    let e = &record.expenses;
    let more = StudentMore {
        books_from_school: e.school_materials,
        other_books: e.other_materials,
        refunds: e.refunds,
        tax_free_529: e.other_benefits,
        scholarship_in_income: e.scholarship_in_income.clone(),
        american_opportunity_used_up: false,
    };
    Some(StudentCredit {
        student,
        tuition: e.tuition,
        scholarships: e.assistance,
        half_time: true,
        graduate,
        more,
    })
}
// A filer or a person you support who is a student: the credits hub suggests
// the education topic.
fn student_on_return(d: &FederalDraft) -> bool {
    d.people.as_ref().is_some_and(|p| {
        p.taxpayer.full_time_student || p.spouse.as_ref().is_some_and(|s| s.full_time_student)
    }) || d.dependents().iter().any(|v| v.student())
}
// W-2 box 12 elective deferrals and designated Roth contributions (codes D,
// E, F, G, S, AA, BB and EE) of one owner: Form 8880 line 2.
fn saver_box12(d: &FederalDraft, owner: Owner) -> i64 {
    d.income
        .iter()
        .filter(|e| e.owner == owner)
        .map(|e| match &e.income {
            FederalIncome::Wage { data } => data
                .other_box12
                .iter()
                .filter(|c| {
                    matches!(
                        c.code,
                        W2Code::D
                            | W2Code::E
                            | W2Code::F
                            | W2Code::G
                            | W2Code::S
                            | W2Code::AA
                            | W2Code::BB
                            | W2Code::EE
                    )
                })
                .map(|c| c.amount)
                .sum(),
            _ => 0,
        })
        .sum()
}
fn saver_from_w2(d: &FederalDraft) -> Vec<SaverContribution> {
    [Owner::Taxpayer, Owner::Spouse]
        .into_iter()
        .map(|owner| SaverContribution { owner, amount: saver_box12(d, owner) })
        .filter(|c| c.amount != 0)
        .collect()
}
// The saver's credit is offered whenever the return's facts let it apply:
// the AGI inside Form 8880's bands for the filing status (a recorded credit
// stays offered so it can be changed). A contribution is not a gate: the
// page itself asks for contributions no other page records (ABLE, plans
// outside W-2 box 12). It is suggested (derived) only when a contribution
// is already on the return (box 12 deferrals or IRA contributions).
fn saver_offered(d: &FederalDraft) -> bool {
    d.credits.as_ref().is_some_and(|c| c.saver.is_some()) || saver_band(d)
}
fn saver_hint(d: &FederalDraft) -> bool {
    let contribution = saver_box12(d, Owner::Taxpayer) != 0
        || saver_box12(d, Owner::Spouse) != 0
        || d.adjustments.as_ref().is_some_and(|a| a.entered_iras().is_some());
    contribution && saver_band(d)
}
fn saver_band(d: &FederalDraft) -> bool {
    let Some(status) = d.setup.as_ref().map(|s| s.filing_status()) else {
        return false;
    };
    // An AGI the estimate cannot state yet does not hide the topic.
    estimate(d).lines.iter().find(|l| l.id == "agi").is_none_or(|l| {
        crate::federal_rules::saver_rate(crate::kernel::ratio::trunc_i64(l.amount, 100), status) > 0
    })
}
// The saver page's value for the stored credit: the workplace rows derived
// from box 12, the other contributions as what the stored total adds to them.
// None for a record this page does not write (unconfirmed answers, spouse
// contributions not from a W-2).
fn saver_item(d: &FederalDraft) -> Option<SaverCredit> {
    let from_w2 = saver_from_w2(d);
    let Some(facts) = d.credits.as_ref().and_then(|c| c.saver.as_ref()) else {
        return Some(SaverCredit {
            from_w2,
            distributions: Vec::new(),
            more: SaverMore::default(),
        });
    };
    let other_contributions = facts.taxpayer_contributions - saver_box12(d, Owner::Taxpayer);
    if other_contributions < 0 || facts.spouse_contributions != saver_box12(d, Owner::Spouse) {
        return None;
    }
    let spouse_able = facts.spouse_able;
    Some(SaverCredit {
        from_w2,
        distributions: facts.distributions.clone(),
        more: SaverMore { your_able: facts.taxpayer_able, spouse_able, other_contributions },
    })
}
// The page onto FederalSaver: contributions are box 12 deferrals plus the
// other contributions; choosing the page is the eligibility, ABLE and
// distribution-lookback confirmation.
fn saver_record(d: &FederalDraft, value: &SaverCredit) -> FederalSaver {
    let SaverMore { your_able, spouse_able, other_contributions } = value.more;
    FederalSaver {
        taxpayer_contributions: saver_box12(d, Owner::Taxpayer) + other_contributions,
        spouse_contributions: saver_box12(d, Owner::Spouse),
        taxpayer_able: your_able,
        spouse_able,
        distributions: value.distributions.clone(),
    }
}
// A changed W-2 re-derives the saver's workplace contributions: the part of
// each stored total not from box 12 is kept, the box 12 part follows the
// W-2s (the wages page erases nothing).
fn follow_saver(before: &FederalDraft, d: &mut FederalDraft) {
    let (taxpayer, spouse) = (saver_box12(d, Owner::Taxpayer), saver_box12(d, Owner::Spouse));
    let (was_taxpayer, was_spouse) =
        (saver_box12(before, Owner::Taxpayer), saver_box12(before, Owner::Spouse));
    if let Some(facts) = d.credits.as_mut().and_then(|c| c.saver.as_mut()) {
        facts.taxpayer_contributions =
            taxpayer + phase::floor(facts.taxpayer_contributions - was_taxpayer, 0);
        facts.spouse_contributions =
            spouse + phase::floor(facts.spouse_contributions - was_spouse, 0);
    }
}
// The Form 1095-A page (T2-27p). The page is policy-major (one Form 1095-A,
// its months); the store is month-major (MarketplaceClaim::Yes, each month
// listing its policies). These functions transpose both ways.
fn filing_status(d: &FederalDraft) -> FederalStatus {
    d.setup.as_ref().map_or(FederalStatus::Single, |s| s.filing_status())
}
// Form 8962 Part IV choices this return offers: a former spouse's share
// only off a joint return, a spouse's share only on a separate return.
// Form 8962 line A is asked only on a separate return, where it has no
// default: the filer answers No or Yes.
fn allowed_separate(status: FederalStatus) -> Vec<i32> {
    if status == FederalStatus::Separate {
        alloc::vec![SeparateRelief::No as i32, SeparateRelief::Yes as i32]
    } else {
        alloc::vec![SeparateRelief::NotSeparate as i32]
    }
}
// The people a dependent return can belong to: the people you support, in
// the people page's order. A dependent return of a person who left the return
// goes with the person (the save's prune), so no stale person is offered.
fn marketplace_people(d: &FederalDraft) -> Vec<crate::PersonChoice> {
    d.dependents()
        .iter()
        .map(|person| crate::PersonChoice {
            id: person.id,
            label: person.name(),
            valid_ssn: person.valid_ssn,
        })
        .collect()
}
struct MarketplaceCatalog {
    people: Vec<PersonChoice>,
    ptc_people: Vec<RecordChoice>,
    ptc_families: Vec<RecordChoice>,
    ptc_policies: Vec<RecordChoice>,
    ptc_w2: Vec<RecordChoice>,
    ptc_employees: Vec<RecordChoice>,
    ptc_nonreturn_people: Vec<RecordChoice>,
    ptc_claimed_dependents: Vec<RecordChoice>,
    allowed_marriage: Vec<i32>,
}
fn marketplace_catalog(d: &FederalDraft) -> MarketplaceCatalog {
    let facts = d.credits.as_ref().and_then(|c| crate::marketplace::facts(&c.marketplace));
    let family = crate::marketplace::family_people(d);
    let current = crate::federal_rules::people_students(d);
    let mut ptc_people: Vec<_> =
        current.iter().map(|p| RecordChoice { id: p.id, label: p.label.clone() }).collect();
    let ptc_employees = ptc_people
        .iter()
        .filter(|p| p.id == -1 || p.id == -2 && joint(d) || p.id > 0 && family.contains(&p.id))
        .cloned()
        .collect();
    let ptc_claimed_dependents =
        ptc_people.iter().filter(|p| p.id > 0 && family.contains(&p.id)).cloned().collect();
    let ptc_nonreturn_people =
        ptc_people.iter().filter(|p| !family.contains(&p.id)).cloned().collect();
    let choice = |id, label: alloc::string::String| RecordChoice {
        id,
        label: Message::new(
            "PTC_RECORD_CHOICE",
            alloc::vec![MessageArg::Text(label), MessageArg::Number(id)],
        )
        .encode(),
    };
    ptc_people.extend(facts.into_iter().flat_map(|f| &f.covered).map(|p| {
        choice(
            p.id,
            match &p.identity {
                MarketplacePersonIdentity::OtherFamily { label, .. }
                | MarketplacePersonIdentity::NoFamily { label } => label.clone(),
            },
        )
    }));
    let ptc_families = facts
        .into_iter()
        .flat_map(|f| &f.other_families)
        .map(|f| choice(f.id, f.label.clone()))
        .collect();
    let ptc_policies = facts
        .into_iter()
        .flat_map(|f| &f.forms)
        .filter(|p| p.status != MarketplaceStatementStatus::Void)
        .map(|p| choice(p.id, alloc::format!("{} {}", p.issuer, p.policy_number)))
        .collect();
    let w2 = crate::marketplace::w2_sources(d);
    let ptc_w2 = d
        .income
        .iter()
        .filter(|e| w2.iter().any(|(id, _, _)| *id == e.id))
        .map(source_choice)
        .collect();
    let mut allowed_marriage =
        alloc::vec![libertas_macros::variant_index!(MarketplaceMarriagePage::Regular) as i32];
    if joint(d) {
        allowed_marriage
            .push(libertas_macros::variant_index!(MarketplaceMarriagePage::Alternative) as i32);
    }
    MarketplaceCatalog {
        people: marketplace_people(d),
        ptc_people,
        ptc_families,
        ptc_policies,
        ptc_w2,
        ptc_employees,
        ptc_nonreturn_people,
        ptc_claimed_dependents,
        allowed_marriage,
    }
}
fn marketplace_value(d: &FederalDraft) -> MarketplaceFactsPage {
    d.credits
        .as_ref()
        .and_then(|c| crate::marketplace::facts(&c.marketplace))
        .cloned()
        .map(Into::into)
        .unwrap_or_default()
}
// The hub and review row: "1 Form 1095-A · credit $1,234.00" or
// "· repay $567.00"; None without a claim.
fn marketplace_status(d: &FederalDraft, result: &FederalResult) -> Option<Vec<u8>> {
    let facts = crate::marketplace::facts(&d.credits.as_ref()?.marketplace)?;
    let count =
        facts.forms.iter().filter(|p| p.status != MarketplaceStatementStatus::Void).count() as i64;
    let line = |id: &str| result.lines.iter().find(|l| l.id == id).map(|l| l.amount);
    let (key, amount) = match (line("premium_credit_refundable"), line("premium_credit_repayment"))
    {
        (_, Some(repay)) if repay > 0 => ("REVIEW_MARKETPLACE_REPAY", Some(repay)),
        (Some(credit), _) => ("REVIEW_MARKETPLACE_CREDIT", Some(credit)),
        _ => ("REVIEW_MARKETPLACE_COUNT", None),
    };
    let mut args = alloc::vec![LibertasMessageArgument::Plural(count)];
    if let Some(minor_units) = amount {
        args.push(LibertasMessageArgument::Currency {
            currency_code: "USD",
            scale: 2,
            minor_units,
        });
    }
    Some(libertas_formatted_text(key, &args))
}
// People with care costs on the people page: the credits hub's care row.
fn care_people(d: &FederalDraft) -> usize {
    d.dependents()
        .iter()
        .filter(|v| {
            v.use_for == crate::PersonUse::TaxDependent && !matches!(v.care, DependentCare::No)
        })
        .count()
}
// More credits (M3-P12): the stored FederalCredits fields this page exposes,
// one list item per field, in the struct's declaration order, and the home
// kerosene credit stored with the payments (u5-credits). A field this page
// does not cover (students, education, care, saver, marketplace,
// marketplace_dependents; mortgage_subsidies is the other taxes page's) is
// untouched here.
fn more_credit_items(d: &FederalDraft) -> Vec<MoreCredit> {
    let Some(credits) = d.credits.as_ref() else {
        return Vec::new();
    };
    let mut items = Vec::new();
    if let Some(value) = &credits.minimum_tax {
        items.push(MoreCredit::MinimumTax(value.clone().into()));
    }
    if let Some(value) = &credits.mortgage_credit {
        items.push(MoreCredit::MortgageCredit {
            current: value.current.clone(),
            carry_three_years_prior: value.carry_three_years_prior,
            carry_two_years_prior: value.carry_two_years_prior,
            carry_prior_year: value.carry_prior_year,
            loan: value.loan,
        });
    }
    if credits.residential_energy_carry.is_some() || credits.dc_homebuyer_carry.is_some() {
        items.push(MoreCredit::PriorCreditCarryovers {
            residential_energy_carry: credits.residential_energy_carry,
            dc_homebuyer_carry: credits.dc_homebuyer_carry,
        });
    }
    if credits.clean_vehicles.is_some() || !credits.personal_refueling.is_empty() {
        items.push(MoreCredit::CleanVehiclesAndRefueling {
            clean_vehicles: credits.clean_vehicles.clone().map(Into::into),
            personal_refueling: credits.personal_refueling.clone(),
        });
    }
    if !credits.adoptions.is_empty() || !credits.adoption_carry.is_empty() {
        items.push(MoreCredit::Adoption {
            adoptions: credits
                .adoptions
                .iter()
                .map(|c| c.page(&employee_wage_choices(d)))
                .collect(),
            adoption_carry: credits.adoption_carry.clone(),
        });
    }
    if !credits.exempt_pensions.is_empty() {
        items.push(MoreCredit::ElderlyOrDisabled {
            exempt_pensions: credits.exempt_pensions.clone(),
        });
    }
    if credits.foreign_tax != ForeignTaxClaim::No
        && let Ok(page) = ForeignTaxPage::try_from(credits.foreign_tax.clone())
    {
        items.push(MoreCredit::ForeignTax(page));
    }
    if !credits.tax_credit_bonds.is_empty() {
        items.push(MoreCredit::TaxCreditBonds {
            tax_credit_bonds: credits.tax_credit_bonds.iter().cloned().map(Into::into).collect(),
        });
    }
    if credits.legacy_ev_passive_allowed.is_some() {
        items.push(MoreCredit::ElectricVehicleCarryover {
            legacy_ev_passive_allowed: credits.legacy_ev_passive_allowed,
        });
    }
    if let Some(value) = &credits.tip_fica_carryforward {
        items.push(MoreCredit::EmployerTip(value.clone()));
    }
    if let Some(value) = &credits.business_credits {
        items.push(MoreCredit::BusinessCredits(value.clone().into()));
    }
    if let Some(value) = &credits.bba_audit_interest {
        items.push(MoreCredit::BbaAuditAdjustment(value.clone()));
    }
    if let Some(value) = &credits.education_recapture {
        items.push(MoreCredit::EducationRecapture(value.clone()));
    }
    if let Some(value) = &credits.after_disallowance {
        items.push(MoreCredit::AfterDisallowance(value.clone()));
    }
    if let Some(value) = d.payments.as_ref().and_then(|p| p.home_kerosene.as_ref()) {
        items.push(MoreCredit::HomeKerosene(value.clone()));
    }
    if credits.decline_earned_income_credit {
        items.push(MoreCredit::DeclineEarnedIncomeCredit);
    }
    items
}
// More adjustments (unit u5-adjust): the alimony rows, the moving rows (Form
// 3903), then the refusal kinds chosen, stored as they were chosen.
fn more_adjustment_items(d: &FederalDraft) -> Vec<MoreAdjustment> {
    d.adjustments
        .iter()
        .flat_map(|a| &a.alimony_paid)
        .map(|v| {
            MoreAdjustment::AlimonyPaid(AlimonyItem { owner: v.owner, payment: v.payment.clone() })
        })
        .chain(d.adjustments.iter().flat_map(|a| &a.moving).map(|m| {
            MoreAdjustment::MovingExpenses(crate::MovingItem {
                owner: m.owner,
                record: m.record.clone(),
            })
        }))
        .chain(d.adjustment_refusals.iter().cloned())
        .collect()
}
// Both AlimonyPayment entry paths share these existing recapture checks.
fn alimony_issue(payment: &crate::AlimonyPayment) -> Option<ValidationIssue> {
    match &payment.recapture {
        crate::AlimonyRecapture::ThirdYear { first, first_excluded, .. }
            if first_excluded > first =>
        {
            Some(
                ValidationIssue::new("ALIMONY_2024_EXCLUDED_ABOVE_PAID")
                    .at_field("first_excluded")
                    .in_field("recapture"),
            )
        }
        crate::AlimonyRecapture::ThirdYear { second, second_excluded, .. }
            if second_excluded > second =>
        {
            Some(
                ValidationIssue::new("ALIMONY_2025_EXCLUDED_ABOVE_PAID")
                    .at_field("second_excluded")
                    .in_field("recapture"),
            )
        }
        _ => None,
    }
}
// Other taxes (u5-credits): the stored records the page owns, one list
// item per kind (Schedule H employers, Trump accounts, Form 8828 homes),
// then its refusal kinds, stored as they were chosen.
fn other_tax_items(d: &FederalDraft) -> Vec<OtherTax> {
    let mut items = Vec::new();
    if let Some(screening) = d.screening.as_ref() {
        if !screening.household_employment.is_empty() {
            items.push(OtherTax::HouseholdEmployees {
                employers: screening.household_employment.clone(),
            });
        }
        if !screening.trump_accounts.is_empty() {
            items.push(OtherTax::TrumpAccounts { accounts: screening.trump_accounts.clone() });
        }
    }
    if let Some(credits) = d.credits.as_ref()
        && !credits.mortgage_subsidies.is_empty()
    {
        items
            .push(OtherTax::MortgageSubsidyRecapture { homes: credits.mortgage_subsidies.clone() });
    }
    if !d.coverdell_excess.is_empty() {
        items.push(OtherTax::CoverdellExcess {
            beneficiaries: d.coverdell_excess.iter().cloned().map(Into::into).collect(),
        });
    }
    items.extend(d.tax_refusals.iter().cloned().map(Into::into));
    items
}
// The list onto the records it owns: a kind absent from the list clears
// its field. Two items of the same kind keep the last one entered.
fn apply_other_taxes(d: &mut FederalDraft, items: &[OtherTax]) {
    let mut employers = Vec::new();
    let mut accounts = Vec::new();
    let mut homes = Vec::new();
    let mut coverdell = Vec::new();
    for item in items {
        match item {
            OtherTax::CoverdellExcess { beneficiaries } => {
                coverdell = beneficiaries.iter().cloned().map(Into::into).collect();
            }
            OtherTax::HouseholdEmployees { employers: value } => employers = value.clone(),
            OtherTax::TrumpAccounts { accounts: value } => accounts = value.clone(),
            OtherTax::MortgageSubsidyRecapture { homes: value } => homes = value.clone(),
            // The refusal kinds are stored in tax_refusals (other_taxes_candidate).
            OtherTax::AlternativeMinimumTax
            | OtherTax::HousingCreditRecapture
            | OtherTax::Section965
            | OtherTax::OtherAdditionalTaxes { .. } => {}
        }
    }
    d.coverdell_excess = coverdell;
    if let Some(screening) = d.screening.as_mut() {
        screening.household_employment = employers;
        screening.trump_accounts = accounts;
    }
    if let Some(credits) = d.credits.as_mut() {
        credits.mortgage_subsidies = homes;
    }
}
// A Form 8828 sale names its home sale entry by a hidden ID: a row keeps
// an ID that is one of the return's home sales, and the others take the
// unused home sale closing on the row's disposition date, else the first
// unused one; a row with no home sale left keeps 0, which the estimate
// names (the sale is entered on Investment sales). Derived on every save
// (follow_home_sales), so a sale entered after the Form 8828 row binds.
fn bind_home_sales(d: &FederalDraft, homes: &mut [MortgageSubsidyEntry]) {
    let sales: Vec<i64> = d
        .income
        .iter()
        .filter(|e| matches!(e.income, FederalIncome::HomeSale { .. }))
        .map(|e| e.id)
        .collect();
    let closed = |id: i64| {
        d.income.iter().find_map(|e| match &e.income {
            FederalIncome::HomeSale { data } if e.id == id => data.facts.as_ref().map(|f| f.closed),
            _ => None,
        })
    };
    let mut used: Vec<i64> = Vec::new();
    let mut kept = alloc::vec![false; homes.len()];
    for (home, kept) in homes.iter_mut().zip(kept.iter_mut()) {
        if let Some(id) = sale_id(home)
            && sales.contains(id)
            && !used.contains(id)
        {
            used.push(*id);
            *kept = true;
        }
    }
    for (home, kept) in homes.iter_mut().zip(kept) {
        let disposed = match &home.disposition {
            MortgageSubsidyDisposition::Ordinary { facts, .. } => Some(facts.disposed_on),
            _ => None,
        };
        let Some(id) = sale_id(home).filter(|_| !kept) else {
            continue;
        };
        let unused = || sales.iter().filter(|s| !used.contains(s));
        match unused()
            .find(|s| disposed.is_some() && closed(**s) == disposed)
            .or_else(|| unused().next())
        {
            Some(next) => {
                *id = *next;
                used.push(*next);
            }
            None => *id = 0,
        }
    }
}
// Form 8828's hidden home sale IDs follow the return's home sales (a
// derived value of every save, u6-home).
fn follow_home_sales(d: &mut FederalDraft) {
    let Some(mut homes) = d.credits.as_ref().map(|c| c.mortgage_subsidies.clone()) else {
        return;
    };
    bind_home_sales(d, &mut homes);
    if let Some(credits) = d.credits.as_mut() {
        credits.mortgage_subsidies = homes;
    }
}
fn sale_id(home: &mut MortgageSubsidyEntry) -> Option<&mut i64> {
    match &mut home.disposition {
        MortgageSubsidyDisposition::Ordinary {
            transfer: MortgageSubsidyTransfer::Sale { home_sale_income_id, .. },
            ..
        } => Some(home_sale_income_id),
        _ => None,
    }
}
// The list onto FederalCredits (and the payments' home kerosene): a variant
// absent from the list clears its field(s), matching the platform's
// ordinary "the list is the whole answer" save contract. Two items of the
// same kind keep the last one entered; the client's chooser makes that
// pairing unlikely, and no page elsewhere reads these fields between save
// and the next open.
fn apply_more_credits(d: &mut FederalDraft, items: &[MoreCredit]) {
    let kerosene = items.iter().rev().find_map(|item| match item {
        MoreCredit::HomeKerosene(value) => Some(value.clone()),
        _ => None,
    });
    if kerosene.is_some() || d.payments.is_some() {
        let joint = joint(d);
        d.payments
            .get_or_insert_with(|| FederalPayments { joint, ..FederalPayments::none() })
            .home_kerosene = kerosene;
    }
    let Some(credits) = d.credits.as_mut() else {
        return;
    };
    credits.decline_earned_income_credit = false;
    credits.minimum_tax = None;
    credits.mortgage_credit = None;
    credits.residential_energy_carry = None;
    credits.dc_homebuyer_carry = None;
    credits.clean_vehicles = None;
    credits.personal_refueling = Vec::new();
    credits.adoptions = Vec::new();
    credits.adoption_carry = Vec::new();
    credits.exempt_pensions = Vec::new();
    credits.foreign_tax = ForeignTaxClaim::No;
    credits.tax_credit_bonds = Vec::new();
    credits.legacy_ev_passive_allowed = None;
    credits.tip_fica_carryforward = None;
    credits.business_credits = None;
    credits.bba_audit_interest = None;
    credits.education_recapture = None;
    credits.after_disallowance = None;
    for item in items {
        match item.clone() {
            MoreCredit::MinimumTax(value) => credits.minimum_tax = Some(value.into()),
            MoreCredit::MortgageCredit {
                current,
                carry_three_years_prior,
                carry_two_years_prior,
                carry_prior_year,
                loan,
            } => {
                credits.mortgage_credit = Some(FederalMortgageCredit {
                    current,
                    carry_three_years_prior,
                    carry_two_years_prior,
                    carry_prior_year,
                    loan,
                })
            }
            MoreCredit::PriorCreditCarryovers { residential_energy_carry, dc_homebuyer_carry } => {
                credits.residential_energy_carry = residential_energy_carry;
                credits.dc_homebuyer_carry = dc_homebuyer_carry;
            }
            MoreCredit::CleanVehiclesAndRefueling { clean_vehicles, personal_refueling } => {
                credits.clean_vehicles = clean_vehicles.map(Into::into);
                credits.personal_refueling = personal_refueling;
            }
            MoreCredit::Adoption { adoptions, adoption_carry } => {
                credits.adoptions = adoptions.iter().map(|c| c.record()).collect();
                credits.adoption_carry = adoption_carry;
            }
            MoreCredit::ElderlyOrDisabled { exempt_pensions } => {
                credits.exempt_pensions = exempt_pensions;
            }
            MoreCredit::ForeignTax(value) => credits.foreign_tax = value.clone().into(),
            MoreCredit::TaxCreditBonds { tax_credit_bonds } => {
                credits.tax_credit_bonds = tax_credit_bonds.into_iter().map(Into::into).collect();
            }
            MoreCredit::ElectricVehicleCarryover { legacy_ev_passive_allowed } => {
                credits.legacy_ev_passive_allowed = legacy_ev_passive_allowed;
            }
            MoreCredit::EmployerTip(value) => credits.tip_fica_carryforward = Some(value),
            MoreCredit::BusinessCredits(value) => credits.business_credits = Some(value.into()),
            MoreCredit::BbaAuditAdjustment(value) => credits.bba_audit_interest = Some(value),
            MoreCredit::EducationRecapture(value) => credits.education_recapture = Some(value),
            MoreCredit::AfterDisallowance(value) => credits.after_disallowance = Some(value),
            // Stored with the payments, above.
            MoreCredit::HomeKerosene(_) => {}
            // The refusal kinds are stored as situations (more_credits_candidate).
            MoreCredit::DeclineEarnedIncomeCredit => credits.decline_earned_income_credit = true,
            MoreCredit::OtherCredit => {}
        }
    }
}
// The review's "Credits" count: care, education, the saver's credit and any
// more-credits entry.
// The accepted return without Form 2210: the lines the payments pages show
// or derive (withholding, Schedule AI column (d)) do not depend on the
// penalty, and a Form 2210 answer still being entered (box C before its
// periods) must not hide them.
fn return_before_penalty(d: &FederalDraft) -> FederalResult {
    let mut d = d.clone();
    if let Some(pay) = d.payments.as_mut() {
        pay.prior_year = None;
    }
    estimate(&d)
}
// A Form 1040 line of a calculated return, in cents; 0 when absent.
fn form_1040_line(result: &FederalResult, reference: &str) -> i64 {
    result
        .return_lines
        .iter()
        .find(|l| {
            l.form_line.as_ref().is_some_and(|f| f.form == TaxForm::Form1040 && f.line == reference)
        })
        .map_or(0, |l| l.amount)
}
// A calculation line of a calculated return, in cents; 0 when absent.
fn calculation_line(result: &FederalResult, id: &str) -> i64 {
    result.lines.iter().find(|l| l.id == id).map_or(0, |l| l.amount)
}
// Form 1040 lines 25a-25d of the accepted return, in cents: the payments
// page shows them and the box D periods must add up to line 25d.
fn withheld(d: &FederalDraft) -> Option<Withheld> {
    return_before_penalty(d).payment_withholding
}
// Schedule AI column (d) from the accepted return (M3-P14): AGI (Form 1040
// line 11), the itemized deductions taken (line 12e, 0 with the standard
// deduction), the Schedule 1-A deductions (line 13a), the QBI deduction
// (line 13b), and the net profit and Social Security wages of the person
// with self-employment tax.
fn full_year_period(d: &FederalDraft) -> AnnualizedPeriod {
    let result = return_before_penalty(d);
    AnnualizedPeriod {
        agi: form_1040_line(&result, "11a / 11b"),
        itemized: calculation_line(&result, "schedule_ai_full_year_itemized"),
        qbi: form_1040_line(&result, "13b"),
        additional: form_1040_line(&result, "13a"),
        self_employment: calculation_line(&result, "schedule_ai_full_year_self_employment"),
        social_wages: calculation_line(&result, "schedule_ai_full_year_social_wages"),
    }
}
// The full year spread evenly through a period ending after `months`: the
// page's starting values before the filer enters the actual amounts, which
// annualize back to the full year, so the election changes nothing until
// they are entered.
fn even_period(full: &AnnualizedPeriod, months: i64) -> AnnualizedPeriod {
    use crate::kernel::ratio::fraction;
    AnnualizedPeriod {
        agi: fraction(full.agi, months, 12),
        itemized: fraction(full.itemized, months, 12),
        qbi: fraction(full.qbi, months, 12),
        additional: fraction(full.additional, months, 12),
        self_employment: fraction(full.self_employment, months, 12),
        social_wages: fraction(full.social_wages, months, 12),
    }
}
// Box C (the annualized income installment method) is chosen.
fn box_c(d: &FederalDraft) -> bool {
    d.payments.as_ref().is_some_and(|p| p.annualized)
}
// Column (d) follows the return: every accepted change re-derives it, so
// the stored Schedule AI record always reconciles to the return.
fn follow_full_year(d: &mut FederalDraft) {
    if d.payments.as_ref().is_some_and(|p| p.annualized_income.is_some()) {
        let full = full_year_period(d);
        if let Some(periods) = d.payments.as_mut().and_then(|p| p.annualized_income.as_mut()) {
            periods.full_year = full;
        }
    }
}
fn waiver_record(waiver: &Waiver) -> Option<PenaltyWaiver> {
    match waiver {
        Waiver::None => None,
        Waiver::Full { reason, explanation } => {
            Some(PenaltyWaiver::Full { reason: *reason, explanation: explanation.clone() })
        }
        Waiver::Partial { reason, explanation, amount } => Some(PenaltyWaiver::Partial {
            reason: *reason,
            explanation: explanation.clone(),
            amount: *amount,
        }),
    }
}
fn waiver_item(waiver: &Option<PenaltyWaiver>) -> Waiver {
    match waiver {
        None => Waiver::None,
        Some(PenaltyWaiver::Full { reason, explanation }) => {
            Waiver::Full { reason: *reason, explanation: explanation.clone() }
        }
        Some(PenaltyWaiver::Partial { reason, explanation, amount }) => {
            Waiver::Partial { reason: *reason, explanation: explanation.clone(), amount: *amount }
        }
    }
}
// The stored Form 2210 facts as the page's penalty choice; None when the
// record holds a shape this page could not have written.
// The stored 2027 estimate as the payments page shows it (T2-49c): the
// farmer and fisherman answer inside the set the page offers, "Not needed"
// when 2026 qualifies, and a stored "Not needed" that no longer applies
// constructed as an unanswered required choice.
fn next_year_item(
    stored: &crate::NextYearEstimateRecord,
    farming_return_year: bool,
) -> Option<NextYearEstimate> {
    if !farming_return_year
        && matches!(
            NextYearEstimate::from(stored.clone()),
            NextYearEstimate::SameAsThisReturn {
                farmer_fisherman_next_year: FarmerNextYear::NotNeeded
            } | NextYearEstimate::WithChanges {
                farmer_fisherman_next_year: FarmerNextYear::NotNeeded,
                ..
            }
        )
    {
        return None;
    }
    let shown = |answer: FarmerNextYear| match (farming_return_year, answer) {
        (true, _) => FarmerNextYear::NotNeeded,
        (false, FarmerNextYear::NotNeeded) => FarmerNextYear::NotNeeded,
        (false, answer) => answer,
    };
    let mut item = NextYearEstimate::from(stored.clone());
    match &mut item {
        NextYearEstimate::NotNeeded => {}
        NextYearEstimate::SameAsThisReturn { farmer_fisherman_next_year }
        | NextYearEstimate::WithChanges { farmer_fisherman_next_year, .. } => {
            *farmer_fisherman_next_year = shown(*farmer_fisherman_next_year)
        }
    }
    Some(item)
}
fn penalty_item(pay: &FederalPayments, farming_return_year: bool) -> Option<PenaltyChoice> {
    let Some(prior) = &pay.prior_year else {
        let untouched = !pay.withholding_by_date
            && pay.withholding_periods.is_none()
            && !pay.annualized
            && pay.annualized_income.is_none()
            && !pay.farmer_fisherman_prior_year
            && !pay.farmer_paid_by_march
            && pay.waiver.is_none();
        return untouched.then_some(PenaltyChoice::IrsFigures);
    };
    let withholding = match (pay.withholding_by_date, &pay.withholding_periods) {
        (false, None) => WithholdingTiming::Evenly,
        (true, Some(p)) => WithholdingTiming::ByPeriod {
            first: p.first,
            second: p.second,
            third: p.third,
            fourth: p.fourth,
        },
        _ => return None,
    };
    let income = match (pay.annualized, &pay.annualized_income) {
        (true, _) => IncomeTiming::ByPeriod,
        (false, None) => IncomeTiming::Evenly,
        (false, Some(_)) => return None,
    };
    // 2026 figured from this return decides first; the 2025 answer is shown
    // only when 2026 does not qualify, and the March 1 answer only with Yes.
    let farmer = match (farming_return_year, pay.farmer_fisherman_prior_year) {
        (true, _) => Farmer::ThisReturn { paid_by_march_1: pay.farmer_paid_by_march },
        (false, false) => Farmer::No,
        (false, true) => Farmer::Yes { paid_by_march_1: pay.farmer_paid_by_march },
    };
    Some(PenaltyChoice::Figure {
        prior_tax: prior.tax,
        prior_agi: prior.agi,
        full_year: prior.full_year,
        prior_return: match prior.spouse_tax {
            0 => PriorReturn::SameReturn,
            spouse_tax => PriorReturn::SeparateReturns { spouse_tax },
        },
        withholding,
        income,
        farmer,
        waiver: waiver_item(&pay.waiver),
    })
}
// The page onto FederalPayments: the estimated amount is the dated list's
// total; IrsFigures leaves every Form 2210 fact empty; box C keeps the
// income by period already entered, Evenly erases it. Home kerosene is not
// on this page and is kept.
fn payments_record(value: &Payments, kept: &FederalPayments) -> FederalPayments {
    let mut pay = FederalPayments {
        credit_applied_next_year: value.credit_applied_next_year,
        credit_recipient: value.credit_recipient,
        estimated: Some(0),
        extension: value.extension,
        home_kerosene: kept.home_kerosene.clone(),
        estimated_payments: value
            .estimated
            .iter()
            .map(crate::InjuredDatedPayment::accepted)
            .collect(),
        extension_payer: value.extension_payer,
        extension_refund_property: value
            .extension_refund_property
            .as_ref()
            .map(crate::RefundSourceProperty::accepted),
        next_year: value.next_year.clone().into(),
        ..FederalPayments::none()
    };
    if let PenaltyChoice::Figure {
        prior_tax,
        prior_agi,
        full_year,
        prior_return,
        withholding,
        income,
        farmer,
        waiver,
    } = &value.penalty
    {
        pay.prior_year = Some(PriorYearTax {
            full_year: *full_year,
            tax: *prior_tax,
            agi: *prior_agi,
            spouse_tax: match prior_return {
                PriorReturn::SameReturn => 0,
                PriorReturn::SeparateReturns { spouse_tax } => *spouse_tax,
            },
        });
        if let WithholdingTiming::ByPeriod { first, second, third, fourth } = withholding {
            pay.withholding_by_date = true;
            pay.withholding_periods = Some(PeriodWithholding {
                first: *first,
                second: *second,
                third: *third,
                fourth: *fourth,
            });
        }
        if *income == IncomeTiming::ByPeriod {
            pay.annualized = true;
            pay.annualized_income = kept.annualized_income.clone();
        }
        // The 2025 answer is Yes only when chosen; with 2026 from this return
        // it is not asked and stays No.
        match farmer {
            Farmer::No => {}
            Farmer::Yes { paid_by_march_1 } => {
                pay.farmer_fisherman_prior_year = true;
                pay.farmer_paid_by_march = *paid_by_march_1;
            }
            Farmer::ThisReturn { paid_by_march_1 } => {
                pay.farmer_paid_by_march = *paid_by_march_1;
            }
        }
        pay.waiver = waiver_record(waiver);
    }
    pay.refresh_estimated_projection();
    pay
}
fn payments_count(pay: &FederalPayments) -> usize {
    pay.estimated_payments.len() + usize::from(pay.extension != 0)
}
fn credits_count(d: &FederalDraft) -> usize {
    let credits = d.credits.as_ref();
    usize::from(care_people(d) != 0)
        + usize::from(credits.is_some_and(|c| !c.education.is_empty()))
        + usize::from(credits.is_some_and(|c| c.saver.is_some()))
        + usize::from(
            credits.is_some_and(|c| matches!(c.marketplace, MarketplaceClaim::Yes { .. })),
        )
        + usize::from(!more_credit_items(d).is_empty() || !d.credit_refusals.is_empty())
}
// The position of a page in the sequence: TaxSection is declared in
// sequence order (M3-P19), and the income by period page belongs to the
// payments section.
fn rank(page: i32) -> i32 {
    match page {
        INCOME_BY_PERIOD_PAGE => PAYMENTS_PAGE,
        PARENT_TAX_PAGE => OTHER_TAXES_PAGE,
        _ => page,
    }
}
// A hub's less-common row, shown once something is chosen there.
fn less_common_row(d: &FederalDraft, section: TaxSection) -> Option<ReviewItem> {
    less_common_status(d, section).map(|status| ReviewItem {
        item: section_message(section).encode(),
        status: status.encode(),
        section,
    })
}
// More adjustments' row (unit u5-adjust): a count for each kind that has
// entries (alimony agreements, moves), then the refusal kinds chosen, joined
// by one shared composition; None when nothing is chosen.
pub(crate) fn more_adjustments_row(d: &FederalDraft) -> Option<ReviewItem> {
    let counts = d.adjustments.as_ref().map_or([0; 2], |a| [a.alimony_paid.len(), a.moving.len()]);
    let mut parts: Vec<Vec<u8>> = ["REVIEW_ALIMONY", "REVIEW_MOVES"]
        .into_iter()
        .zip(counts)
        .filter(|(_, n)| *n > 0)
        .map(|(key, n)| status_count(key, n))
        .collect();
    parts.extend(less_common_status(d, TaxSection::MoreAdjustments).map(|r| r.encode()));
    let status = parts.into_iter().reduce(|joined, next| {
        libertas_formatted_text(
            "REVIEW_STATUS_JOIN",
            &[
                LibertasMessageArgument::formatted_text(&joined),
                LibertasMessageArgument::formatted_text(&next),
            ],
        )
    })?;
    Some(ReviewItem {
        item: section_message(TaxSection::MoreAdjustments).encode(),
        status,
        section: TaxSection::MoreAdjustments,
    })
}
// The stored situations a page offers, in declaration order.
fn situations_of(
    d: &FederalDraft,
    section: TaxSection,
) -> impl Iterator<Item = RareSituation> + '_ {
    d.situations.iter().copied().filter(move |s| s.destination().0 == section)
}
// A less-common row names what was chosen: "Farming, Gambling winnings —
// not calculated yet"; None when nothing is.
fn less_common_status(d: &FederalDraft, section: TaxSection) -> Option<crate::Message> {
    let mut topics: Vec<&'static str> = Vec::new();
    for refusal in d.refusals().filter(|r| r.section == section) {
        let topic = refusal.topic_key;
        if !topics.contains(&topic) {
            topics.push(topic);
        }
    }
    (!topics.is_empty()).then(|| {
        crate::Message::new(
            "SUMMARY_TOPICS_NOT_CALCULATED",
            alloc::vec![crate::MessageArg::Nested(alloc::boxed::Box::new(message_list(
                &topics
                    .into_iter()
                    .map(|key| crate::Message::new(key, alloc::vec![]))
                    .collect::<Vec<_>>(),
            ))),],
        )
    })
}
