    // Choices come only from accepted first-lender records, never echoed catalogs.
    fn rental_energy_buildings(&self) -> Vec<RecordChoice> {
        self.draft
            .income
            .iter()
            .flat_map(|entry| match &entry.income {
                FederalIncome::Rental { data } => data
                    .energy_buildings
                    .iter()
                    .map(|building| RecordChoice {
                        id: building.id,
                        label: Message::new(
                            "RENTAL_ENERGY_BUILDING_CHOICE",
                            alloc::vec![MessageArg::Text(building.building_source.clone())],
                        )
                        .encode(),
                    })
                    .collect::<Vec<_>>(),
                _ => Vec::new(),
            })
            .collect()
    }
    fn mortgage_choices(&self) -> Vec<RecordChoice> {
        self.draft
            .deductions
            .iter()
            .flat_map(|d| &d.mortgage)
            .filter(|loan| matches!(loan.details, MortgageLoanDetails::FirstLender(_)))
            .map(|loan| RecordChoice {
                id: loan.id,
                label: Message::new(
                    "MORTGAGE_SAVED_LOAN",
                    alloc::vec![
                        MessageArg::Number(loan.id),
                        if loan.property.is_empty() {
                            MessageArg::Resource("MORTGAGE_PROPERTY_UNNAMED".into())
                        } else {
                            MessageArg::Text(loan.property.clone())
                        },
                        MessageArg::DateOnly(i64::from(loan.incurred)),
                    ],
                )
                .encode(),
            })
            .collect()
    }
