    // The charity carryovers page, opened with its complete value. The
    // balances live on FederalDeductions directly, not the route's
    // ItemizedExpenses, so this only needs itemizing to be open, not `facts`.
    fn gift_carryovers_page(&self, review: bool) -> Reply {
        let d = &self.draft;
        if itemized_facts(d).is_none() {
            return problem_key("PROBLEM_SECTION_UNAVAILABLE_YET");
        }
        // itemized_facts above already confirmed d.deductions is Some.
        let ded = d.deductions.as_ref().unwrap();
        let appraisal_choices = appraisal_catalog(&ded.appraisals);
        let value = GiftCarryovers {
            gifts: ded.property_gifts.iter().cloned().map(Into::into).collect(),
            appraisals: ded.appraisals.clone(),
            appraisal_choices: appraisal_choices.clone(),
            carryovers: ded
                .charity_carryovers
                .iter()
                .cloned()
                .map(|record| {
                    let mut page = crate::CharityCarryoverPage::from(record);
                    page.allowed_research_parts = crate::retained_research::choices(
                        page.balance,
                        &crate::retained_research::available(d),
                    );
                    page.allowed_source_appreciation =
                        crate::retained_charity::appreciation_choices(
                            page.class,
                            page.balance,
                            page.appreciation,
                            ded.basis_election,
                            &crate::retained_research::available(d),
                        );
                    page
                })
                .collect(),
            basis_election: ded.basis_election,
            volunteer: ded.volunteer_expenses.clone(),
            less_common: less_common_rows(ded),
        };
        Reply::Edit(P::SaveGiftCarryovers {
            user: self.user,
            cookie: d.cookie.clone(),
            revision: d.revision,
            page: ITEMIZED_PAGE,
            previous: ITEMIZED_PAGE,
            review,
            estimate: self.estimate_now(),
            warnings: Vec::new(),
            progress: self.topic_progress(ITEMIZED_PAGE, Some(TaxSection::GiftCarryovers)),
            allowed_owners: self.allowed_owners(),
            appraisal_choices,
            document_facts: DocumentFacts { year: 2026 },
            retained_charity_k1s: crate::investment_interest::k1_sources(d),
            retained_charity_origins: crate::retained_charity::origin_choices(d),
            retained_research_choices: crate::retained_research::available(d),
            value,
        })
    }
    // Borrowing survives the deduction route; Schedule A-only controls retain their own eligibility.
    fn other_itemized_page(&self, review: bool) -> Reply {
        let d = &self.draft;
        let Some(deductions) = d.deductions.as_ref() else {
            return problem_key("PROBLEM_SECTION_UNAVAILABLE_YET");
        };
        let facts = itemized_facts(d);
        let mut investment_interest =
            deductions.investment_interest.as_ref().map(crate::InvestmentBorrowingPage::from);
        if let Some(value) = &mut investment_interest {
            for loan in &mut value.loans {
                loan.allowed_origin_choices = crate::investment_interest::loan_origin_choices(
                    d,
                    loan.source,
                    loan.carry,
                    loan.amt_carry,
                );
            }
        }
        // Each unrecovered annuity cost names its retirement income in the
        // catalog (T3-deduct).
        let contracts = annuity_contracts(d);
        let Some(annuity_losses) = d
            .deductions
            .as_ref()
            .map_or(&[][..], |v| &v.annuity_losses)
            .iter()
            .map(|loss| {
                let contract = contracts.iter().find(|c| c.id == loss.income_id)?.id;
                Some(FinalAnnuityLoss {
                    contract,
                    started: loss.started,
                    cost: loss.cost,
                    recovered: loss.recovered,
                    refunds: loss.refunds,
                    eligible: loss.eligible,
                })
            })
            .collect::<Option<Vec<_>>>()
        else {
            return problem_key("PROBLEM_UNDISPLAYABLE_STALE_ANNUITY_COST");
        };
        Reply::Edit(P::SaveOtherItemized {
            user: self.user,
            cookie: d.cookie.clone(),
            revision: d.revision,
            page: if itemizing(d) { ITEMIZED_PAGE } else { DEDUCTIONS_PAGE },
            previous: if itemizing(d) { ITEMIZED_PAGE } else { DEDUCTIONS_PAGE },
            review,
            estimate: self.estimate_now(),
            warnings: Vec::new(),
            progress: self.topic_progress(
                if itemizing(d) { ITEMIZED_PAGE } else { DEDUCTIONS_PAGE },
                Some(TaxSection::OtherItemized),
            ),
            allowed_owners: self.allowed_owners(),
            interest_sources: crate::investment_interest::sources(d),
            investment_k1_sources: crate::investment_interest::k1_sources(d),
            investment_origin_choices: crate::investment_interest::origin_choices(d),
            value: OtherItemized {
                investment_interest,
                investment_property_taxes: facts.map_or(0, |f| f.investment_property_taxes),
                investment_property_tax_owners: facts
                    .and_then(|f| f.investment_property_tax_owners),
                annuity_losses,
                other_lines: facts.map_or_else(Vec::new, |f| {
                    f.other_lines.iter().cloned().map(Into::into).collect()
                }),
                contracts,
                bond_instruments: crate::investment_statements::bond_instruments(d),
            },
        })
    }
    // What the credits hub offers: the previous section, the people page for
    // child and dependent care (only with dependents), education, the saver's
    // credit when it can apply, more credits, and the next section
    // ("Continue").
    fn credits_hub_sections(&self) -> Vec<i32> {
        let mut sections = alloc::vec![self.before_credits()];
        if !sections.contains(&CHECKLIST_PAGE) {
            sections.push(CHECKLIST_PAGE);
        }
        if in_walk(&self.draft, TaxSection::Children) {
            sections.push(CHILDREN_PAGE);
        }
        sections.extend(offered_topics(&self.draft, &CREDIT_TOPICS));
        sections.push(MORE_CREDITS_PAGE);
        sections.push(self.after_credits() as i32);
        sections
    }
    // The credits hub, topics in Schedule 3's order. It suggests education
    // while a student is on the return and the topic is not yet visited, then
    // the saver's credit while a contribution exists inside Form 8880's bands
    // and it is not yet visited, otherwise the next section. The child tax
    // credit and the earned income credit need no page.
    fn credits_hub(&self, review: bool) -> Reply {
        let d = &self.draft;
        let visited = |topic: TaxSection| d.finished_sections.contains(&topic);
        let students = d.credits.as_ref().map_or(0, |c| c.education.len());
        let saver = d.credits.as_ref().is_some_and(|c| c.saver.is_some());
        let result = estimate(d);
        let items = self.remaining_items(&result);
        let planned = planned_sections(d);
        let offered = self.credits_hub_sections();
        let hub_topics = hub_topics(TaxSection::Credits);
        let walk = walk_topics(d, TaxSection::Credits, &offered);
        let suggested = hub_suggestion(&hub_topics, &offered, &items, &walk, self.after_credits());
        let care = Some(if !visited(TaxSection::Care) {
            status("REVIEW_NOT_STARTED")
        } else if let Some(c) = d.credits.as_ref().filter(|c| c.care.active()) {
            let count = c.care.providers.len()
                + c.care.benefits.len()
                + c.care.grace.len()
                + c.care.own_business.len();
            if count > 0 {
                status_count("CARE_RECORDED_SOURCES", count)
            } else {
                status("REVIEW_RECORDED")
            }
        } else {
            status("REVIEW_NONE")
        });
        let education = match students {
            0 if suggested == TaxSection::Education => Some(status("REVIEW_NOT_STARTED")),
            0 if visited(TaxSection::Education) => Some(status("REVIEW_NONE")),
            0 => None,
            n => Some(status_count("REVIEW_STUDENTS", n)),
        };
        let saver_status = if saver {
            Some(status("REVIEW_RECORDED"))
        } else if suggested == TaxSection::Saver {
            Some(status("REVIEW_NOT_STARTED"))
        } else {
            None
        };
        let marketplace = match marketplace_status(d, &result) {
            Some(summary) => Some(summary),
            None if suggested == TaxSection::Marketplace => Some(status("REVIEW_NOT_STARTED")),
            None if visited(TaxSection::Marketplace) => Some(status("REVIEW_NONE")),
            None => None,
        };
        // More credits is never suggested (it covers rare, one-off credits);
        // its row always shows, "None" until something is added.
        let more_credits = more_credit_items(d).len() + d.credit_refusals.len();
        let more_credits_status = Some(match more_credits {
            0 => status("REVIEW_NONE"),
            n => status_count("REVIEW_CREDITS", n),
        });
        let topics = [
            ("SECTION_CARE", TaxSection::Care, care),
            (section_info(TaxSection::Education).1, TaxSection::Education, education),
            (section_info(TaxSection::Saver).1, TaxSection::Saver, saver_status),
            (section_info(TaxSection::Marketplace).1, TaxSection::Marketplace, marketplace),
            (section_info(TaxSection::MoreCredits).1, TaxSection::MoreCredits, more_credits_status),
        ]
        .into_iter()
        .filter_map(|(item, section, status)| {
            status.map(|status| ReviewItem {
                item: libertas_formatted_text(item, &[]),
                status,
                section,
            })
        })
        .collect();
        // Care is a required first visit when facts exist. Its initial row
        // remains Not started; accepted topics still show ordinary attention.
        let attention_topics = hub_topics
            .iter()
            .copied()
            .filter(|topic| *topic != TaxSection::Care || visited(*topic))
            .collect::<Vec<_>>();
        let topics = mark_attention(topics, &attention_topics, &items);
        let topics = with_checklist_rows(
            topics,
            &[
                TaxSection::Children,
                TaxSection::Education,
                TaxSection::Saver,
                TaxSection::Marketplace,
                TaxSection::MoreCredits,
            ],
            &offered,
            &planned,
        );
        let topics = with_every_destination(d, topics, TaxSection::Credits, &offered);
        let allowed_sections = self.allowed_sections();
        let navigation = self.navigation_availability(&allowed_sections);
        let allowed_actions = self.hub_actions(TaxSection::Credits);
        let primary_actions = Self::primary_actions(&allowed_actions);
        Reply::Response(P::Hub {
            cookie: d.cookie.clone(),
            revision: d.revision,
            page: CREDITS_PAGE,
            previous: offered[0],
            review,
            estimate: estimate_text(&result),
            progress: progress_line(
                CREDITS_PAGE,
                &shown_sections(d),
                walk.is_empty().then(|| done_with(TaxSection::Credits)),
            ),
            told: told_us(d, TaxSection::Credits),
            topics: hub_list(TaxSection::Credits, topics),
            previous_section: previous_section_row(self.before_credits()),
            navigation,
            suggested_destination: suggested.into(),
            primary_actions,
            go_to_actions: alloc::vec![libertas_macros::variant_index!(P::Navigate) as i32],
            allowed_actions,
            suggested,
            allowed_sections,
        })
    }
